/*  External Function declarations */
DECLARE EXTERNAL FUNCTION ASCII_CHAR 
INTEGER
RETURNS CSTRING(1) CHARACTER SET NONE FREE_IT
ENTRY_POINT 'IB_UDF_ascii_char' MODULE_NAME 'ib_udf';

DECLARE EXTERNAL FUNCTION F_REPLSTR 
CSTRING(254) CHARACTER SET NONE, CSTRING(254) CHARACTER SET NONE, CSTRING(254) CHARACTER SET NONE
RETURNS CSTRING(254) CHARACTER SET NONE FREE_IT
ENTRY_POINT 'ReplStr' MODULE_NAME 'FreeUDFLib';

DECLARE EXTERNAL FUNCTION TRUNCATE 
INTEGER BY DESCRIPTOR, INTEGER BY DESCRIPTOR
RETURNS PARAMETER 2
ENTRY_POINT 'fbtruncate' MODULE_NAME 'fbudf';


