/* Table: TMP_BETS, Owner: SYSDBA */
CREATE TABLE TMP_BETS (ID_RACE_ITEM ID,
        ID_EVENT_INVENTORY_ITEM TINTEGER,
        BIRD_DROP TINTEGER,
        BELGIAN_SHOW_1 TVALUE,
        BELGIAN_SHOW_2 TVALUE,
        BELGIAN_SHOW_3 TVALUE,
        BELGIAN_SHOW_4 TVALUE,
        BELGIAN_SHOW_5 TVALUE,
        BELGIAN_SHOW_6 TVALUE,
        BELGIAN_SHOW_7 TVALUE,
        STANDARD_SHOW_1 TVALUE,
        STANDARD_SHOW_2 TVALUE,
        STANDARD_SHOW_3 TVALUE,
        STANDARD_SHOW_4 TVALUE,
        STANDARD_SHOW_5 TVALUE,
        STANDARD_SHOW_6 TVALUE,
        WTA_1 TVALUE,
        WTA_2 TVALUE,
        WTA_3 TVALUE,
        WTA_4 TVALUE,
        WTA_5 TVALUE,
        TOTAL TVALUE,
        EXEC_TIME TDATETME NOT NULL,
CONSTRAINT PK_TMP_BETS PRIMARY KEY (ID_RACE_ITEM, EXEC_TIME));

/* Table: TMP_ID, Owner: SYSDBA */
CREATE TABLE TMP_ID (ID ID NOT NULL,
        TAG TEXT_100 NOT NULL,
CONSTRAINT PK_TMP_ID PRIMARY KEY (ID, TAG));

/* Table: USERS, Owner: SYSDBA */
CREATE TABLE USERS (ID_USER ID_TYPE NOT NULL,
        LOGIN_NAME LOGIN_NAME,
        FULL_NAME CONTRAGENT_MOL,
        "PASSWORD" "PASSWORD",
        IS_ACTIVE LOGICAL,
        EMAIL_ADDRESS TEMAIL_ADDRESS,
CONSTRAINT PK_USERS PRIMARY KEY (ID_USER),
CONSTRAINT UNQ1_USERS UNIQUE (LOGIN_NAME, "PASSWORD"));

/* Table: USER_RIGHT_GROUPS, Owner: SYSDBA */
CREATE TABLE USER_RIGHT_GROUPS (ID_USER_RIGHT_GROUP ID_TYPE NOT NULL,
        ID_USER ID_TYPE,
        ID_RIGHT_GROUP ID_TYPE,
CONSTRAINT PK_USER_RIGHT_GROUPS PRIMARY KEY (ID_USER_RIGHT_GROUP));

