/* View: BIRDS_VIEW, Owner: SYSDBA */
CREATE VIEW BIRDS_VIEW (ID_BIRD, BAND, BAND_1, BAND_2, BAND_3, BAND_4, BIRD_NAME, RF_ID, COLOR, SEX, IS_ACTIVE, IS_RACE_VERIFIED, IS_LOST, LOST_DATE, LOST_ID_RACE, NOTE, ID_PICTURE, PLAY_ATTENTION_SOUND) AS
 
select ID_BIRD,
       (select BAND_NUMBER from FORMAT_BAND_NUMBER(BAND_1, BAND_2, BAND_3, BAND_4)),
       BAND_1,
       BAND_2,
       BAND_3,
       BAND_4,
       BIRD_NAME,
       RF_ID,
       COLOR,
       SEX,
       IS_ACTIVE,
       IS_RACE_VERIFIED,
       IS_LOST,
       LOST_DATE,
       LOST_ID_RACE,
       NOTE,
       ID_PICTURE,
       PLAY_ATTENTION_SOUND
from BIRDS;

