ALTER PROCEDURE AUTO_BETS (ID_EVENT INTEGER)
AS 
DECLARE VARIABLE ID_EVENT_INVENTORY_ITEM INTEGER;
DECLARE VARIABLE BELGIAN_SHOW_BET_1 SMALLINT;
DECLARE VARIABLE BELGIAN_SHOW_BET_2 SMALLINT;
DECLARE VARIABLE BELGIAN_SHOW_BET_3 SMALLINT;
DECLARE VARIABLE BELGIAN_SHOW_BET_4 SMALLINT;
DECLARE VARIABLE BELGIAN_SHOW_BET_5 SMALLINT;
DECLARE VARIABLE STANDARD_SHOW_BET_1 SMALLINT;
DECLARE VARIABLE STANDARD_SHOW_BET_2 SMALLINT;
DECLARE VARIABLE STANDARD_SHOW_BET_3 SMALLINT;
DECLARE VARIABLE STANDARD_SHOW_BET_6 SMALLINT;
DECLARE VARIABLE WTA_BET_1 SMALLINT;
DECLARE VARIABLE WTA_BET_2 SMALLINT;
DECLARE VARIABLE WTA_BET_3 SMALLINT;
declare variable is_even smallint;
begin
  is_even = 0;
  for select eii.ID_EVENT_INVENTORY_ITEM
    from EVENT_INVENTORY_ITEM eii
    join EVENT_INVENTORY ei on ei.ID_EVENT_INVENTORY = eii.ID_EVENT_INVENTORY
    where ei.ID_EVENT = :ID_EVENT
    into :ID_EVENT_INVENTORY_ITEM
  do begin
    if (is_even = 0) then begin
      BELGIAN_SHOW_BET_1 = 1;
      BELGIAN_SHOW_BET_2 = 0;
      BELGIAN_SHOW_BET_3 = 1;
      BELGIAN_SHOW_BET_4 = 0;
      BELGIAN_SHOW_BET_5 = 1;
      STANDARD_SHOW_BET_1 = 0;
      STANDARD_SHOW_BET_2 = 1;
      STANDARD_SHOW_BET_3 = 0;
      STANDARD_SHOW_BET_6 = 1;
      WTA_BET_1 = 0;
      WTA_BET_2 = 1;
      WTA_BET_3 = 0;
      is_even = 1;
    end else begin
      BELGIAN_SHOW_BET_1 = 0;
      BELGIAN_SHOW_BET_2 = 1;
      BELGIAN_SHOW_BET_3 = 0;
      BELGIAN_SHOW_BET_4 = 1;
      BELGIAN_SHOW_BET_5 = 0;
      STANDARD_SHOW_BET_1 = 1;
      STANDARD_SHOW_BET_2 = 0;
      STANDARD_SHOW_BET_3 = 1;
      STANDARD_SHOW_BET_6 = 0;
      WTA_BET_1 = 1;
      WTA_BET_2 = 0;
      WTA_BET_3 = 1;
      is_even = 0;
    end
    update EVENT_INVENTORY_ITEM
     set BELGIAN_SHOW_BET_1 = :BELGIAN_SHOW_BET_1,
         BELGIAN_SHOW_BET_2 = :BELGIAN_SHOW_BET_2,
         BELGIAN_SHOW_BET_3 = :BELGIAN_SHOW_BET_3,
         BELGIAN_SHOW_BET_4 = :BELGIAN_SHOW_BET_4,
         BELGIAN_SHOW_BET_5 = :BELGIAN_SHOW_BET_5,
         STANDARD_SHOW_BET_1 = :STANDARD_SHOW_BET_1,
         STANDARD_SHOW_BET_2 = :STANDARD_SHOW_BET_2,
         STANDARD_SHOW_BET_3 = :STANDARD_SHOW_BET_3,
         STANDARD_SHOW_BET_6 = :STANDARD_SHOW_BET_6,
         WTA_BET_1 = :WTA_BET_1,
         WTA_BET_2 = :WTA_BET_2,
         WTA_BET_3 = :WTA_BET_3
     where ID_EVENT_INVENTORY_ITEM = :ID_EVENT_INVENTORY_ITEM;
  end
end ^

ALTER PROCEDURE AVG_WINNER_PRIZE_SET (ID_EVENT_INVENTORY_ITEM INTEGER,
ID_EVENT INTEGER,
PRIZE_VALUE NUMERIC(15, 4),
OPERATION VARCHAR(5) CHARACTER SET NONE)
AS 
begin
  if (OPERATION = 'set') then begin
    if (PRIZE_VALUE is not null) then begin
      if (exists (select awp.ID_EVENT_INVENTORY_ITEM
                    from AVG_WINNER_PRIZES awp
                    where awp.ID_EVENT_INVENTORY_ITEM = :ID_EVENT_INVENTORY_ITEM)) then begin
         update AVG_WINNER_PRIZES
         set PRIZE_VALUE = :PRIZE_VALUE
         where ID_EVENT_INVENTORY_ITEM = :ID_EVENT_INVENTORY_ITEM;
      end else begin
         insert into AVG_WINNER_PRIZES(ID_EVENT_INVENTORY_ITEM, ID_EVENT, PRIZE_VALUE)
         values (:ID_EVENT_INVENTORY_ITEM, :ID_EVENT, :PRIZE_VALUE);
      end
    end else begin
      delete from AVG_WINNER_PRIZES
      where ID_EVENT_INVENTORY_ITEM = :ID_EVENT_INVENTORY_ITEM;
    end
  end else if (OPERATION = 'clear') then begin
    delete from AVG_WINNER_PRIZES
    where ID_EVENT = :ID_EVENT;
  end
end ^

ALTER PROCEDURE BASKET_MODIFY (ID_BASKET INTEGER,
ID_RACE INTEGER,
BASKET_NO INTEGER,
CAPACITY INTEGER,
IS_RACE_BASKET SMALLINT,
OPERATION VARCHAR(3) CHARACTER SET NONE)
RETURNS (NEW_ID_BASKET INTEGER)
AS 
begin
  NEW_ID_BASKET = ID_BASKET;
  if (OPERATION = 'add') then begin
    NEW_ID_BASKET = gen_id(GEN_BASKET_ID, 1);
    insert into BASKET(ID_BASKET, ID_RACE, BASKET_NO, CAPACITY, IS_RACE_BASKET)
    values (:NEW_ID_BASKET, :ID_RACE, :BASKET_NO, :CAPACITY, :IS_RACE_BASKET);
  end else if (OPERATION = 'mod') then begin
    update BASKET
    set ID_RACE = :ID_RACE,
        BASKET_NO = :BASKET_NO,
        CAPACITY = :CAPACITY,
        IS_RACE_BASKET = :IS_RACE_BASKET
    where (ID_BASKET = :ID_BASKET);
  end else if (OPERATION = 'del') then begin
    delete from BASKET
    where (ID_BASKET = :ID_BASKET);
  end
  suspend;
end ^

