   join EVENT_INVENTORY_ITEM eii on eii.ID_EVENT_INVENTORY_ITEM = t.ID
   join EVENT_INVENTORY ei on ei.ID_EVENT_INVENTORY = eii.ID_EVENT_INVENTORY
   where ei.ID_EVENT = :ID_EVENT and t.TAG = :SELECTED_TAG and eii.IS_BET_ACTIVE = 1
   into :ID_INVENTORY_ITEM
 do begin
   execute procedure BIRD_BETS_CALC(:ID_INVENTORY_ITEM)
   returning_values :IS_BET_ACTIVE, :BELGIAN_SHOW_1_VALUE, :BELGIAN_SHOW_2_VALUE, :BELGIAN_SHOW_3_VALUE,
     :BELGIAN_SHOW_4_VALUE, :BELGIAN_SHOW_5_VALUE, :BELGIAN_SHOW_6_VALUE, :BELGIAN_SHOW_7_VALUE,
     :STANDARD_SHOW_1_VALUE, :STANDARD_SHOW_2_VALUE, :STANDARD_SHOW_3_VALUE, :STANDARD_SHOW_4_VALUE,
     :STANDARD_SHOW_5_VALUE, :STANDARD_SHOW_6_VALUE, :WTA_1_VALUE, :WTA_2_VALUE, :WTA_3_VALUE,
     :WTA_4_VALUE, :WTA_5_VALUE, :TOTAL_BETS;
   if (coalesce(BELGIAN_SHOW_1_VALUE, 0) > 0) then begin
    BELGIAN_SHOW_1_TOTAL = coalesce(BELGIAN_SHOW_1_TOTAL, 0) + BELGIAN_SHOW_1_VALUE;
    BELGIAN_SHOW_1_COUNT = BELGIAN_SHOW_1_COUNT + 1;
