 select bs.BETTING_CUT_PERCENT, bs.BELGIAN_SHOW_1, bs.BELGIAN_SHOW_2, bs.BELGIAN_SHOW_3, bs.BELGIAN_SHOW_4, bs.BELGIAN_SHOW_5, bs.BELGIAN_SHOW_6,
   bs.BELGIAN_SHOW_7, bs.STANDARD_SHOW_1, bs.STANDARD_SHOW_2, bs.STANDARD_SHOW_3, bs.STANDARD_SHOW_4, bs.STANDARD_SHOW_5, bs.STANDARD_SHOW_6,
   bs.WTA_1, bs.WTA_2, bs.WTA_3, bs.WTA_4, bs.WTA_5
   from EVENTS e
   join BETTING_SCHEME bs on bs.ID_BETTING_SCHEME = e.ID_BETTING_SCHEME
   where e.ID_EVENT = :ID_EVENT
   into :BETTING_CUT_PERCENT, :BELGIAN_SHOW_1, :BELGIAN_SHOW_2, :BELGIAN_SHOW_3, :BELGIAN_SHOW_4, :BELGIAN_SHOW_5, :BELGIAN_SHOW_6,
