     CLASS_PAYOUT = BELGIAN_SHOW_1_TOTAL - ((BELGIAN_SHOW_1_TOTAL * BETTING_CUT_PERCENT) / 100);
     CLASS_FULL_PRIZE_COUNT = TRUNCATE(CLASS_PAYOUT / (BELGIAN_SHOW_1 * 10));
     CLASS_FULL_PRIZE = CLASS_FULL_PRIZE_COUNT * (BELGIAN_SHOW_1 * 10);
     CLASS_PARTIAL_PRIZE = CLASS_PAYOUT - CLASS_FULL_PRIZE;
