ALTER PROCEDURE BETTING_SCHEME_MODIFY (ID_BETTING_SCHEME INTEGER,
BETTING_SCHEME_NAME VARCHAR(100) CHARACTER SET NONE,
BETTING_CUT_PERCENT NUMERIC(15, 4),
BELGIAN_SHOW_1 NUMERIC(15, 4),
BELGIAN_SHOW_2 NUMERIC(15, 4),
BELGIAN_SHOW_3 NUMERIC(15, 4),
BELGIAN_SHOW_4 NUMERIC(15, 4),
BELGIAN_SHOW_5 NUMERIC(15, 4),
BELGIAN_SHOW_6 NUMERIC(15, 4),
BELGIAN_SHOW_7 NUMERIC(15, 4),
STANDARD_SHOW_1 NUMERIC(15, 4),
STANDARD_SHOW_2 NUMERIC(15, 4),
STANDARD_SHOW_3 NUMERIC(15, 4),
STANDARD_SHOW_4 NUMERIC(15, 4),
STANDARD_SHOW_5 NUMERIC(15, 4),
STANDARD_SHOW_6 NUMERIC(15, 4),
WTA_1 NUMERIC(15, 4),
WTA_2 NUMERIC(15, 4),
WTA_3 NUMERIC(15, 4),
WTA_4 NUMERIC(15, 4),
WTA_5 NUMERIC(15, 4),
OPERATION VARCHAR(3) CHARACTER SET NONE)
RETURNS (NEW_ID_BETTING_SCHEME INTEGER)
AS 
begin
  NEW_ID_BETTING_SCHEME = ID_BETTING_SCHEME;
  if (OPERATION = 'add') then begin
    NEW_ID_BETTING_SCHEME = gen_id(GEN_BETTING_SCHEME_ID, 1);
    insert into BETTING_SCHEME(ID_BETTING_SCHEME, BETTING_SCHEME_NAME, BETTING_CUT_PERCENT,
      BELGIAN_SHOW_1, BELGIAN_SHOW_2, BELGIAN_SHOW_3, BELGIAN_SHOW_4, BELGIAN_SHOW_5,
      BELGIAN_SHOW_6, BELGIAN_SHOW_7, STANDARD_SHOW_1, STANDARD_SHOW_2, STANDARD_SHOW_3,
      STANDARD_SHOW_4, STANDARD_SHOW_5, STANDARD_SHOW_6, WTA_1, WTA_2, WTA_3, WTA_4, WTA_5)
    values (:NEW_ID_BETTING_SCHEME, :BETTING_SCHEME_NAME, :BETTING_CUT_PERCENT,
      :BELGIAN_SHOW_1, :BELGIAN_SHOW_2, :BELGIAN_SHOW_3, :BELGIAN_SHOW_4, :BELGIAN_SHOW_5,
      :BELGIAN_SHOW_6, :BELGIAN_SHOW_7, :STANDARD_SHOW_1, :STANDARD_SHOW_2, :STANDARD_SHOW_3,
      :STANDARD_SHOW_4, :STANDARD_SHOW_5, :STANDARD_SHOW_6, :WTA_1, :WTA_2, :WTA_3, :WTA_4, :WTA_5);
  end else if (OPERATION = 'mod') then begin
    update BETTING_SCHEME
    set BETTING_SCHEME_NAME = :BETTING_SCHEME_NAME,
        BETTING_CUT_PERCENT = :BETTING_CUT_PERCENT,
        BELGIAN_SHOW_1 = :BELGIAN_SHOW_1,
        BELGIAN_SHOW_2 = :BELGIAN_SHOW_2,
        BELGIAN_SHOW_3 = :BELGIAN_SHOW_3,
        BELGIAN_SHOW_4 = :BELGIAN_SHOW_4,
        BELGIAN_SHOW_5 = :BELGIAN_SHOW_5,
        BELGIAN_SHOW_6 = :BELGIAN_SHOW_6,
        BELGIAN_SHOW_7 = :BELGIAN_SHOW_7,
        STANDARD_SHOW_1 = :STANDARD_SHOW_1,
        STANDARD_SHOW_2 = :STANDARD_SHOW_2,
        STANDARD_SHOW_3 = :STANDARD_SHOW_3,
        STANDARD_SHOW_4 = :STANDARD_SHOW_4,
        STANDARD_SHOW_5 = :STANDARD_SHOW_5,
        STANDARD_SHOW_6 = :STANDARD_SHOW_6,
        WTA_1 = :WTA_1,
        WTA_2 = :WTA_2,
        WTA_3 = :WTA_3,
        WTA_4 = :WTA_4,
        WTA_5 = :WTA_5
    where ID_BETTING_SCHEME = :ID_BETTING_SCHEME;
  end else if (OPERATION = 'del') then begin
     delete from BETTING_SCHEME
     where ID_BETTING_SCHEME = :ID_BETTING_SCHEME;
  end
  suspend;
end ^

ALTER PROCEDURE BIRDS_BY_EVENT_GET (ID_EVENT INTEGER)
RETURNS (BREEDER_NAME VARCHAR(50) CHARACTER SET NONE,
BIRD_BAND_1 VARCHAR(20) CHARACTER SET NONE,
BIRD_BAND_2 VARCHAR(20) CHARACTER SET NONE,
BIRD_BAND_3 VARCHAR(20) CHARACTER SET NONE,
BIRD_BAND_4 VARCHAR(20) CHARACTER SET NONE)
AS 
declare variable ID_BREEDER integer;
declare variable TMP_ID_BREEDER integer;
declare variable TMP_BREEDER_NAME varchar(50);
declare variable BAND varchar(20);
begin
  TMP_ID_BREEDER = null;
  TMP_BREEDER_NAME = null;
  BIRD_BAND_1 = null;
  BIRD_BAND_2 = null;
  BIRD_BAND_3 = null;
  BIRD_BAND_4 = null;
  for select
    b.ID_BREEDER,
    coalesce(b.FIRST_NAME, '') || ' ' || coalesce(b.LAST_NAME, ''),
    br.BAND
    from EVENT_INVENTORY ei
    join BREEDERS b on b.ID_BREEDER = ei.ID_BREEDER
    join EVENT_INVENTORY_ITEM eii on eii.ID_EVENT_INVENTORY = ei.ID_EVENT_INVENTORY
    join BIRDS br on br.ID_BIRD = eii.ID_BIRD
    where ei.ID_EVENT = :ID_EVENT
    order by b.ID_BREEDER
    into :ID_BREEDER, :TMP_BREEDER_NAME, :BAND
  do begin
    if (TMP_ID_BREEDER = ID_BREEDER) then begin
      if (BIRD_BAND_1 is null) then begin
        BIRD_BAND_1 = BAND;
      end else if (BIRD_BAND_2 is null) then begin
        BIRD_BAND_2 = BAND;
      end else if (BIRD_BAND_3 is null) then begin
        BIRD_BAND_3 = BAND;
      end else begin
        BIRD_BAND_4 = BAND;
        suspend;
        BIRD_BAND_1 = null;
        BIRD_BAND_2 = null;
        BIRD_BAND_3 = null;
        BIRD_BAND_4 = null;
      end
    end else begin
      if (TMP_ID_BREEDER is not null) then begin
        if ((BIRD_BAND_1 is not null) or (BIRD_BAND_2 is not null)
          or (BIRD_BAND_3 is not null) or (BIRD_BAND_4 is not null)) then begin
          suspend;
        end
        BIRD_BAND_1 = null;
        BIRD_BAND_2 = null;
        BIRD_BAND_3 = null;
        BIRD_BAND_4 = null;
      end
      TMP_ID_BREEDER = ID_BREEDER;
      BREEDER_NAME = TMP_BREEDER_NAME;
      BIRD_BAND_1 = BAND;
    end
  end
  if ((BIRD_BAND_1 is not null) or (BIRD_BAND_2 is not null)
    or (BIRD_BAND_3 is not null) or (BIRD_BAND_4 is not null)) then begin
    suspend;
  end
end ^

ALTER PROCEDURE BIRD_BACKUP_APPLY (ID_LOST_BIRD INTEGER)
AS 
declare variable ID_EVENT_INVENTORY integer;
declare variable ID_LOST_BIRD_INVENTORY integer;
declare variable ID_BACKUP_BIRD_INVENTORY integer;
declare variable BIRD_NO integer;
declare variable PERCH_FEE_VALUE numeric(15, 4);
declare variable ENTRY_FEE_VALUE numeric(15, 4);
declare variable ENTRY_FEE_PAID smallint;
declare variable HOT_SPOT_FEE_VALUE numeric(15, 4);
begin
  select eii.ID_EVENT_INVENTORY,
         eii.ID_EVENT_INVENTORY_ITEM, eii.BIRD_NO,
         eii.PERCH_FEE_VALUE,
         eii.ENTRY_FEE_VALUE,
         eii.ENTRY_FEE_PAID,
         eii.HOT_SPOT_FEE_VALUE
    from EVENT_INVENTORY_ITEM eii
    where eii.ID_BIRD = :ID_LOST_BIRD
    into :ID_EVENT_INVENTORY,
         :ID_LOST_BIRD_INVENTORY,
         :BIRD_NO,
         :PERCH_FEE_VALUE,
         :ENTRY_FEE_VALUE,
         :ENTRY_FEE_PAID,
         :HOT_SPOT_FEE_VALUE;

  select first 1 eii.ID_EVENT_INVENTORY_ITEM
    from EVENT_INVENTORY_ITEM eii
    join BIRDS b on b.ID_BIRD = eii.ID_BIRD
    where eii.ID_EVENT_INVENTORY = :ID_EVENT_INVENTORY
      and eii.IS_BACKUP = 1
      and b.IS_LOST = 0
      and coalesce(eii.PERCH_FEE_VALUE, 0) = 0
    order by eii.BIRD_NO
    into :ID_BACKUP_BIRD_INVENTORY;

  if (ID_BACKUP_BIRD_INVENTORY is not null) then begin
    update EVENT_INVENTORY_ITEM eii
      set eii.BIRD_NO = :BIRD_NO,
          eii.PERCH_FEE_VALUE = :PERCH_FEE_VALUE,
          eii.ENTRY_FEE_VALUE = :ENTRY_FEE_VALUE,
          eii.ENTRY_FEE_PAID = :ENTRY_FEE_PAID,
          eii.HOT_SPOT_FEE_VALUE = :HOT_SPOT_FEE_VALUE,
          eii.IS_BACKUP = 0
      where eii.ID_EVENT_INVENTORY_ITEM = :ID_BACKUP_BIRD_INVENTORY;
    execute procedure EVENT_INVENTORY_ITEM_REPLACE(:ID_LOST_BIRD_INVENTORY, :ID_BACKUP_BIRD_INVENTORY);
  end
end ^

ALTER PROCEDURE BIRD_BETS_CALC (ID_EVENT_INVENTORY_ITEM INTEGER)
RETURNS (IS_BET_ACTIVE SMALLINT,
BELGIAN_SHOW_1 NUMERIC(15, 4),
BELGIAN_SHOW_2 NUMERIC(15, 4),
BELGIAN_SHOW_3 NUMERIC(15, 4),
BELGIAN_SHOW_4 NUMERIC(15, 4),
BELGIAN_SHOW_5 NUMERIC(15, 4),
BELGIAN_SHOW_6 NUMERIC(15, 4),
BELGIAN_SHOW_7 NUMERIC(15, 4),
STANDARD_SHOW_1 NUMERIC(15, 4),
STANDARD_SHOW_2 NUMERIC(15, 4),
STANDARD_SHOW_3 NUMERIC(15, 4),
STANDARD_SHOW_4 NUMERIC(15, 4),
STANDARD_SHOW_5 NUMERIC(15, 4),
STANDARD_SHOW_6 NUMERIC(15, 4),
WTA_1 NUMERIC(15, 4),
WTA_2 NUMERIC(15, 4),
WTA_3 NUMERIC(15, 4),
WTA_4 NUMERIC(15, 4),
WTA_5 NUMERIC(15, 4),
TOTAL_BETS NUMERIC(15, 4))
AS 
begin
  select eii.IS_BET_ACTIVE,
         (eii.BELGIAN_SHOW_BET_1 * bs.BELGIAN_SHOW_1),
         (eii.BELGIAN_SHOW_BET_2 * bs.BELGIAN_SHOW_2),
         (eii.BELGIAN_SHOW_BET_3 * bs.BELGIAN_SHOW_3),
         (eii.BELGIAN_SHOW_BET_4 * bs.BELGIAN_SHOW_4),
         (eii.BELGIAN_SHOW_BET_5 * bs.BELGIAN_SHOW_5),
         (eii.BELGIAN_SHOW_BET_6 * bs.BELGIAN_SHOW_6),
         (eii.BELGIAN_SHOW_BET_7 * bs.BELGIAN_SHOW_7),
         (eii.STANDARD_SHOW_BET_1 * bs.STANDARD_SHOW_1),
         (eii.STANDARD_SHOW_BET_2 * bs.STANDARD_SHOW_2),
         (eii.STANDARD_SHOW_BET_3 * bs.STANDARD_SHOW_3),
         (eii.STANDARD_SHOW_BET_4 * bs.STANDARD_SHOW_4),
         (eii.STANDARD_SHOW_BET_5 * bs.STANDARD_SHOW_5),
         (eii.STANDARD_SHOW_BET_6 * bs.STANDARD_SHOW_6),
         (eii.WTA_BET_1 * bs.WTA_1),
         (eii.WTA_BET_2 * bs.WTA_2),
         (eii.WTA_BET_3 * bs.WTA_3),
         (eii.WTA_BET_4 * bs.WTA_4),
         (eii.WTA_BET_5 * bs.WTA_5)
    from EVENT_INVENTORY_ITEM eii
    join EVENT_INVENTORY ei on ei.ID_EVENT_INVENTORY = eii.ID_EVENT_INVENTORY
    join EVENTS e on e.ID_EVENT = ei.ID_EVENT
    join BETTING_SCHEME bs on bs.ID_BETTING_SCHEME = e.ID_BETTING_SCHEME
    where eii.ID_EVENT_INVENTORY_ITEM = :ID_EVENT_INVENTORY_ITEM
    into :IS_BET_ACTIVE, :BELGIAN_SHOW_1, :BELGIAN_SHOW_2, :BELGIAN_SHOW_3, :BELGIAN_SHOW_4,
         :BELGIAN_SHOW_5, :BELGIAN_SHOW_6, :BELGIAN_SHOW_7, :STANDARD_SHOW_1,
         :STANDARD_SHOW_2, :STANDARD_SHOW_3, :STANDARD_SHOW_4, :STANDARD_SHOW_5,
         :STANDARD_SHOW_6, :WTA_1, :WTA_2, :WTA_3, :WTA_4, :WTA_5;

  TOTAL_BETS = coalesce(BELGIAN_SHOW_1, 0)
             + coalesce(BELGIAN_SHOW_2, 0)
             + coalesce(BELGIAN_SHOW_3, 0)
             + coalesce(BELGIAN_SHOW_4, 0)
             + coalesce(BELGIAN_SHOW_5, 0)
             + coalesce(BELGIAN_SHOW_6, 0)
             + coalesce(BELGIAN_SHOW_7, 0)
             + coalesce(STANDARD_SHOW_1, 0)
             + coalesce(STANDARD_SHOW_2, 0)
             + coalesce(STANDARD_SHOW_3, 0)
             + coalesce(STANDARD_SHOW_4, 0)
             + coalesce(STANDARD_SHOW_5, 0)
             + coalesce(STANDARD_SHOW_6, 0)
             + coalesce(WTA_1, 0)
             + coalesce(WTA_2, 0)
             + coalesce(WTA_3, 0)
             + coalesce(WTA_4, 0);
  suspend;
end ^

ALTER PROCEDURE BIRD_BETS_DESC (ID_EVENT_INVENTORY_ITEM INTEGER)
RETURNS (BETS_DESC VARCHAR(750) CHARACTER SET NONE)
AS 
declare variable IS_BET_ACTIVE smallint;
declare variable BELGIAN_SHOW_1 numeric(15,2);
declare variable BELGIAN_SHOW_2 numeric(15,2);
declare variable BELGIAN_SHOW_3 numeric(15,2);
declare variable BELGIAN_SHOW_4 numeric(15,2);
declare variable BELGIAN_SHOW_5 numeric(15,2);
declare variable BELGIAN_SHOW_6 numeric(15,2);
declare variable BELGIAN_SHOW_7 numeric(15,2);
declare variable STANDARD_SHOW_1 numeric(15,2);
declare variable STANDARD_SHOW_2 numeric(15,2);
declare variable STANDARD_SHOW_3 numeric(15,2);
declare variable STANDARD_SHOW_4 numeric(15,2);
declare variable STANDARD_SHOW_5 numeric(15,2);
declare variable STANDARD_SHOW_6 numeric(15,2);
declare variable WTA_1 numeric(15,2);
declare variable WTA_2 numeric(15,2);
declare variable WTA_3 numeric(15,2);
declare variable WTA_4 numeric(15,2);
declare variable WTA_5 numeric(15,2);
declare variable TOTAL_BETS numeric(15,4);
declare variable BELGIAN_SHOW varchar(250);
declare variable STANDARD_SHOW varchar(250);
declare variable WTA_SHOW varchar(250);
begin
  execute procedure BIRD_BETS_CALC(:ID_EVENT_INVENTORY_ITEM)
  returning_values :IS_BET_ACTIVE, :BELGIAN_SHOW_1, :BELGIAN_SHOW_2, :BELGIAN_SHOW_3,
                   :BELGIAN_SHOW_4, :BELGIAN_SHOW_5, :BELGIAN_SHOW_6,
                   :BELGIAN_SHOW_7, :STANDARD_SHOW_1, :STANDARD_SHOW_2,
                   :STANDARD_SHOW_3, :STANDARD_SHOW_4, :STANDARD_SHOW_5,
                   :STANDARD_SHOW_6, :WTA_1, :WTA_2, :WTA_3, :WTA_4, :WTA_5, :TOTAL_BETS;
  BELGIAN_SHOW = '';
  if ((BELGIAN_SHOW_1 is not null) and (BELGIAN_SHOW_1 > 0)) then begin
    BELGIAN_SHOW = '$' || BELGIAN_SHOW_1;
  end
  if ((BELGIAN_SHOW_2 is not null) and (BELGIAN_SHOW_2 > 0)) then begin
    if (BELGIAN_SHOW <> '') then BELGIAN_SHOW = BELGIAN_SHOW || '+';
    BELGIAN_SHOW = BELGIAN_SHOW || '$' || BELGIAN_SHOW_2;
  end
  if ((BELGIAN_SHOW_3 is not null) and (BELGIAN_SHOW_3 > 0)) then begin
    if (BELGIAN_SHOW <> '') then BELGIAN_SHOW = BELGIAN_SHOW || '+';
    BELGIAN_SHOW = BELGIAN_SHOW || '$' || BELGIAN_SHOW_3;
  end
  if ((BELGIAN_SHOW_4 is not null) and (BELGIAN_SHOW_4 > 0)) then begin
    if (BELGIAN_SHOW <> '') then BELGIAN_SHOW = BELGIAN_SHOW || '+';
    BELGIAN_SHOW = BELGIAN_SHOW || '$' || BELGIAN_SHOW_4;
  end
  if ((BELGIAN_SHOW_5 is not null) and (BELGIAN_SHOW_5 > 0)) then begin
    if (BELGIAN_SHOW <> '') then BELGIAN_SHOW = BELGIAN_SHOW || '+';
    BELGIAN_SHOW = BELGIAN_SHOW || '$' || BELGIAN_SHOW_5;
  end
  if ((BELGIAN_SHOW_6 is not null) and (BELGIAN_SHOW_6 > 0)) then begin
    if (BELGIAN_SHOW <> '') then BELGIAN_SHOW = BELGIAN_SHOW || '+';
    BELGIAN_SHOW = BELGIAN_SHOW || '$' || BELGIAN_SHOW_6;
  end
  if ((BELGIAN_SHOW_7 is not null) and (BELGIAN_SHOW_7 > 0)) then begin
    if (BELGIAN_SHOW <> '') then BELGIAN_SHOW = BELGIAN_SHOW || '+';
    BELGIAN_SHOW = BELGIAN_SHOW || '$' || BELGIAN_SHOW_7;
  end
  STANDARD_SHOW = '';
  if ((STANDARD_SHOW_1 is not null) and (STANDARD_SHOW_1 > 0)) then begin
    STANDARD_SHOW = '$' || STANDARD_SHOW_1;
  end
  if ((STANDARD_SHOW_2 is not null) and (STANDARD_SHOW_2 > 0)) then begin
    if (STANDARD_SHOW <> '') then STANDARD_SHOW = STANDARD_SHOW || '+';
    STANDARD_SHOW = STANDARD_SHOW || '$' || STANDARD_SHOW_2;
  end
  if ((STANDARD_SHOW_3 is not null) and (STANDARD_SHOW_3 > 0)) then begin
    if (STANDARD_SHOW <> '') then STANDARD_SHOW = STANDARD_SHOW || '+';
    STANDARD_SHOW = STANDARD_SHOW || '$' || STANDARD_SHOW_3;
  end
  if ((STANDARD_SHOW_4 is not null) and (STANDARD_SHOW_4 > 0)) then begin
    if (STANDARD_SHOW <> '') then STANDARD_SHOW = STANDARD_SHOW || '+';
    STANDARD_SHOW = STANDARD_SHOW || '$' || STANDARD_SHOW_4;
  end
  if ((STANDARD_SHOW_5 is not null) and (STANDARD_SHOW_5 > 0)) then begin
    if (STANDARD_SHOW <> '') then STANDARD_SHOW = STANDARD_SHOW || '+';
    STANDARD_SHOW = STANDARD_SHOW || '$' || STANDARD_SHOW_5;
  end
  if ((STANDARD_SHOW_6 is not null) and (STANDARD_SHOW_6 > 0)) then begin
    if (STANDARD_SHOW <> '') then STANDARD_SHOW = STANDARD_SHOW || '+';
    STANDARD_SHOW = STANDARD_SHOW || '$' || STANDARD_SHOW_6;
  end
  WTA_SHOW = '';
  if ((WTA_1 is not null) and (WTA_1 > 0)) then begin
    WTA_SHOW = '$' || WTA_1;
  end
  if ((WTA_2 is not null) and (WTA_2 > 0)) then begin
    if (WTA_SHOW <> '') then WTA_SHOW = WTA_SHOW || '+';
    WTA_SHOW = WTA_SHOW || '$' || WTA_2;
  end
  if ((WTA_3 is not null) and (WTA_3 > 0)) then begin
    if (WTA_SHOW <> '') then WTA_SHOW = WTA_SHOW || '+';
    WTA_SHOW = WTA_SHOW || '$' || WTA_3;
  end
  if ((WTA_4 is not null) and (WTA_4 > 0)) then begin
    if (WTA_SHOW <> '') then WTA_SHOW = WTA_SHOW || '+';
    WTA_SHOW = WTA_SHOW || '$' || WTA_4;
  end
  if ((WTA_5 is not null) and (WTA_5 > 0)) then begin
    if (WTA_SHOW <> '') then WTA_SHOW = WTA_SHOW || '+';
    WTA_SHOW = WTA_SHOW || '$' || WTA_5;
  end
  BETS_DESC = '';
  if (BELGIAN_SHOW <> '') then begin
    BETS_DESC = '10 to 1(' || BELGIAN_SHOW || ')';
  end
  if (STANDARD_SHOW <> '') then begin
    if (BETS_DESC <> '') then BETS_DESC = BETS_DESC || ';';
    BETS_DESC = BETS_DESC || 'Standard(' || STANDARD_SHOW || ')';
  end
  if (WTA_SHOW <> '') then begin
    if (BETS_DESC <> '') then BETS_DESC = BETS_DESC || ';';
    BETS_DESC = BETS_DESC || 'WTA(' || WTA_SHOW || ')';
  end
  suspend;
end ^

ALTER PROCEDURE BIRD_BETS_REFUND_SET (ID_EVENT_INVENTORY_ITEM INTEGER)
AS 
declare variable IS_BET_ACTIVE smallint;
declare variable BIRD_BETS numeric(15, 4);
begin
  select bbc.IS_BET_ACTIVE, bbc.TOTAL_BETS
    from BIRD_BETS_CALC(:ID_EVENT_INVENTORY_ITEM) bbc
    into :IS_BET_ACTIVE, :BIRD_BETS;

  if ((IS_BET_ACTIVE <> 0) and (BIRD_BETS > 0)) then begin
    -- setting refunds and clear th bets
    update EVENT_INVENTORY_ITEM eii
      set eii.BETS_REFUND = :BIRD_BETS,
          eii.IS_BET_ACTIVE = 0
      where eii.ID_EVENT_INVENTORY_ITEM = :ID_EVENT_INVENTORY_ITEM;
  end
end ^

ALTER PROCEDURE BIRD_LOST_STATUS_MODIFY (ID_BIRD INTEGER,
IS_LOST SMALLINT,
CHANGE_DATE DATE,
ID_RACE INTEGER)
AS 
declare variable PREV_IS_LOST smallint;
declare variable PREV_ID_LOST_RACE integer;
declare variable LOST_DATE date;
declare variable LOST_ID_RACE integer;
declare variable IS_FLOATING_BACKUP_SCHEME smallint;
begin
  select b.IS_LOST,
         b.LOST_ID_RACE,
         fs.IS_FLOATING_BACKUP
    from BIRDS b
    join EVENT_INVENTORY_ITEM eii on eii.ID_BIRD = b.ID_BIRD
    join EVENT_INVENTORY ei on ei.ID_EVENT_INVENTORY = eii.ID_EVENT_INVENTORY
    join EVENTS e on e.ID_EVENT = ei.ID_EVENT
    join FEE_SCHEME fs on fs.ID_FEE_SCHEME = e.ID_FEE_SCHEME
    where b.ID_BIRD = :ID_BIRD
    into :PREV_IS_LOST,
         :PREV_ID_LOST_RACE,
         :IS_FLOATING_BACKUP_SCHEME;

  if ((PREV_IS_LOST = IS_LOST) and ((ID_RACE is null) or (PREV_ID_LOST_RACE = ID_RACE))) then begin
    exit;
  end

  if (CHANGE_DATE is null) then begin
    CHANGE_DATE = 'now';
  end

  LOST_DATE = null;
  LOST_ID_RACE = null;
  if (IS_LOST = 1) then begin
    LOST_DATE = CHANGE_DATE;
    LOST_ID_RACE = ID_RACE;
  end
  update BIRDS b
    set b.IS_LOST = :IS_LOST,
        b.LOST_DATE = :LOST_DATE,
        B.LOST_ID_RACE = :LOST_ID_RACE
   where b.ID_BIRD = :ID_BIRD;

  execute procedure LOST_HISTORY_MODIFY(:ID_BIRD, :CHANGE_DATE, :IS_LOST, :ID_RACE, 'set');

  if ((IS_LOST = 1) and (IS_FLOATING_BACKUP_SCHEME = 1)) then begin
    execute procedure BIRD_BACKUP_APPLY(:ID_BIRD);
  end

  execute procedure BIRD_REFUNDS_MODIFY(:ID_RACE, :ID_BIRD, :IS_LOST);

end ^

ALTER PROCEDURE BIRD_MODIFY (ID_BIRD INTEGER,
BAND_1 VARCHAR(10) CHARACTER SET NONE,
BAND_2 VARCHAR(10) CHARACTER SET NONE,
BAND_3 VARCHAR(10) CHARACTER SET NONE,
BAND_4 VARCHAR(10) CHARACTER SET NONE,
BIRD_NAME VARCHAR(30) CHARACTER SET NONE,
RF_ID VARCHAR(20) CHARACTER SET NONE,
COLOR VARCHAR(10) CHARACTER SET NONE,
SEX SMALLINT,
IS_ACTIVE SMALLINT,
IS_RACE_VERIFIED SMALLINT,
NOTE VARCHAR(500) CHARACTER SET NONE,
ID_PICTURE INTEGER,
PLAY_ATTENTION_SOUND SMALLINT,
OPERATION VARCHAR(3) CHARACTER SET NONE)
RETURNS (NEW_ID_BIRD INTEGER,
ERR_CODE INTEGER,
ERR_TEXT VARCHAR(255) CHARACTER SET NONE)
AS 
declare variable BAND varchar(40);
begin
  ERR_CODE = 0;
  ERR_TEXT = '';

  BAND = BAND_1 || BAND_2 || BAND_3 || BAND_4;
  NEW_ID_BIRD = ID_BIRD;
  if ((OPERATION = 'add') or (OPERATION = 'mod')) then begin
    if (exists (select b.ID_BIRD
                  from BIRDS b
                  where b.BAND_1 = :BAND_1
                    and b.BAND_2 = :BAND_2
                    and b.BAND_3 = :BAND_3
                    and b.BAND_4 = :BAND_4
                    and ((:ID_BIRD is null) or (b.ID_BIRD <> :ID_BIRD)))) then begin
      ERR_CODE = 1;
      ERR_TEXT = 'Bird with BAND ' || :BAND || ' already exist!';
      exit;
    end
    if ((RF_ID is not null) and (RF_ID <> '')) then begin
      if (exists (select b.ID_BIRD
                    from BIRDS b
                    where b.RF_ID = :RF_ID
                      and ((:ID_BIRD is null) or (b.ID_BIRD <> :ID_BIRD)))) then begin
        ERR_CODE = 1;
        ERR_TEXT = 'Bird with EID ' ||:RF_ID|| ' already exist!';
        exit;
      end
    end
  end
  if (OPERATION = 'add') then begin
    NEW_ID_BIRD = gen_id(GEN_BIRD_ID, 1);
    insert into BIRDS
      (ID_BIRD, BAND, BAND_1, BAND_2, BAND_3, BAND_4, BIRD_NAME, RF_ID, COLOR,
      SEX, IS_ACTIVE, IS_RACE_VERIFIED, IS_LOST, NOTE, ID_PICTURE, PLAY_ATTENTION_SOUND)
    values
      (:NEW_ID_BIRD, :BAND, :BAND_1, :BAND_2, :BAND_3, :BAND_4, :BIRD_NAME, :RF_ID, :COLOR,
      :SEX, :IS_ACTIVE, :IS_RACE_VERIFIED, 0, :NOTE, :ID_PICTURE, :PLAY_ATTENTION_SOUND);
  end else if (OPERATION = 'mod') then begin
    update BIRDS b
    set b.BAND = :BAND,
        b.BAND_1 = :BAND_1,
        b.BAND_2 = :BAND_2,
        b.BAND_3 = :BAND_3,
        b.BAND_4 = :BAND_4,
        b.BIRD_NAME = :BIRD_NAME,
        b.RF_ID = :RF_ID,
        b.COLOR = :COLOR,
        b.SEX = :SEX,
        b.IS_ACTIVE = :IS_ACTIVE,
        b.IS_RACE_VERIFIED = :IS_RACE_VERIFIED,
        b.NOTE = :NOTE,
        b.ID_PICTURE = :ID_PICTURE,
        b.PLAY_ATTENTION_SOUND = :PLAY_ATTENTION_SOUND
    where (b.ID_BIRD = :ID_BIRD);
  end else if (OPERATION = 'del') then begin
   -- birds are deleted only from EVENT_INVENTORY_ITEM_MODIFY
   /* delete from BIRDS b
    where (b.ID_BIRD = :ID_BIRD);*/
  end
  suspend;
end ^

ALTER PROCEDURE BIRD_PLAY_ATTENTION_RESET (RF_ID VARCHAR(20) CHARACTER SET NONE)
AS 
begin
  update BIRDS b
    set b.PLAY_ATTENTION_SOUND = 0
    where b.RF_ID = :RF_ID;
end ^

ALTER PROCEDURE BIRD_REFUNDS_MODIFY (ID_RACE INTEGER,
ID_BIRD INTEGER,
IS_LOST SMALLINT)
AS 
declare variable ID_EVENT integer;
declare variable ID_RACE_TYPE integer;
declare variable ID_EVENT_INVENTORY_ITEM integer;
declare variable ENTRY_FEE_VALUE numeric(15, 4);
declare variable REFUND_VALUE numeric(15, 4);
declare variable ENTRY_FEE_PAID smallint;
declare variable HOT_SPOT_FEE_VALUE numeric(15, 4);
begin
  if (ID_RACE is not null) then begin
    select r.ID_RACE_TYPE,
           r.ID_EVENT
      from RACE r
      where r.ID_RACE = :ID_RACE
      into :ID_RACE_TYPE,
           :ID_EVENT;
    if (ID_RACE_TYPE = 5) then begin
      -- no any refunds are allowed on final race
      exit;
    end
  end

  -- this section is used to recalc entry fee refunds if it is allowed
  select eii.ID_EVENT_INVENTORY_ITEM,
         eii.ENTRY_FEE_VALUE,
         eii.ENTRY_FEE_PAID
    from EVENT_INVENTORY ei
    join EVENTS e on e.ID_EVENT = ei.ID_EVENT
    join FEE_SCHEME fs on fs.ID_FEE_SCHEME = e.ID_FEE_SCHEME
    join EVENT_INVENTORY_ITEM eii on eii.ID_EVENT_INVENTORY = ei.ID_EVENT_INVENTORY
    where (e.IS_OPEN = 1) and (eii.ID_BIRD = :ID_BIRD) and (fs.IS_REFUNDABLE = 1) and (eii.ENTRY_FEE_VALUE > 0)
    into :ID_EVENT_INVENTORY_ITEM,
         :ENTRY_FEE_VALUE,
         :ENTRY_FEE_PAID;

  if (ID_EVENT_INVENTORY_ITEM is not null) then begin
    if ((IS_LOST = 0) or (ENTRY_FEE_PAID = 0)) then begin
      REFUND_VALUE = null;
    end else begin
      REFUND_VALUE = ENTRY_FEE_VALUE;
    end
    update EVENT_INVENTORY_ITEM eii
      set eii.ENTRY_REFUND = :REFUND_VALUE
      where eii.ID_EVENT_INVENTORY_ITEM = :ID_EVENT_INVENTORY_ITEM;
  end

  -- this section is used to recalc hot spot refunds if it is allowed
  -- hot spot refund is allowed only if hot spot 1 is not processed
  if (not exists (select r.ID_RACE from RACE r where r.ID_EVENT = :ID_EVENT and r.ID_RACE_TYPE = 6 /* hot spot 1*/)) then begin
    select eii.ID_EVENT_INVENTORY_ITEM,
           eii.HOT_SPOT_FEE_VALUE
      from EVENT_INVENTORY ei
      join EVENTS e on e.ID_EVENT = ei.ID_EVENT
      join EVENT_INVENTORY_ITEM eii on eii.ID_EVENT_INVENTORY = ei.ID_EVENT_INVENTORY
      where (e.IS_OPEN = 1) and (eii.ID_BIRD = :ID_BIRD) and (eii.HOT_SPOT_FEE_VALUE > 0)
      into :ID_EVENT_INVENTORY_ITEM,
           :HOT_SPOT_FEE_VALUE;

    if (ID_EVENT_INVENTORY_ITEM is not null) then begin
      if (IS_LOST = 0) then begin
        REFUND_VALUE = null;
      end else begin
        REFUND_VALUE = HOT_SPOT_FEE_VALUE;
      end
      update EVENT_INVENTORY_ITEM eii
        set eii.HOT_SPOT_REFUND = :REFUND_VALUE
        where eii.ID_EVENT_INVENTORY_ITEM = :ID_EVENT_INVENTORY_ITEM;
    end
  end

  -- this section is used to refund bet on bird that is lost after that
  if (IS_LOST = 1) then begin
    select eii.ID_EVENT_INVENTORY_ITEM
      from EVENT_INVENTORY ei
      join EVENTS e on e.ID_EVENT = ei.ID_EVENT
      join EVENT_INVENTORY_ITEM eii on eii.ID_EVENT_INVENTORY = ei.ID_EVENT_INVENTORY
      where (e.IS_OPEN = 1) and (eii.ID_BIRD = :ID_BIRD)
      into :ID_EVENT_INVENTORY_ITEM;

    if (ID_EVENT_INVENTORY_ITEM is not null) then begin
      -- setting refunds and clear th bets
      execute procedure BIRD_BETS_REFUND_SET(:ID_EVENT_INVENTORY_ITEM);
    end
  end
end ^

ALTER PROCEDURE BREEDER_AVG_SPEED_GET (SELECTED_TAG VARCHAR(50) CHARACTER SET NONE,
ONLY_HOT_SPOT_PAID SMALLINT,
BIRDS_COUNT INTEGER)
RETURNS (ID_EVENT_INVENTORY INTEGER,
BREEDERD_POSITION INTEGER,
RACE_COUNT INTEGER,
TOTAL_FLIGHT_TIME BIGINT,
TOTAL_FLIGHT_DISTANCE INTEGER,
AVG_SPEED_IN_YARDS NUMERIC(15, 4),
AVG_SPEED_IN_MILES NUMERIC(15, 4),
TIME_TO_WIN BIGINT)
AS 
declare variable BEST_FLIGHT_TIME bigint;
declare variable MAX_RACE_COUNT integer;
declare variable MAX_BIRD_COUNT integer;
declare variable TMP_BIRD_COUNT integer;
begin
  MAX_RACE_COUNT = null;
  MAX_BIRD_COUNT = null;
  BEST_FLIGHT_TIME = null;
  BREEDERD_POSITION = 0;
  for select ras.ID_EVENT_INVENTORY, ras.RACE_COUNT, ras.BIRDS_COUNT_OUT, ras.TOTAL_FLIGHT_DISTANCE, ras.TOTAL_FLIGHT_TIME,
    ras.AVG_SPEED_IN_YARDS, ras.AVG_SPEED_IN_MILES
    from CALC_RACE_BREEDER_SPEED_INT(:SELECTED_TAG, :ONLY_HOT_SPOT_PAID, :BIRDS_COUNT) ras
    order by ras.RACE_COUNT desc, ras.TOTAL_FLIGHT_DISTANCE desc, ras.TOTAL_FLIGHT_TIME
    into :ID_EVENT_INVENTORY, :RACE_COUNT, :TMP_BIRD_COUNT, :TOTAL_FLIGHT_DISTANCE, :TOTAL_FLIGHT_TIME,
      :AVG_SPEED_IN_YARDS, :AVG_SPEED_IN_MILES
  do begin
    BREEDERD_POSITION = BREEDERD_POSITION + 1;
    if (MAX_RACE_COUNT is null) then begin
      MAX_RACE_COUNT = RACE_COUNT;
    end
    if (MAX_BIRD_COUNT is null) then begin
      MAX_BIRD_COUNT = TMP_BIRD_COUNT;
    end
    if (BEST_FLIGHT_TIME is null) then begin
      BEST_FLIGHT_TIME = TOTAL_FLIGHT_TIME;
    end
    TIME_TO_WIN = null;
    if ((MAX_RACE_COUNT = RACE_COUNT) and (MAX_BIRD_COUNT = TMP_BIRD_COUNT)) then begin
      TIME_TO_WIN = TOTAL_FLIGHT_TIME - BEST_FLIGHT_TIME;
    end
    suspend;
  end
end ^

ALTER PROCEDURE BREEDER_BIRDS_AVG_SPEED_GET (SELECTED_TAG VARCHAR(50) CHARACTER SET NONE,
ID_EVENT_INVENTORY INTEGER,
ONLY_HOT_SPOT_PAID SMALLINT,
BIRDS_COUNT INTEGER)
RETURNS (ID_RACE INTEGER,
ID_EVENT_INVENTORY_ITEM INTEGER,
BEST_BIRD_POSITION INTEGER,
BEST_FLIGHT_TIME BIGINT,
BEST_FLIGHT_DISTANCE INTEGER,
BEST_AVG_SPEED_IN_YARDS NUMERIC(15, 4),
BEST_AVG_SPEED_IN_MILES NUMERIC(15, 4))
AS 
begin
  for select distinct r.ID_RACE
    from RACE r
    join TMP_ID tid on tid.ID = r.ID_RACE and tid.TAG = :SELECTED_TAG
    join RACE_ITEM ri on ri.ID_RACE = r.ID_RACE
    join RACE_ITEM_RESULT rir on rir.ID_RACE_ITEM = ri.ID_RACE_ITEM
    join EVENT_INVENTORY_ITEM eii on eii.ID_EVENT_INVENTORY_ITEM = ri.ID_INVENTORY_ITEM
    where (coalesce(r.DISTANCE, 0) > 0) and (rir.BIRD_POSITION is not null) and ((coalesce(:ONLY_HOT_SPOT_PAID, 0) <> 1) or (eii.HOT_SPOT_FEE_VALUE is not null))
    order by r.ID_RACE
    into :ID_RACE
  do begin

    for select bbs.ID_EVENT_INVENTORY_ITEM, bbs.BEST_BIRD_POSITION, bbs.BEST_FLIGHT_TIME, bbs.BEST_FLIGHT_DISTANCE,
      bbs.BEST_AVG_SPEED_IN_YARDS, bbs.BEST_AVG_SPEED_IN_MILES
      from CALC_RACE_BEST_BIRD_SPEED_INT(:ID_RACE, :ID_EVENT_INVENTORY, :ONLY_HOT_SPOT_PAID, :BIRDS_COUNT) bbs
      into :ID_EVENT_INVENTORY_ITEM, :BEST_BIRD_POSITION, :BEST_FLIGHT_TIME, :BEST_FLIGHT_DISTANCE,
        :BEST_AVG_SPEED_IN_YARDS, :BEST_AVG_SPEED_IN_MILES
    do begin
      suspend;
    end
  end
end ^

ALTER PROCEDURE BREEDER_EVENT_LIST_GET (ID_BREEDER INTEGER)
RETURNS (EVENT_LIST VARCHAR(1000) CHARACTER SET NONE)
AS 
declare variable EVENT_NAME varchar(50);
begin
  EVENT_LIST = '';
  for select distinct(e.EVENT_NAME)
    from EVENT_INVENTORY ei
    join EVENTS e on e.ID_EVENT = ei.ID_EVENT
    where ei.ID_BREEDER = :ID_BREEDER
    into :EVENT_NAME
  do begin
    if (EVENT_LIST <> '') then begin
      EVENT_LIST = EVENT_LIST || ',';
    end
    EVENT_LIST = EVENT_LIST || EVENT_NAME;
  end
  suspend;
end ^

ALTER PROCEDURE BREEDER_MODIFY (ID_BREEDER INTEGER,
FIRST_NAME VARCHAR(20) CHARACTER SET NONE,
LAST_NAME VARCHAR(20) CHARACTER SET NONE,
COUNTRY VARCHAR(100) CHARACTER SET NONE,
IS_DEFAULT_ADDRESS_1 SMALLINT,
ADDRESS_1 VARCHAR(100) CHARACTER SET NONE,
CITY_1 VARCHAR(20) CHARACTER SET NONE,
STATE_1 VARCHAR(2) CHARACTER SET NONE,
ZIP_1 VARCHAR(10) CHARACTER SET NONE,
ADDRESS_2 VARCHAR(100) CHARACTER SET NONE,
CITY_2 VARCHAR(20) CHARACTER SET NONE,
STATE_2 VARCHAR(2) CHARACTER SET NONE,
ZIP_2 VARCHAR(10) CHARACTER SET NONE,
PHONE VARCHAR(20) CHARACTER SET NONE,
CELL VARCHAR(20) CHARACTER SET NONE,
FAX VARCHAR(20) CHARACTER SET NONE,
EMAIL VARCHAR(100) CHARACTER SET NONE,
EMAIL_2 VARCHAR(100) CHARACTER SET NONE,
WEB_ADDRESS VARCHAR(250) CHARACTER SET NONE,
SOCIAL_SECURITY_NUMBER VARCHAR(20) CHARACTER SET NONE,
STATUS SMALLINT,
STATUS_DATE DATE,
NOTE VARCHAR(250) CHARACTER SET NONE,
LOGIN_NAME VARCHAR(50) CHARACTER SET NONE,
LOGIN_PASSWORD VARCHAR(50) CHARACTER SET NONE,
ID_PICTURE INTEGER,
SMS VARCHAR(250) CHARACTER SET NONE,
TAX_NUMBER VARCHAR(20) CHARACTER SET NONE,
DEF_NAME_AGN VARCHAR(100) CHARACTER SET NONE,
DEF_NAME_AS VARCHAR(100) CHARACTER SET NONE,
OPERATION VARCHAR(3) CHARACTER SET NONE)
RETURNS (NEW_ID_BREEDER INTEGER)
AS 
declare variable NUMBER integer;
begin
  NEW_ID_BREEDER = ID_BREEDER;
  if (OPERATION = 'add') then begin
    NEW_ID_BREEDER = gen_id(GEN_BREEDER_ID, 1);
    select max(b.NUMBER)
      from BREEDERS b
      into :NUMBER;
    if (NUMBER is null) then begin
      NUMBER = 1;
    end else begin
      NUMBER = NUMBER + 1;
    end
    insert into BREEDERS
      (ID_BREEDER, NUMBER, FIRST_NAME, LAST_NAME, COUNTRY, IS_DEFAULT_ADDRESS_1, ADDRESS_1,
      CITY_1, STATE_1, ZIP_1, ADDRESS_2, CITY_2, STATE_2, ZIP_2, PHONE, CELL, FAX,
      EMAIL, EMAIL_2, WEB_ADDRESS, SOCIAL_SECURITY_NUMBER, STATUS, STATUS_DATE, NOTE,
      LOGIN_NAME, LOGIN_PASSWORD, ID_PICTURE, SMS, TAX_NUMBER, DEF_NAME_AGN, DEF_NAME_AS)
    values
      (:NEW_ID_BREEDER, :NUMBER, :FIRST_NAME, :LAST_NAME, :COUNTRY, :IS_DEFAULT_ADDRESS_1,
      :ADDRESS_1, :CITY_1, :STATE_1, :ZIP_1, :ADDRESS_2, :CITY_2, :STATE_2, :ZIP_2,
      :PHONE, :CELL, :FAX, :EMAIL, :EMAIL_2, :WEB_ADDRESS, :SOCIAL_SECURITY_NUMBER,
      :STATUS, :STATUS_DATE, :NOTE, :LOGIN_NAME, :LOGIN_PASSWORD, :ID_PICTURE, :SMS, :TAX_NUMBER,
      :DEF_NAME_AGN, :DEF_NAME_AS);
  end else if (OPERATION = 'mod') then begin
    update BREEDERS
    set FIRST_NAME = :FIRST_NAME,
        LAST_NAME = :LAST_NAME,
        COUNTRY = :COUNTRY,
        IS_DEFAULT_ADDRESS_1 = :IS_DEFAULT_ADDRESS_1,
        ADDRESS_1 = :ADDRESS_1,
        CITY_1 = :CITY_1,
        STATE_1 = :STATE_1,
        ZIP_1 = :ZIP_1,
        ADDRESS_2 = :ADDRESS_2,
        CITY_2 = :CITY_2,
        STATE_2 = :STATE_2,
        ZIP_2 = :ZIP_2,
        PHONE = :PHONE,
        CELL = :CELL,
        FAX = :FAX,
        EMAIL = :EMAIL,
        EMAIL_2 = :EMAIL_2,
        WEB_ADDRESS = :WEB_ADDRESS,
        SOCIAL_SECURITY_NUMBER = :SOCIAL_SECURITY_NUMBER,
        STATUS = :STATUS,
        STATUS_DATE = :STATUS_DATE,
        NOTE = :NOTE,
        LOGIN_NAME = :LOGIN_NAME,
        LOGIN_PASSWORD = :LOGIN_PASSWORD,
        ID_PICTURE = :ID_PICTURE,
        SMS = :SMS,
        TAX_NUMBER = :TAX_NUMBER,
        DEF_NAME_AGN = :DEF_NAME_AGN,
        DEF_NAME_AS = :DEF_NAME_AS
    where ID_BREEDER = :ID_BREEDER;
  end else if (OPERATION = 'del') then begin
    select b.NUMBER, b.ID_PICTURE
      from BREEDERS b
      where b.ID_BREEDER = :ID_BREEDER
      into :NUMBER, :ID_PICTURE;
    execute procedure BREEDER_NUMBERS_REGEN(:NUMBER);
    delete from BREEDERS
      where ID_BREEDER = :ID_BREEDER;
    delete from PICTURE p
      where p.ID_PICTURE = :ID_PICTURE;
  end
  suspend;
end ^

ALTER PROCEDURE BREEDER_NUMBERS_REGEN (START_NUMBER INTEGER)
AS 
declare variable NUMBER integer;
declare variable ID_BREEDER integer;
begin
  NUMBER = 1;
  if (START_NUMBER is not null) then begin
    NUMBER = START_NUMBER;
  end
  for select b.ID_BREEDER
    from BREEDERS b
    where (:START_NUMBER is null) or (b.NUMBER > :START_NUMBER)
    into :ID_BREEDER
  do begin
    update BREEDERS b
      set b.NUMBER = :NUMBER
      where b.ID_BREEDER = :ID_BREEDER;
    NUMBER = NUMBER + 1;
  end
end ^

ALTER PROCEDURE CALC_AVG_SPEED_INT (DISTANCE INTEGER,
START_TIME TIMESTAMP,
ARRIVAL_TIME TIMESTAMP,
SUNRISE_TIME TIME,
SUNSET_TIME TIME)
RETURNS (AVG_SPEED_IN_YARDS NUMERIC(15, 4),
AVG_SPEED_IN_MILES NUMERIC(15, 4),
FLIGHT_TIME BIGINT)
AS 
begin
  AVG_SPEED_IN_YARDS = null;
  AVG_SPEED_IN_MILES = null;

  if ((ARRIVAL_TIME is not null) and (DISTANCE is not null) and (DISTANCE > 0)) then begin
    execute procedure CALC_FLIGHT_TIME(:START_TIME, :ARRIVAL_TIME, :SUNRISE_TIME, :SUNSET_TIME)
    returning_values :FLIGHT_TIME;

    execute procedure CALC_SPEED_INT(:DISTANCE, :FLIGHT_TIME)
    returning_values :AVG_SPEED_IN_YARDS, :AVG_SPEED_IN_MILES;
  end

  suspend;
end ^

ALTER PROCEDURE CALC_FLIGHT_TIME (START_TIME TIMESTAMP,
ARRIVAL_TIME TIMESTAMP,
SUNRISE_TIME TIME,
SUNSET_TIME TIME)
RETURNS (FLIGHT_TIME BIGINT)
AS 
declare variable TMP_DATE date;
declare variable TMP_FROM timestamp;
declare variable TMP_TO timestamp;
begin
  FLIGHT_TIME = 0;
  if (ARRIVAL_TIME is not null) then begin
    if ((SUNRISE_TIME is not null) and (SUNSET_TIME is not null)) then begin
      TMP_DATE = START_TIME;
      while (:TMP_DATE <= cast(:ARRIVAL_TIME as date)) do begin
        TMP_FROM = START_TIME;
        if (TMP_FROM < (TMP_DATE + SUNRISE_TIME)) then begin
          TMP_FROM = TMP_DATE + SUNRISE_TIME;
        end
        TMP_TO = ARRIVAL_TIME;
        if (TMP_TO > (TMP_DATE + SUNSET_TIME)) then begin
          TMP_TO = (TMP_DATE + SUNSET_TIME);
        end
        if (TMP_TO > TMP_FROM) then begin
          FLIGHT_TIME = FLIGHT_TIME + ((TMP_TO - TMP_FROM) * 24 * 60 * 60 * 1000);
        end
        TMP_DATE = TMP_DATE + 1; /* get next day */
      end
    end else begin
      FLIGHT_TIME = (ARRIVAL_TIME - START_TIME) * 24 * 60 * 60 * 1000;
    end
  end
end ^

ALTER PROCEDURE CALC_RACE_AVG_SPEED_INT (SELECTED_TAG VARCHAR(50) CHARACTER SET NONE,
ONLY_HOT_SPOT_BIRDS SMALLINT)
RETURNS (ID_EVENT_INVENTORY_ITEM INTEGER,
RACE_COUNT INTEGER,
TOTAL_FLIGHT_TIME BIGINT,
TOTAL_FLIGHT_DISTANCE INTEGER,
AVG_SPEED_IN_YARDS NUMERIC(15, 4),
AVG_SPEED_IN_MILES NUMERIC(15, 4))
AS 
declare variable TMP_ID_EVENT_INVENTORY_ITEM integer;
declare variable DISTANCE integer;
declare variable START_TIME timestamp;
declare variable ARRIVAL_TIME timestamp;
declare variable SUNRISE_TIME time;
declare variable SUNSET_TIME time;
declare variable FLIGHT_TIME integer;
begin
 TMP_ID_EVENT_INVENTORY_ITEM = null;
 RACE_COUNT = 0;
 TOTAL_FLIGHT_TIME = 0;
 TOTAL_FLIGHT_DISTANCE = 0;
 AVG_SPEED_IN_YARDS = null;
 AVG_SPEED_IN_MILES = null;

 for select ri.ID_INVENTORY_ITEM, r.DISTANCE, r.START_TIME, r.SUNRISE, r.SUNSET, rir.ARRIVAL_TIME
   from RACE r
   join TMP_ID tid on tid.ID = r.ID_RACE and tid.TAG = :SELECTED_TAG
   join RACE_ITEM ri on ri.ID_RACE = r.ID_RACE
   join RACE_ITEM_RESULT rir on rir.ID_RACE_ITEM = ri.ID_RACE_ITEM
   join EVENT_INVENTORY_ITEM eii on eii.ID_EVENT_INVENTORY_ITEM = ri.ID_INVENTORY_ITEM
   where (coalesce(r.DISTANCE, 0) > 0) and (rir.BIRD_POSITION is not null) and ((coalesce(:ONLY_HOT_SPOT_BIRDS, 0) <> 1) or (eii.HOT_SPOT_FEE_VALUE is not null))
   order by ri.ID_INVENTORY_ITEM
   into :TMP_ID_EVENT_INVENTORY_ITEM, :DISTANCE, :START_TIME, :SUNRISE_TIME, :SUNSET_TIME, :ARRIVAL_TIME
 do begin
   if (ID_EVENT_INVENTORY_ITEM is null) then begin
     ID_EVENT_INVENTORY_ITEM = TMP_ID_EVENT_INVENTORY_ITEM;
   end
   if (TMP_ID_EVENT_INVENTORY_ITEM <> ID_EVENT_INVENTORY_ITEM) then begin
     execute procedure CALC_SPEED_INT(:TOTAL_FLIGHT_DISTANCE, :TOTAL_FLIGHT_TIME)
     returning_values :AVG_SPEED_IN_YARDS, :AVG_SPEED_IN_MILES;
     suspend;
     ID_EVENT_INVENTORY_ITEM = TMP_ID_EVENT_INVENTORY_ITEM;
     RACE_COUNT = 0;
     TOTAL_FLIGHT_TIME = 0;
     TOTAL_FLIGHT_DISTANCE = 0;
     AVG_SPEED_IN_YARDS = null;
     AVG_SPEED_IN_MILES = null;
   end
   RACE_COUNT = RACE_COUNT + 1;
   TOTAL_FLIGHT_DISTANCE = TOTAL_FLIGHT_DISTANCE + DISTANCE;
   execute procedure CALC_FLIGHT_TIME(:START_TIME, :ARRIVAL_TIME, :SUNRISE_TIME, :SUNSET_TIME)
   returning_values :FLIGHT_TIME;
   TOTAL_FLIGHT_TIME = TOTAL_FLIGHT_TIME + FLIGHT_TIME;
 end

 if (ID_EVENT_INVENTORY_ITEM is not null) then begin
   execute procedure CALC_SPEED_INT(:TOTAL_FLIGHT_DISTANCE, :TOTAL_FLIGHT_TIME)
   returning_values :AVG_SPEED_IN_YARDS, :AVG_SPEED_IN_MILES;
   suspend;
 end
end ^

ALTER PROCEDURE CALC_RACE_BEST_BIRD_SPEED_INT (ID_RACE INTEGER,
ID_EVENT_INVENTORY INTEGER,
ONLY_HOT_SPOT_BIRDS SMALLINT,
BIRDS_COUNT INTEGER)
RETURNS (ID_EVENT_INVENTORY_ITEM INTEGER,
BEST_BIRD_POSITION INTEGER,
BEST_FLIGHT_TIME BIGINT,
BEST_FLIGHT_DISTANCE INTEGER,
BEST_AVG_SPEED_IN_YARDS NUMERIC(15, 4),
BEST_AVG_SPEED_IN_MILES NUMERIC(15, 4))
AS 
declare variable BIRD_POSITION integer;
declare variable DISTANCE integer;
declare variable START_TIME timestamp;
declare variable ARRIVAL_TIME timestamp;
declare variable SUNRISE_TIME time;
declare variable SUNSET_TIME time;
declare variable TMP_FLIGHT_TIME bigint;
declare variable TMP_AVG_SPEED_IN_YARDS numeric(15,4);
declare variable TMP_AVG_SPEED_IN_MILES numeric(15,4);
declare variable TMP_ID_EVENT_INVENTORY_ITEM integer;
declare variable TMP_BIRDS_COUNT integer;
begin
  ID_EVENT_INVENTORY_ITEM = null;
  BEST_BIRD_POSITION = null;
  BEST_FLIGHT_TIME = 0;
  BEST_FLIGHT_DISTANCE = 0;
  BEST_AVG_SPEED_IN_YARDS = null;
  BEST_AVG_SPEED_IN_MILES = null;

  delete from TMP_AVG_SPEED;

  for select rir.BIRD_POSITION, eii.ID_EVENT_INVENTORY_ITEM, r.DISTANCE, r.START_TIME, r.SUNRISE, r.SUNSET, rir.ARRIVAL_TIME
    from RACE r
    join RACE_ITEM ri on ri.ID_RACE = r.ID_RACE
    join RACE_ITEM_RESULT rir on rir.ID_RACE_ITEM = ri.ID_RACE_ITEM
    join EVENT_INVENTORY_ITEM eii on eii.ID_EVENT_INVENTORY_ITEM = ri.ID_INVENTORY_ITEM
  where r.ID_RACE = :ID_RACE
    and (coalesce(r.DISTANCE, 0) > 0)
    and (eii.ID_EVENT_INVENTORY = :ID_EVENT_INVENTORY)
    and (rir.BIRD_POSITION is not null)
    and ((coalesce(:ONLY_HOT_SPOT_BIRDS, 0) <> 1) or (eii.HOT_SPOT_FEE_VALUE is not null))
  into :BIRD_POSITION, :TMP_ID_EVENT_INVENTORY_ITEM, :DISTANCE, :START_TIME, :SUNRISE_TIME, :SUNSET_TIME, :ARRIVAL_TIME
  do begin
    execute procedure CALC_AVG_SPEED_INT(:DISTANCE, :START_TIME, :ARRIVAL_TIME, :SUNRISE_TIME, :SUNSET_TIME)
    returning_values :TMP_AVG_SPEED_IN_YARDS, :TMP_AVG_SPEED_IN_MILES, :TMP_FLIGHT_TIME;

    insert into TMP_AVG_SPEED(ID_EVENT_INVENTORY_ITEM, BIRD_POSITION, FLIGHT_TIME, FLIGHT_DISTANCE, AVG_SPEED_IN_YARDS, AVG_SPEED_IN_MILES)
    values (:TMP_ID_EVENT_INVENTORY_ITEM, :BIRD_POSITION, :TMP_FLIGHT_TIME, :DISTANCE, :TMP_AVG_SPEED_IN_YARDS, :TMP_AVG_SPEED_IN_MILES);
  end

  TMP_BIRDS_COUNT = 1;
  for select tas.ID_EVENT_INVENTORY_ITEM, tas.BIRD_POSITION, tas.FLIGHT_TIME, tas.FLIGHT_DISTANCE,
    tas.AVG_SPEED_IN_YARDS, tas.AVG_SPEED_IN_MILES
    from TMP_AVG_SPEED tas
    order by tas.AVG_SPEED_IN_YARDS desc
    into :ID_EVENT_INVENTORY_ITEM, :BEST_BIRD_POSITION, :BEST_FLIGHT_TIME, :BEST_FLIGHT_DISTANCE,
      :BEST_AVG_SPEED_IN_YARDS, :BEST_AVG_SPEED_IN_MILES
  do begin
    if (TMP_BIRDS_COUNT <= BIRDS_COUNT) then begin
      suspend;
      TMP_BIRDS_COUNT = TMP_BIRDS_COUNT + 1;
    end else begin
      break;
    end
  end
  delete from TMP_AVG_SPEED;
end ^

ALTER PROCEDURE CALC_RACE_BREEDER_SPEED_INT (SELECTED_TAG VARCHAR(50) CHARACTER SET NONE,
ONLY_HOT_SPOT_BIRDS SMALLINT,
BIRDS_COUNT INTEGER)
RETURNS (ID_EVENT_INVENTORY INTEGER,
RACE_COUNT INTEGER,
BIRDS_COUNT_OUT INTEGER,
TOTAL_FLIGHT_TIME BIGINT,
TOTAL_FLIGHT_DISTANCE INTEGER,
AVG_SPEED_IN_YARDS NUMERIC(15, 4),
AVG_SPEED_IN_MILES NUMERIC(15, 4))
AS 
declare variable TMP_ID_EVENT_INVENTORY integer;
declare variable TMP_ID_RACE integer;
declare variable ID_RACE integer;
declare variable BEST_FLIGHT_TIME bigint;
declare variable BEST_FLIGHT_DISTANCE integer;
begin
  TMP_ID_EVENT_INVENTORY = null;
  TMP_ID_RACE = null;
  RACE_COUNT = 0;
  BIRDS_COUNT_OUT = 0;
  TOTAL_FLIGHT_TIME = 0;
  TOTAL_FLIGHT_DISTANCE = 0;
  AVG_SPEED_IN_YARDS = null;
  AVG_SPEED_IN_MILES = null;

  for select distinct eii.ID_EVENT_INVENTORY, r.ID_RACE
    from RACE r
    join TMP_ID tid on tid.ID = r.ID_RACE and tid.TAG = :SELECTED_TAG
    join RACE_ITEM ri on ri.ID_RACE = r.ID_RACE
    join RACE_ITEM_RESULT rir on rir.ID_RACE_ITEM = ri.ID_RACE_ITEM
    join EVENT_INVENTORY_ITEM eii on eii.ID_EVENT_INVENTORY_ITEM = ri.ID_INVENTORY_ITEM
    where (coalesce(r.DISTANCE, 0) > 0) and (rir.BIRD_POSITION is not null) and ((coalesce(:ONLY_HOT_SPOT_BIRDS, 0) <> 1) or (eii.HOT_SPOT_FEE_VALUE is not null))
    order by eii.ID_EVENT_INVENTORY, r.ID_RACE
    into :TMP_ID_EVENT_INVENTORY, :ID_RACE
  do begin
    if (ID_EVENT_INVENTORY is null) then begin
      ID_EVENT_INVENTORY = TMP_ID_EVENT_INVENTORY;
    end
    if (TMP_ID_EVENT_INVENTORY <> ID_EVENT_INVENTORY) then begin
      execute procedure CALC_SPEED_INT(:TOTAL_FLIGHT_DISTANCE, :TOTAL_FLIGHT_TIME)
      returning_values :AVG_SPEED_IN_YARDS, :AVG_SPEED_IN_MILES;
      suspend;
      ID_EVENT_INVENTORY = TMP_ID_EVENT_INVENTORY;
      RACE_COUNT = 0;
      BIRDS_COUNT_OUT = 0;
      TOTAL_FLIGHT_TIME = 0;
      TOTAL_FLIGHT_DISTANCE = 0;
      AVG_SPEED_IN_YARDS = null;
      AVG_SPEED_IN_MILES = null;
      TMP_ID_RACE = null;
    end
    if ((TMP_ID_RACE is null) or (TMP_ID_RACE <> ID_RACE)) then begin
      RACE_COUNT = RACE_COUNT + 1;
      TMP_ID_RACE = ID_RACE;
    end

    for select bbs.BEST_FLIGHT_TIME, bbs.BEST_FLIGHT_DISTANCE
      from CALC_RACE_BEST_BIRD_SPEED_INT(:ID_RACE, :ID_EVENT_INVENTORY, :ONLY_HOT_SPOT_BIRDS, :BIRDS_COUNT) bbs
      into :BEST_FLIGHT_TIME, :BEST_FLIGHT_DISTANCE
    do begin
      TOTAL_FLIGHT_DISTANCE = TOTAL_FLIGHT_DISTANCE + BEST_FLIGHT_DISTANCE;
      TOTAL_FLIGHT_TIME = TOTAL_FLIGHT_TIME + BEST_FLIGHT_TIME;
      BIRDS_COUNT_OUT = BIRDS_COUNT_OUT + 1;
    end
  end

  if (ID_EVENT_INVENTORY is not null) then begin
    execute procedure CALC_SPEED_INT(:TOTAL_FLIGHT_DISTANCE, :TOTAL_FLIGHT_TIME)
    returning_values :AVG_SPEED_IN_YARDS, :AVG_SPEED_IN_MILES;
    suspend;
  end
end ^

ALTER PROCEDURE CALC_SPEED_INT (DISTANCE INTEGER,
FLIGHT_TIME BIGINT)
RETURNS (AVG_SPEED_IN_YARDS NUMERIC(15, 4),
AVG_SPEED_IN_MILES NUMERIC(15, 4))
AS 
begin
  AVG_SPEED_IN_YARDS = null;
  AVG_SPEED_IN_MILES = null;

  if ((coalesce(DISTANCE, 0) > 0) and (coalesce(FLIGHT_TIME, 0) > 0)) then begin
    AVG_SPEED_IN_YARDS = cast((DISTANCE * 1760 * 60 * 1000) as numeric(15, 4)) / FLIGHT_TIME;
    AVG_SPEED_IN_MILES = cast((DISTANCE * 60 * 60 * 1000) as numeric(15, 4)) / FLIGHT_TIME;
  end

  suspend;
end ^

ALTER PROCEDURE ENTRY_FEE_BATCH_SET (ID_EVENT INTEGER,
OPERATION VARCHAR(20) CHARACTER SET NONE)
RETURNS (ERR_CODE INTEGER,
ERR_TEXT VARCHAR(255) CHARACTER SET NONE)
AS 
declare variable ENTRY_FEE numeric(15, 4);
declare variable HOT_SPOT_FEE numeric(15, 4);
declare variable ID_EVENT_INVENTORY_ITEM integer;
begin
  ERR_CODE = 0;
  ERR_TEXT = '';
  select fs.ENTRY_FEE, FS.HOT_SPOT1_FEE
    from EVENTS e
    join FEE_SCHEME fs on fs.ID_FEE_SCHEME = e.ID_FEE_SCHEME
    where e.ID_EVENT = :ID_EVENT
    into :ENTRY_FEE, :HOT_SPOT_FEE;

  if (OPERATION = 'post_entry') then begin
    if (ENTRY_FEE is null) then begin
      ERR_CODE = 1;
      ERR_TEXT = 'Unable to find entry fee for event with ID ' || :ID_EVENT ;
    end
    for select eii.ID_EVENT_INVENTORY_ITEM
      from EVENT_INVENTORY ei
      join EVENT_INVENTORY_ITEM eii on eii.ID_EVENT_INVENTORY = ei.ID_EVENT_INVENTORY
      join BIRDS b on b.ID_BIRD = eii.ID_BIRD
      where ei.ID_EVENT = :ID_EVENT
        and b.IS_LOST = 0
        and b.IS_ACTIVE = 1
        and eii.ID_REPLACED_ITEM is null
        and eii.DEPARTURE_DATE is null
      into :ID_EVENT_INVENTORY_ITEM
    do begin
      update EVENT_INVENTORY_ITEM eii
        set eii.ENTRY_FEE_VALUE = :ENTRY_FEE
        where eii.ID_EVENT_INVENTORY_ITEM = :ID_EVENT_INVENTORY_ITEM;
    end
  end else if (OPERATION = 'post_hot_spot') then begin
    if (HOT_SPOT_FEE is null) then begin
      ERR_CODE = 1;
      ERR_TEXT = 'Unable to find hot spot fee for event with ID ' || :ID_EVENT ;
    end
    for select eii.ID_EVENT_INVENTORY_ITEM
      from EVENT_INVENTORY ei
      join EVENT_INVENTORY_ITEM eii on eii.ID_EVENT_INVENTORY = ei.ID_EVENT_INVENTORY
      join BIRDS b on b.ID_BIRD = eii.ID_BIRD
      where ei.ID_EVENT = :ID_EVENT
        and b.IS_LOST = 0
        and b.IS_ACTIVE = 1
        and eii.ID_REPLACED_ITEM is null
        and eii.DEPARTURE_DATE is null
      into :ID_EVENT_INVENTORY_ITEM
    do begin
      update EVENT_INVENTORY_ITEM eii
        set eii.HOT_SPOT_FEE_VALUE = :HOT_SPOT_FEE
        where eii.ID_EVENT_INVENTORY_ITEM = :ID_EVENT_INVENTORY_ITEM;
    end
  end
end ^

ALTER PROCEDURE EVENTS_MODIFY (ID_EVENT INTEGER,
EVENT_NAME VARCHAR(50) CHARACTER SET NONE,
EVENT_SHORT_NAME VARCHAR(10) CHARACTER SET NONE,
EVENT_DATE DATE,
ID_FEE_SCHEME INTEGER,
ID_FINAL_PRIZE_SCHEME INTEGER,
ID_HOT_SPOT1_PRIZE_SCHEME INTEGER,
ID_HOT_SPOT2_PRIZE_SCHEME INTEGER,
ID_HOT_SPOT3_PRIZE_SCHEME INTEGER,
ID_HOT_SPOT_AVG_PRIZE_SCHEME INTEGER,
ID_BETTING_SCHEME INTEGER,
IS_OPEN SMALLINT,
EVENT_TYPE SMALLINT,
OPERATION VARCHAR(3) CHARACTER SET NONE)
RETURNS (NEW_ID_EVENT INTEGER)
AS 
begin
  NEW_ID_EVENT = ID_EVENT;
  if (OPERATION = 'add') then begin
    NEW_ID_EVENT = gen_id(GEN_EVENT_ID, 1);
    insert into EVENTS
      (ID_EVENT, EVENT_NAME, EVENT_SHORT_NAME, EVENT_DATE, ID_FEE_SCHEME,
       ID_FINAL_PRIZE_SCHEME, ID_HOT_SPOT1_PRIZE_SCHEME, ID_HOT_SPOT2_PRIZE_SCHEME,
       ID_HOT_SPOT3_PRIZE_SCHEME, ID_HOT_SPOT_AVG_PRIZE_SCHEME, ID_BETTING_SCHEME, IS_OPEN,
       EVENT_TYPE)
    values
      (:NEW_ID_EVENT, :EVENT_NAME, :EVENT_SHORT_NAME, :EVENT_DATE, :ID_FEE_SCHEME,
       :ID_FINAL_PRIZE_SCHEME, :ID_HOT_SPOT1_PRIZE_SCHEME, :ID_HOT_SPOT2_PRIZE_SCHEME,
       :ID_HOT_SPOT3_PRIZE_SCHEME, :ID_HOT_SPOT_AVG_PRIZE_SCHEME, :ID_BETTING_SCHEME, :IS_OPEN,
       :EVENT_TYPE);
  end else if (OPERATION = 'mod') then begin
    update EVENTS
    set EVENT_NAME = :EVENT_NAME,
        EVENT_SHORT_NAME = :EVENT_SHORT_NAME,
        EVENT_DATE = :EVENT_DATE,
        ID_FEE_SCHEME = :ID_FEE_SCHEME,
        ID_FINAL_PRIZE_SCHEME = :ID_FINAL_PRIZE_SCHEME,
        ID_HOT_SPOT1_PRIZE_SCHEME = :ID_HOT_SPOT1_PRIZE_SCHEME,
        ID_HOT_SPOT2_PRIZE_SCHEME = :ID_HOT_SPOT2_PRIZE_SCHEME,
        ID_HOT_SPOT3_PRIZE_SCHEME = :ID_HOT_SPOT3_PRIZE_SCHEME,
        ID_HOT_SPOT_AVG_PRIZE_SCHEME = :ID_HOT_SPOT_AVG_PRIZE_SCHEME,
        ID_BETTING_SCHEME = :ID_BETTING_SCHEME,
        IS_OPEN = :IS_OPEN,
        EVENT_TYPE = :EVENT_TYPE
    where (ID_EVENT = :ID_EVENT);
  end else if (OPERATION = 'del') then begin
    delete from EVENTS
    where (ID_EVENT = :ID_EVENT);
  end
  suspend;
end ^

ALTER PROCEDURE EVENT_BET_TOTALS (ID_EVENT INTEGER)
RETURNS (BELGIAN_SHOW_1 NUMERIC(15, 4),
BELGIAN_SHOW_2 NUMERIC(15, 4),
BELGIAN_SHOW_3 NUMERIC(15, 4),
BELGIAN_SHOW_4 NUMERIC(15, 4),
BELGIAN_SHOW_5 NUMERIC(15, 4),
BELGIAN_SHOW_6 NUMERIC(15, 4),
BELGIAN_SHOW_7 NUMERIC(15, 4),
STANDARD_SHOW_1 NUMERIC(15, 4),
STANDARD_SHOW_2 NUMERIC(15, 4),
STANDARD_SHOW_3 NUMERIC(15, 4),
STANDARD_SHOW_4 NUMERIC(15, 4),
STANDARD_SHOW_5 NUMERIC(15, 4),
STANDARD_SHOW_6 NUMERIC(15, 4),
WTA_1 NUMERIC(15, 4),
WTA_2 NUMERIC(15, 4),
WTA_3 NUMERIC(15, 4),
WTA_4 NUMERIC(15, 4),
WTA_5 NUMERIC(15, 4),
BELGIAN_SHOW_1_WO_COM NUMERIC(15, 4),
BELGIAN_SHOW_2_WO_COM NUMERIC(15, 4),
BELGIAN_SHOW_3_WO_COM NUMERIC(15, 4),
BELGIAN_SHOW_4_WO_COM NUMERIC(15, 4),
BELGIAN_SHOW_5_WO_COM NUMERIC(15, 4),
BELGIAN_SHOW_6_WO_COM NUMERIC(15, 4),
BELGIAN_SHOW_7_WO_COM NUMERIC(15, 4),
STANDARD_SHOW_1_WO_COM NUMERIC(15, 4),
STANDARD_SHOW_2_WO_COM NUMERIC(15, 4),
STANDARD_SHOW_3_WO_COM NUMERIC(15, 4),
STANDARD_SHOW_4_WO_COM NUMERIC(15, 4),
STANDARD_SHOW_5_WO_COM NUMERIC(15, 4),
STANDARD_SHOW_6_WO_COM NUMERIC(15, 4),
WTA_1_WO_COM NUMERIC(15, 4),
WTA_2_WO_COM NUMERIC(15, 4),
WTA_3_WO_COM NUMERIC(15, 4),
WTA_4_WO_COM NUMERIC(15, 4),
WTA_5_WO_COM NUMERIC(15, 4))
AS 
declare variable CNT_BELGIAN_SHOW_BET_1 integer;
  declare variable CNT_BELGIAN_SHOW_BET_2 integer;
  declare variable CNT_BELGIAN_SHOW_BET_3 integer;
  declare variable CNT_BELGIAN_SHOW_BET_4 integer;
  declare variable CNT_BELGIAN_SHOW_BET_5 integer;
  declare variable CNT_BELGIAN_SHOW_BET_6 integer;
  declare variable CNT_BELGIAN_SHOW_BET_7 integer;
  declare variable CNT_STANDARD_SHOW_BET_1 integer;
  declare variable CNT_STANDARD_SHOW_BET_2 integer;
  declare variable CNT_STANDARD_SHOW_BET_3 integer;
  declare variable CNT_STANDARD_SHOW_BET_4 integer;
  declare variable CNT_STANDARD_SHOW_BET_5 integer;
  declare variable CNT_STANDARD_SHOW_BET_6 integer;
  declare variable CNT_WTA_BET_1 integer;
  declare variable CNT_WTA_BET_2 integer;
  declare variable CNT_WTA_BET_3 integer;
  declare variable CNT_WTA_BET_4 integer;
  declare variable CNT_WTA_BET_5 integer;
  declare variable BETTING_CUT_PERCENT numeric(15, 4);
begin
  select sum(eii.BELGIAN_SHOW_BET_1), sum(eii.BELGIAN_SHOW_BET_2), sum(eii.BELGIAN_SHOW_BET_3),
       sum(eii.BELGIAN_SHOW_BET_4), sum(eii.BELGIAN_SHOW_BET_5), sum(eii.BELGIAN_SHOW_BET_6),
       sum(eii.BELGIAN_SHOW_BET_7), sum(eii.STANDARD_SHOW_BET_1), sum(eii.STANDARD_SHOW_BET_2),
       sum(eii.STANDARD_SHOW_BET_3), sum(eii.STANDARD_SHOW_BET_4), sum(eii.STANDARD_SHOW_BET_5),
       sum(eii.STANDARD_SHOW_BET_6), sum(eii.WTA_BET_1), sum(eii.WTA_BET_2), sum(eii.WTA_BET_3),
       sum(eii.WTA_BET_4), sum(eii.WTA_BET_5)
  from EVENT_INVENTORY_ITEM eii
  join EVENT_INVENTORY ei on ei.ID_EVENT_INVENTORY = eii.ID_EVENT_INVENTORY
  where ei.ID_EVENT = :ID_EVENT and eii.IS_BET_ACTIVE <> 0
  into :CNT_BELGIAN_SHOW_BET_1, :CNT_BELGIAN_SHOW_BET_2, :CNT_BELGIAN_SHOW_BET_3,
       :CNT_BELGIAN_SHOW_BET_4, :CNT_BELGIAN_SHOW_BET_5, :CNT_BELGIAN_SHOW_BET_6,
       :CNT_BELGIAN_SHOW_BET_7, :CNT_STANDARD_SHOW_BET_1, :CNT_STANDARD_SHOW_BET_2,
       :CNT_STANDARD_SHOW_BET_3, :CNT_STANDARD_SHOW_BET_4, :CNT_STANDARD_SHOW_BET_5,
       :CNT_STANDARD_SHOW_BET_6, :CNT_WTA_BET_1, :CNT_WTA_BET_2, :CNT_WTA_BET_3,
       :CNT_WTA_BET_4, :CNT_WTA_BET_5;

  select bs.BELGIAN_SHOW_1 * :CNT_BELGIAN_SHOW_BET_1,
         bs.BELGIAN_SHOW_2 * :CNT_BELGIAN_SHOW_BET_2,
         bs.BELGIAN_SHOW_3 * :CNT_BELGIAN_SHOW_BET_3,
         bs.BELGIAN_SHOW_4 * :CNT_BELGIAN_SHOW_BET_4,
         bs.BELGIAN_SHOW_5 * :CNT_BELGIAN_SHOW_BET_5,
         bs.BELGIAN_SHOW_6 * :CNT_BELGIAN_SHOW_BET_6,
         bs.BELGIAN_SHOW_7 * :CNT_BELGIAN_SHOW_BET_7,
         bs.STANDARD_SHOW_1 * :CNT_STANDARD_SHOW_BET_1,
         bs.STANDARD_SHOW_2 * :CNT_STANDARD_SHOW_BET_2,
         bs.STANDARD_SHOW_3 * :CNT_STANDARD_SHOW_BET_3,
         bs.STANDARD_SHOW_4 * :CNT_STANDARD_SHOW_BET_4,
         bs.STANDARD_SHOW_5 * :CNT_STANDARD_SHOW_BET_5,
         bs.STANDARD_SHOW_6 * :CNT_STANDARD_SHOW_BET_6,
         bs.WTA_1 * :CNT_WTA_BET_1,
         bs.WTA_2 * :CNT_WTA_BET_2,
         bs.WTA_3 * :CNT_WTA_BET_3,
         bs.WTA_4 * :CNT_WTA_BET_4,
         bs.WTA_5 * :CNT_WTA_BET_5,
         bs.BETTING_CUT_PERCENT
    from EVENTS e
    join BETTING_SCHEME bs on bs.ID_BETTING_SCHEME = e.ID_BETTING_SCHEME
    where e.ID_EVENT = :ID_EVENT
    into :BELGIAN_SHOW_1, :BELGIAN_SHOW_2, :BELGIAN_SHOW_3, :BELGIAN_SHOW_4,
      :BELGIAN_SHOW_5, :BELGIAN_SHOW_6, :BELGIAN_SHOW_7, :STANDARD_SHOW_1,
      :STANDARD_SHOW_2, :STANDARD_SHOW_3, :STANDARD_SHOW_4, :STANDARD_SHOW_5,
      :STANDARD_SHOW_6, :WTA_1, :WTA_2, :WTA_3, :WTA_4, :WTA_5,
      :BETTING_CUT_PERCENT;
  
  BELGIAN_SHOW_1_WO_COM = BELGIAN_SHOW_1 - ((BELGIAN_SHOW_1 * BETTING_CUT_PERCENT) / 100);
  BELGIAN_SHOW_2_WO_COM = BELGIAN_SHOW_2 - ((BELGIAN_SHOW_2 * BETTING_CUT_PERCENT) / 100);
  BELGIAN_SHOW_3_WO_COM = BELGIAN_SHOW_3 - ((BELGIAN_SHOW_3 * BETTING_CUT_PERCENT) / 100);
  BELGIAN_SHOW_4_WO_COM = BELGIAN_SHOW_4 - ((BELGIAN_SHOW_4 * BETTING_CUT_PERCENT) / 100);
  BELGIAN_SHOW_5_WO_COM = BELGIAN_SHOW_5 - ((BELGIAN_SHOW_5 * BETTING_CUT_PERCENT) / 100);
  BELGIAN_SHOW_6_WO_COM = BELGIAN_SHOW_6 - ((BELGIAN_SHOW_6 * BETTING_CUT_PERCENT) / 100);
  BELGIAN_SHOW_7_WO_COM = BELGIAN_SHOW_7 - ((BELGIAN_SHOW_7 * BETTING_CUT_PERCENT) / 100);
  STANDARD_SHOW_1_WO_COM = STANDARD_SHOW_1 - ((STANDARD_SHOW_1 * BETTING_CUT_PERCENT) / 100);
  STANDARD_SHOW_2_WO_COM = STANDARD_SHOW_2 - ((STANDARD_SHOW_2 * BETTING_CUT_PERCENT) / 100);
  STANDARD_SHOW_3_WO_COM = STANDARD_SHOW_3 - ((STANDARD_SHOW_3 * BETTING_CUT_PERCENT) / 100);
  STANDARD_SHOW_4_WO_COM = STANDARD_SHOW_4 - ((STANDARD_SHOW_4 * BETTING_CUT_PERCENT) / 100);
  STANDARD_SHOW_5_WO_COM = STANDARD_SHOW_5 - ((STANDARD_SHOW_5 * BETTING_CUT_PERCENT) / 100);
  STANDARD_SHOW_6_WO_COM = STANDARD_SHOW_6 - ((STANDARD_SHOW_6 * BETTING_CUT_PERCENT) / 100);
  WTA_1_WO_COM = WTA_1 - ((WTA_1 * BETTING_CUT_PERCENT) / 100);
  WTA_2_WO_COM = WTA_2 - ((WTA_2 * BETTING_CUT_PERCENT) / 100);
  WTA_3_WO_COM = WTA_3 - ((WTA_3 * BETTING_CUT_PERCENT) / 100);
  WTA_4_WO_COM = WTA_4 - ((WTA_4 * BETTING_CUT_PERCENT) / 100);
  WTA_5_WO_COM = WTA_5 - ((WTA_5 * BETTING_CUT_PERCENT) / 100);
  
  suspend;
end ^

ALTER PROCEDURE EVENT_INVENTORY_GET (ID_EVENT INTEGER,
IN_ID_EVENT_INVENTORY INTEGER)
RETURNS (ID_EVENT_INVENTORY INTEGER,
ID_BREEDER INTEGER,
BREEDER_NUMBER INTEGER,
FIRST_NAME VARCHAR(20) CHARACTER SET NONE,
LAST_NAME VARCHAR(20) CHARACTER SET NONE,
LOFT VARCHAR(30) CHARACTER SET NONE,
STATE VARCHAR(2) CHARACTER SET NONE,
SIGN_IN_DATE DATE,
IS_WAITING SMALLINT,
WAITING_DATE DATE,
RESERVED_BIRDS INTEGER,
IN_LOFT_BIRDS INTEGER,
LOST_BIRDS INTEGER,
REPLACED_BIRDS INTEGER,
PERCH_FEE_VALUE NUMERIC(15, 4),
ENTRY_FEE_VALUE NUMERIC(15, 4),
BETS_VALUE NUMERIC(15, 4),
HOT_SPOT_BIRDS INTEGER,
HOT_SPOT_VALUE NUMERIC(15, 4),
ENTRY_REFUND NUMERIC(15, 4),
BETS_REFUND NUMERIC(15, 4),
HOT_SPOT_REFUND NUMERIC(15, 4),
PERCH_FEE_PAY_VALUE NUMERIC(15, 4),
ENTRY_FEE_PAY_VALUE NUMERIC(15, 4),
BETS_PAY_VALUE NUMERIC(15, 4),
HOT_SPOT_PAY_VALUE NUMERIC(15, 4),
ENTRY_REFUND_PAY_VALUE NUMERIC(15, 4),
BETS_REFUND_PAY_VALUE NUMERIC(15, 4),
HOT_SPOT_REFUND_PAY_VALUE NUMERIC(15, 4),
ENTRY_BIRDS INTEGER,
NOTE VARCHAR(250) CHARACTER SET NONE,
PARTNER_LIST VARCHAR(1000) CHARACTER SET NONE,
TRANSFER_DUE NUMERIC(15, 4),
TRANSFER_DUE_PAY_VALUE NUMERIC(15, 4),
CAPITAL_PRIZE NUMERIC(15, 4),
HOT_SPOT_1_PRIZE NUMERIC(15, 4),
HOT_SPOT_2_PRIZE NUMERIC(15, 4),
HOT_SPOT_3_PRIZE NUMERIC(15, 4),
AVG_SPEED_WINNER_PRIZE NUMERIC(15, 4),
BETS_PRIZE NUMERIC(15, 4),
WINNER_PAYOUT_VALUE NUMERIC(15, 4),
WINNER_PAYOUT_PAY_VALUE NUMERIC(15, 4),
TOTAL_PAYMENT_VALUE NUMERIC(15, 4),
BALANCE_VALUE NUMERIC(15, 4))
AS 
declare variable EXEC_TIME timestamp;
declare variable BIRD_BETS_PAYOUT_TOTAL numeric(15, 4);
declare variable ID_EVENT_INVENTORY_ITEM integer;
declare variable ID_FINAL_RACE integer;
begin
  select r.ID_RACE
    from RACE r
    where r.ID_EVENT = :ID_EVENT and r.ID_RACE_TYPE = 5
    into :ID_FINAL_RACE;

  if (ID_FINAL_RACE is not null) then begin
    /* etting payout is allowed only on final race */
    execute procedure TMP_BETS_BY_EVENT_INSERT(:ID_EVENT)
    returning_values :EXEC_TIME;
  end

  for select ei.ID_EVENT_INVENTORY,
             ei.ID_BREEDER,
             b.NUMBER,
             b.FIRST_NAME,
             b.LAST_NAME,
             ei.LOFT,
             iif(b.IS_DEFAULT_ADDRESS_1 > 0, b.STATE_1, b.STATE_2) as STATE,
             ei.SIGN_IN_DATE,
             ei.IS_WAITING,
             ei.WAITING_DATE,
             ei.RESERVED_BIRDS,
             ei.NOTE,
             sum(eii.PERCH_FEE_VALUE) as PERCH_FEE_VALUE,
             sum(eii.ENTRY_FEE_VALUE) as ENTRY_FEE_VALUE,
             sum(eii.ENTRY_REFUND) as ENTRY_REFUND,
             sum(eii.BETS_REFUND) as BETS_REFUND,
             sum(eii.HOT_SPOT_FEE_VALUE) as HOT_SPOT_VALUE,
             sum(eii.HOT_SPOT_REFUND) as HOT_SPOT_REFUND,
             sum(eii.TRANSFER_DUE) as TRANSFER_DUE
  from EVENT_INVENTORY ei
  join BREEDERS b on ei.ID_BREEDER = b.ID_BREEDER
  left join EVENT_INVENTORY_ITEM eii on eii.ID_EVENT_INVENTORY = ei.ID_EVENT_INVENTORY
  where (ei.ID_EVENT = :ID_EVENT) and ((:IN_ID_EVENT_INVENTORY is null) or (ei.ID_EVENT_INVENTORY = :IN_ID_EVENT_INVENTORY))
  group by ei.ID_EVENT_INVENTORY, ei.ID_EVENT, ei.ID_BREEDER, ei.LOFT, STATE, ei.SIGN_IN_DATE,
    ei.IS_WAITING, ei.WAITING_DATE, ei.RESERVED_BIRDS, ei.NOTE,
    b.NUMBER, b.FIRST_NAME, b.LAST_NAME
  order by b.LAST_NAME, b.FIRST_NAME
  into :ID_EVENT_INVENTORY,
       :ID_BREEDER,
       :BREEDER_NUMBER,
       :FIRST_NAME,
       :LAST_NAME,
       :LOFT,
       :STATE, 
       :SIGN_IN_DATE,
       :IS_WAITING,
       :WAITING_DATE,
       :RESERVED_BIRDS,
       :NOTE,
       :PERCH_FEE_VALUE,
       :ENTRY_FEE_VALUE,
       :ENTRY_REFUND,
       :BETS_REFUND,
       :HOT_SPOT_VALUE,
       :HOT_SPOT_REFUND,
       :TRANSFER_DUE
  do begin
    select count(eii.ID_EVENT_INVENTORY_ITEM)
      from EVENT_INVENTORY_ITEM eii
      where (eii.ID_EVENT_INVENTORY = :ID_EVENT_INVENTORY)
        and (coalesce(eii.ENTRY_FEE_VALUE, 0) > 0)
        and (coalesce(eii.ENTRY_REFUND, 0) = 0)
      into :ENTRY_BIRDS;

    select count(eii.ID_EVENT_INVENTORY_ITEM)
      from EVENT_INVENTORY_ITEM eii
      where (eii.ID_EVENT_INVENTORY = :ID_EVENT_INVENTORY)
        and (eii.ID_REPLACED_ITEM is null)
      into :IN_LOFT_BIRDS;

    select count(eii.ID_EVENT_INVENTORY_ITEM)
      from EVENT_INVENTORY_ITEM eii
      join BIRDS b on b.ID_BIRD = eii.ID_BIRD
      where (eii.ID_EVENT_INVENTORY = :ID_EVENT_INVENTORY)
        and (b.IS_LOST = 1)
      into :LOST_BIRDS;

    select count(eii.ID_EVENT_INVENTORY_ITEM)
      from EVENT_INVENTORY_ITEM eii
      where (eii.ID_EVENT_INVENTORY = :ID_EVENT_INVENTORY)
        and (eii.ID_REPLACED_ITEM is not null)
      into :REPLACED_BIRDS;

    execute procedure PAYMENT_CALC(:ID_EVENT_INVENTORY)
    returning_values :PERCH_FEE_PAY_VALUE, :ENTRY_FEE_PAY_VALUE, :BETS_PAY_VALUE,
      :HOT_SPOT_PAY_VALUE, :ENTRY_REFUND_PAY_VALUE, :BETS_REFUND_PAY_VALUE,
      :HOT_SPOT_REFUND_PAY_VALUE, :TRANSFER_DUE_PAY_VALUE, :WINNER_PAYOUT_PAY_VALUE,
      :TOTAL_PAYMENT_VALUE;

    execute procedure PARTNERS_GET(:ID_EVENT_INVENTORY)
    returning_values :PARTNER_LIST;

    select ibc.TOTAL_BETS
      from INVENTORY_BETS_CALC(:ID_EVENT_INVENTORY) ibc
      into :BETS_VALUE;
    if (BETS_VALUE = 0) then begin
      BETS_VALUE = null;
    end

    select count(eii.ID_EVENT_INVENTORY_ITEM)
      from EVENT_INVENTORY_ITEM eii
      where eii.ID_EVENT_INVENTORY = :ID_EVENT_INVENTORY and coalesce(eii.HOT_SPOT_FEE_VALUE, 0) > 0
      into :HOT_SPOT_BIRDS;

    BETS_PRIZE = 0;
    if (ID_FINAL_RACE is not null) then begin
      /* setting payout is allowed only on final race */
      for select eii.ID_EVENT_INVENTORY_ITEM
        from EVENT_INVENTORY_ITEM eii
        where eii.ID_EVENT_INVENTORY = :ID_EVENT_INVENTORY
        into :ID_EVENT_INVENTORY_ITEM
      do begin
        select sum(tb.TOTAL) as BETS_PAYOUT_TOTAL
          from TMP_BETS tb
          where tb.ID_EVENT_INVENTORY_ITEM = :ID_EVENT_INVENTORY_ITEM and tb.EXEC_TIME = :EXEC_TIME
          into :BIRD_BETS_PAYOUT_TOTAL;
        BETS_PRIZE = BETS_PRIZE + coalesce(BIRD_BETS_PAYOUT_TOTAL, 0);
      end
    end

    select sum(coalesce(wpp.CAPITAL_VALUE, 0)),
           sum(coalesce(wpp.HOT_SPOT_1_VALUE, 0)),
           sum(coalesce(wpp.HOT_SPOT_2_VALUE, 0)),
           sum(coalesce(wpp.HOT_SPOT_3_VALUE, 0)),
           sum(coalesce(wpp.AVG_SPEED_WINNER_VALUE, 0)),
           sum(wpp.PRIZE_TOTAL) + :BETS_PRIZE
      from WINNER_PRIZE_PAYOUT_GET(:ID_EVENT, :ID_EVENT_INVENTORY) wpp
      into :CAPITAL_PRIZE,
           :HOT_SPOT_1_PRIZE,
           :HOT_SPOT_2_PRIZE,
           :HOT_SPOT_3_PRIZE,
           :AVG_SPEED_WINNER_PRIZE,
           :WINNER_PAYOUT_VALUE;

    BALANCE_VALUE = coalesce(:PERCH_FEE_VALUE, 0)
                  + coalesce(:ENTRY_FEE_VALUE, 0)
                  + coalesce(:HOT_SPOT_VALUE, 0)
                  + coalesce(:BETS_VALUE, 0)
                  + coalesce(:TRANSFER_DUE, 0)
                  - coalesce(:ENTRY_REFUND, 0)
                  - coalesce(:BETS_REFUND, 0)
                  - coalesce(:HOT_SPOT_REFUND, 0)
                  - coalesce(:WINNER_PAYOUT_VALUE, 0)
                  - :TOTAL_PAYMENT_VALUE;
    suspend;
  end

  if (ID_FINAL_RACE is not null) then begin
    /* etting payout is allowed only on final race */
    delete from TMP_BETS tb where tb.EXEC_TIME = :EXEC_TIME;
  end
end ^

ALTER PROCEDURE EVENT_INVENTORY_ITEM_BET_CALC (ID_EVENT_INVENTORY_ITEM INTEGER)
RETURNS (BELGIAN_SHOW_1 NUMERIC(15, 4),
BELGIAN_SHOW_2 NUMERIC(15, 4),
BELGIAN_SHOW_3 NUMERIC(15, 4),
BELGIAN_SHOW_4 NUMERIC(15, 4),
BELGIAN_SHOW_5 NUMERIC(15, 4),
BELGIAN_SHOW_6 NUMERIC(15, 4),
BELGIAN_SHOW_7 NUMERIC(15, 4),
STANDARD_SHOW_1 NUMERIC(15, 4),
STANDARD_SHOW_2 NUMERIC(15, 4),
STANDARD_SHOW_3 NUMERIC(15, 4),
STANDARD_SHOW_4 NUMERIC(15, 4),
STANDARD_SHOW_5 NUMERIC(15, 4),
STANDARD_SHOW_6 NUMERIC(15, 4),
WTA_1 NUMERIC(15, 4),
WTA_2 NUMERIC(15, 4),
WTA_3 NUMERIC(15, 4),
WTA_4 NUMERIC(15, 4),
WTA_5 NUMERIC(15, 4),
TOTAL NUMERIC(15, 4))
AS 
declare variable BELGIAN_SHOW_BET_1 smallint;
  declare variable BELGIAN_SHOW_BET_2 smallint;
  declare variable BELGIAN_SHOW_BET_3 smallint;
  declare variable BELGIAN_SHOW_BET_4 smallint;
  declare variable BELGIAN_SHOW_BET_5 smallint;
  declare variable BELGIAN_SHOW_BET_6 smallint;
  declare variable BELGIAN_SHOW_BET_7 smallint;
  declare variable STANDARD_SHOW_BET_1 smallint;
  declare variable STANDARD_SHOW_BET_2 smallint;
  declare variable STANDARD_SHOW_BET_3 smallint;
  declare variable STANDARD_SHOW_BET_4 smallint;
  declare variable STANDARD_SHOW_BET_5 smallint;
  declare variable STANDARD_SHOW_BET_6 smallint;
  declare variable WTA_BET_1 smallint;
  declare variable WTA_BET_2 smallint;
  declare variable WTA_BET_3 smallint;
  declare variable WTA_BET_4 smallint;
  declare variable WTA_BET_5 smallint;
begin
  select eii.BELGIAN_SHOW_BET_1, eii.BELGIAN_SHOW_BET_2, eii.BELGIAN_SHOW_BET_3,
         eii.BELGIAN_SHOW_BET_4, eii.BELGIAN_SHOW_BET_5, eii.BELGIAN_SHOW_BET_6,
         eii.BELGIAN_SHOW_BET_7, eii.STANDARD_SHOW_BET_1, eii.STANDARD_SHOW_BET_2,
         eii.STANDARD_SHOW_BET_3, eii.STANDARD_SHOW_BET_4, eii.STANDARD_SHOW_BET_5,
         eii.STANDARD_SHOW_BET_6,
         eii.WTA_BET_1, eii.WTA_BET_2, eii.WTA_BET_3, eii.WTA_BET_4, eii.WTA_BET_5,
         bs.BELGIAN_SHOW_1, bs.BELGIAN_SHOW_2, bs.BELGIAN_SHOW_3, bs.BELGIAN_SHOW_4,
         bs.BELGIAN_SHOW_5, bs.BELGIAN_SHOW_6, bs.BELGIAN_SHOW_7, bs.STANDARD_SHOW_1,
         bs.STANDARD_SHOW_2, bs.STANDARD_SHOW_3, bs.STANDARD_SHOW_4, bs.STANDARD_SHOW_5,
         bs.STANDARD_SHOW_6, bs.WTA_1, bs.WTA_2, bs.WTA_3, bs.WTA_4, bs.WTA_5
    from EVENT_INVENTORY_ITEM eii
    join EVENT_INVENTORY ei on ei.ID_EVENT_INVENTORY = eii.ID_EVENT_INVENTORY
    join EVENTS e on e.ID_EVENT = ei.ID_EVENT
    join BETTING_SCHEME bs on bs.ID_BETTING_SCHEME = e.ID_BETTING_SCHEME
    where eii.ID_EVENT_INVENTORY_ITEM = :ID_EVENT_INVENTORY_ITEM
    into :BELGIAN_SHOW_BET_1, :BELGIAN_SHOW_BET_2, :BELGIAN_SHOW_BET_3, :BELGIAN_SHOW_BET_4,
         :BELGIAN_SHOW_BET_5, :BELGIAN_SHOW_BET_6, :BELGIAN_SHOW_BET_7, :STANDARD_SHOW_BET_1,
         :STANDARD_SHOW_BET_2, :STANDARD_SHOW_BET_3, :STANDARD_SHOW_BET_4, :STANDARD_SHOW_BET_5,
         :STANDARD_SHOW_BET_6,
         :WTA_BET_1, :WTA_BET_2, :WTA_BET_3, :WTA_BET_4, :WTA_BET_5,
         :BELGIAN_SHOW_1, :BELGIAN_SHOW_2, :BELGIAN_SHOW_3, :BELGIAN_SHOW_4,
         :BELGIAN_SHOW_5, :BELGIAN_SHOW_6, :BELGIAN_SHOW_7, :STANDARD_SHOW_1,
         :STANDARD_SHOW_2, :STANDARD_SHOW_3, :STANDARD_SHOW_4, :STANDARD_SHOW_5,
         :STANDARD_SHOW_6, :WTA_1, :WTA_2, :WTA_3, :WTA_4, :WTA_5;
  if ((BELGIAN_SHOW_BET_1 is null) or (BELGIAN_SHOW_BET_1 <> 1)) then BELGIAN_SHOW_1 = null;
  if ((BELGIAN_SHOW_BET_2 is null) or (BELGIAN_SHOW_BET_2 <> 1)) then BELGIAN_SHOW_2 = null;
  if ((BELGIAN_SHOW_BET_3 is null) or (BELGIAN_SHOW_BET_3 <> 1)) then BELGIAN_SHOW_3 = null;
  if ((BELGIAN_SHOW_BET_4 is null) or (BELGIAN_SHOW_BET_4 <> 1)) then BELGIAN_SHOW_4 = null;
  if ((BELGIAN_SHOW_BET_5 is null) or (BELGIAN_SHOW_BET_5 <> 1)) then BELGIAN_SHOW_5 = null;
  if ((BELGIAN_SHOW_BET_6 is null) or (BELGIAN_SHOW_BET_6 <> 1)) then BELGIAN_SHOW_6 = null;
  if ((BELGIAN_SHOW_BET_7 is null) or (BELGIAN_SHOW_BET_7 <> 1)) then BELGIAN_SHOW_7 = null;
  if ((STANDARD_SHOW_BET_1 is null) or (STANDARD_SHOW_BET_1 <> 1)) then STANDARD_SHOW_1 = null;
  if ((STANDARD_SHOW_BET_2 is null) or (STANDARD_SHOW_BET_2 <> 1)) then STANDARD_SHOW_2 = null;
  if ((STANDARD_SHOW_BET_3 is null) or (STANDARD_SHOW_BET_3 <> 1)) then STANDARD_SHOW_3 = null;
  if ((STANDARD_SHOW_BET_4 is null) or (STANDARD_SHOW_BET_4 <> 1)) then STANDARD_SHOW_4 = null;
  if ((STANDARD_SHOW_BET_5 is null) or (STANDARD_SHOW_BET_5 <> 1)) then STANDARD_SHOW_5 = null;
  if ((STANDARD_SHOW_BET_6 is null) or (STANDARD_SHOW_BET_6 <> 1)) then STANDARD_SHOW_6 = null;
  if ((WTA_BET_1 is null) or (WTA_BET_1 <> 1)) then WTA_1 = null;
  if ((WTA_BET_2 is null) or (WTA_BET_2 <> 1)) then WTA_2 = null;
  if ((WTA_BET_3 is null) or (WTA_BET_3 <> 1)) then WTA_3 = null;
  if ((WTA_BET_4 is null) or (WTA_BET_4 <> 1)) then WTA_4 = null;
  if ((WTA_BET_5 is null) or (WTA_BET_5 <> 1)) then WTA_5 = null;

  TOTAL = 0;
  if (BELGIAN_SHOW_1 is not null) then TOTAL = TOTAL + BELGIAN_SHOW_1;
  if (BELGIAN_SHOW_2 is not null) then TOTAL = TOTAL + BELGIAN_SHOW_2;
  if (BELGIAN_SHOW_3 is not null) then TOTAL = TOTAL + BELGIAN_SHOW_3;
  if (BELGIAN_SHOW_4 is not null) then TOTAL = TOTAL + BELGIAN_SHOW_4;
  if (BELGIAN_SHOW_5 is not null) then TOTAL = TOTAL + BELGIAN_SHOW_5;
  if (BELGIAN_SHOW_6 is not null) then TOTAL = TOTAL + BELGIAN_SHOW_6;
  if (BELGIAN_SHOW_7 is not null) then TOTAL = TOTAL + BELGIAN_SHOW_7;
  if (STANDARD_SHOW_1 is not null) then TOTAL = TOTAL + STANDARD_SHOW_1;
  if (STANDARD_SHOW_2 is not null) then TOTAL = TOTAL + STANDARD_SHOW_2;
  if (STANDARD_SHOW_3 is not null) then TOTAL = TOTAL + STANDARD_SHOW_3;
  if (STANDARD_SHOW_4 is not null) then TOTAL = TOTAL + STANDARD_SHOW_4;
  if (STANDARD_SHOW_5 is not null) then TOTAL = TOTAL + STANDARD_SHOW_5;
  if (STANDARD_SHOW_6 is not null) then TOTAL = TOTAL + STANDARD_SHOW_6;
  if (WTA_1 is not null) then TOTAL = TOTAL + WTA_1;
  if (WTA_2 is not null) then TOTAL = TOTAL + WTA_2;
  if (WTA_3 is not null) then TOTAL = TOTAL + WTA_3;
  if (WTA_4 is not null) then TOTAL = TOTAL + WTA_4;
  if (WTA_5 is not null) then TOTAL = TOTAL + WTA_5;
  suspend;
end ^

ALTER PROCEDURE EVENT_INVENTORY_ITEM_CHANGE (ID_EVENT_INVENTORY_ITEM INTEGER,
NEW_ID_EVENT_INVENTORY INTEGER)
RETURNS (ERR_CODE INTEGER,
ERR_TEXT VARCHAR(250) CHARACTER SET NONE)
AS 
declare variable ID_EVENT_INVENTORY integer;
declare variable ENTRY_REFUND numeric(15, 4);
declare variable BETS_REFUND numeric(15, 4);
declare variable HOT_SPOT_REFUND numeric(15, 4);
begin
  ID_EVENT_INVENTORY = null;
  select eii.ID_EVENT_INVENTORY, eii.ENTRY_REFUND, eii.BETS_REFUND, eii.HOT_SPOT_REFUND
    from EVENT_INVENTORY_ITEM eii
    where eii.ID_EVENT_INVENTORY_ITEM = :ID_EVENT_INVENTORY_ITEM
    into :ID_EVENT_INVENTORY, :ENTRY_REFUND, :BETS_REFUND, :HOT_SPOT_REFUND;

  if (ID_EVENT_INVENTORY is null) then begin
    ERR_CODE = 1;
    ERR_TEXT = 'Unable to find envent inventory item with id ' || ID_EVENT_INVENTORY_ITEM;
  end

  if ((coalesce(ENTRY_REFUND, 0) > 0)
    or (coalesce(BETS_REFUND, 0) > 0)
    or (coalesce(HOT_SPOT_REFUND, 0) > 0)) then begin
    ERR_CODE = 1;
    ERR_TEXT = 'This bird have some refunds! First remove the refunds!';
  end

  update EVENT_INVENTORY_ITEM eii
    set eii.ENTRY_FEE_VALUE = null,
        eii.ENTRY_FEE_PAID = 0,
        eii.ENTRY_REFUND = null,
        eii.ID_REPLACED_ITEM = null,
        eii.IS_BET_ACTIVE = 1,
        eii.BETS_REFUND = null,
        eii.BELGIAN_SHOW_BET_1 = null,
        eii.BELGIAN_SHOW_BET_2 = null,
        eii.BELGIAN_SHOW_BET_3 = null,
        eii.BELGIAN_SHOW_BET_4 = null,
        eii.BELGIAN_SHOW_BET_5 = null,
        eii.BELGIAN_SHOW_BET_6 = null,
        eii.BELGIAN_SHOW_BET_7 = null,
        eii.STANDARD_SHOW_BET_1 = null,
        eii.STANDARD_SHOW_BET_2 = null,
        eii.STANDARD_SHOW_BET_3 = null,
        eii.STANDARD_SHOW_BET_4 = null,
        eii.STANDARD_SHOW_BET_5 = null,
        eii.STANDARD_SHOW_BET_6 = null,
        eii.WTA_BET_1 = null,
        eii.WTA_BET_2 = null,
        eii.WTA_BET_3 = null,
        eii.WTA_BET_4 = null,
        eii.WTA_BET_5 = null,
        eii.HOT_SPOT_FEE_VALUE = null,
        eii.HOT_SPOT_REFUND = null,
        eii.ID_EVENT_INVENTORY = :NEW_ID_EVENT_INVENTORY
    where eii.ID_EVENT_INVENTORY_ITEM = :ID_EVENT_INVENTORY_ITEM;

  execute procedure PERCH_FEES_RECALC(:ID_EVENT_INVENTORY);
  execute procedure PERCH_FEES_RECALC(:NEW_ID_EVENT_INVENTORY);
end ^

ALTER PROCEDURE EVENT_INVENTORY_ITEM_MODIFY (ID_EVENT_INVENTORY_ITEM INTEGER,
ID_EVENT_INVENTORY INTEGER,
ID_BIRD INTEGER,
BIRD_NO INTEGER,
ARRIVAL_DATE DATE,
DEPARTURE_DATE DATE,
PERCH_FEE_VALUE NUMERIC(15, 4),
ENTRY_FEE_VALUE NUMERIC(15, 4),
ENTRY_FEE_PAID SMALLINT,
ENTRY_REFUND NUMERIC(15, 4),
ID_REPLACED_ITEM INTEGER,
IS_BACKUP SMALLINT,
BETS_REFUND NUMERIC(15, 4),
BELGIAN_SHOW_BET_1 SMALLINT,
BELGIAN_SHOW_BET_2 SMALLINT,
BELGIAN_SHOW_BET_3 SMALLINT,
BELGIAN_SHOW_BET_4 SMALLINT,
BELGIAN_SHOW_BET_5 SMALLINT,
BELGIAN_SHOW_BET_6 SMALLINT,
BELGIAN_SHOW_BET_7 SMALLINT,
STANDARD_SHOW_BET_1 SMALLINT,
STANDARD_SHOW_BET_2 SMALLINT,
STANDARD_SHOW_BET_3 SMALLINT,
STANDARD_SHOW_BET_4 SMALLINT,
STANDARD_SHOW_BET_5 SMALLINT,
STANDARD_SHOW_BET_6 SMALLINT,
WTA_BET_1 SMALLINT,
WTA_BET_2 SMALLINT,
WTA_BET_3 SMALLINT,
WTA_BET_4 SMALLINT,
WTA_BET_5 SMALLINT,
IS_BET_ACTIVE SMALLINT,
HOT_SPOT_FEE_VALUE NUMERIC(15, 4),
HOT_SPOT_REFUND NUMERIC(15, 4),
TRANSFER_DUE NUMERIC(15, 4),
OPERATION VARCHAR(10) CHARACTER SET NONE)
RETURNS (NEW_ID_EVENT_INVENTORY_ITEM INTEGER,
ERR_CODE INTEGER,
ERR_TEXT VARCHAR(250) CHARACTER SET NONE)
AS 
begin
  ERR_CODE = 0;
  ERR_TEXT = '';

  NEW_ID_EVENT_INVENTORY_ITEM = ID_EVENT_INVENTORY_ITEM;
  if (OPERATION = 'add') then begin
    NEW_ID_EVENT_INVENTORY_ITEM = gen_id(GEN_EVENT_INVENTORY_ITEM_ID, 1);
    insert into EVENT_INVENTORY_ITEM(ID_EVENT_INVENTORY_ITEM, ID_EVENT_INVENTORY, ID_BIRD, BIRD_NO,
      ARRIVAL_DATE, DEPARTURE_DATE, PERCH_FEE_VALUE, ENTRY_FEE_VALUE, ENTRY_FEE_PAID, ENTRY_REFUND, BETS_REFUND,
      HOT_SPOT_FEE_VALUE, HOT_SPOT_REFUND, ID_REPLACED_ITEM, IS_BACKUP, BELGIAN_SHOW_BET_1, BELGIAN_SHOW_BET_2,
      BELGIAN_SHOW_BET_3, BELGIAN_SHOW_BET_4, BELGIAN_SHOW_BET_5, BELGIAN_SHOW_BET_6, BELGIAN_SHOW_BET_7,
      STANDARD_SHOW_BET_1, STANDARD_SHOW_BET_2, STANDARD_SHOW_BET_3, STANDARD_SHOW_BET_4, STANDARD_SHOW_BET_5,
      STANDARD_SHOW_BET_6, WTA_BET_1, WTA_BET_2, WTA_BET_3, WTA_BET_4, WTA_BET_5, IS_BET_ACTIVE, TRANSFER_DUE)
    values (:NEW_ID_EVENT_INVENTORY_ITEM, :ID_EVENT_INVENTORY, :ID_BIRD, :BIRD_NO,
      :ARRIVAL_DATE, :DEPARTURE_DATE, :PERCH_FEE_VALUE, :ENTRY_FEE_VALUE, :ENTRY_FEE_PAID, :ENTRY_REFUND, :BETS_REFUND,
      :HOT_SPOT_FEE_VALUE, :HOT_SPOT_REFUND, :ID_REPLACED_ITEM, :IS_BACKUP, :BELGIAN_SHOW_BET_1, :BELGIAN_SHOW_BET_2,
      :BELGIAN_SHOW_BET_3, :BELGIAN_SHOW_BET_4, :BELGIAN_SHOW_BET_5, :BELGIAN_SHOW_BET_6, :BELGIAN_SHOW_BET_7,
      :STANDARD_SHOW_BET_1, :STANDARD_SHOW_BET_2, :STANDARD_SHOW_BET_3, :STANDARD_SHOW_BET_4, :STANDARD_SHOW_BET_5,
      :STANDARD_SHOW_BET_6, :WTA_BET_1, :WTA_BET_2, :WTA_BET_3, :WTA_BET_4, :WTA_BET_5, :IS_BET_ACTIVE, :TRANSFER_DUE);
    -- reset race verified status
    update BIRDS b
      set b.IS_RACE_VERIFIED = 0
      where b.ID_BIRD = :ID_BIRD;
  end else if (OPERATION = 'mod') then begin
    update EVENT_INVENTORY_ITEM
    set ID_EVENT_INVENTORY = :ID_EVENT_INVENTORY,
        ID_BIRD = :ID_BIRD,
        BIRD_NO = :BIRD_NO,
        ARRIVAL_DATE = :ARRIVAL_DATE,
        DEPARTURE_DATE = :DEPARTURE_DATE,
        PERCH_FEE_VALUE = :PERCH_FEE_VALUE,
        ENTRY_FEE_VALUE = :ENTRY_FEE_VALUE,
        ENTRY_FEE_PAID = :ENTRY_FEE_PAID,
        ENTRY_REFUND = :ENTRY_REFUND,
        BETS_REFUND = :BETS_REFUND,
        HOT_SPOT_FEE_VALUE = :HOT_SPOT_FEE_VALUE,
        HOT_SPOT_REFUND = :HOT_SPOT_REFUND,
        ID_REPLACED_ITEM = :ID_REPLACED_ITEM,
        IS_BACKUP = :IS_BACKUP,
        BELGIAN_SHOW_BET_1 = :BELGIAN_SHOW_BET_1,
        BELGIAN_SHOW_BET_2 = :BELGIAN_SHOW_BET_2,
        BELGIAN_SHOW_BET_3 = :BELGIAN_SHOW_BET_3,
        BELGIAN_SHOW_BET_4 = :BELGIAN_SHOW_BET_4,
        BELGIAN_SHOW_BET_5 = :BELGIAN_SHOW_BET_5,
        BELGIAN_SHOW_BET_6 = :BELGIAN_SHOW_BET_6,
        BELGIAN_SHOW_BET_7 = :BELGIAN_SHOW_BET_7,
        STANDARD_SHOW_BET_1 = :STANDARD_SHOW_BET_1,
        STANDARD_SHOW_BET_2 = :STANDARD_SHOW_BET_2,
        STANDARD_SHOW_BET_3 = :STANDARD_SHOW_BET_3,
        STANDARD_SHOW_BET_4 = :STANDARD_SHOW_BET_4,
        STANDARD_SHOW_BET_5 = :STANDARD_SHOW_BET_5,
        STANDARD_SHOW_BET_6 = :STANDARD_SHOW_BET_6,
        WTA_BET_1 = :WTA_BET_1,
        WTA_BET_2 = :WTA_BET_2,
        WTA_BET_3 = :WTA_BET_3,
        WTA_BET_4 = :WTA_BET_4,
        WTA_BET_5 = :WTA_BET_5,
        IS_BET_ACTIVE = :IS_BET_ACTIVE,
        TRANSFER_DUE = :TRANSFER_DUE
    where ID_EVENT_INVENTORY_ITEM = :ID_EVENT_INVENTORY_ITEM;
  end else if (OPERATION = 'del') then begin
    -- when deleting ID_EVENT_INVENTORY is null
    select eii.ID_EVENT_INVENTORY
      from EVENT_INVENTORY_ITEM eii
      where eii.ID_EVENT_INVENTORY_ITEM = :ID_EVENT_INVENTORY_ITEM
      into :ID_EVENT_INVENTORY;

    delete from BIRDS b
      where b.ID_BIRD = (select eii.ID_BIRD
                          from EVENT_INVENTORY_ITEM eii
                          where ID_EVENT_INVENTORY_ITEM = :ID_EVENT_INVENTORY_ITEM);
    delete from EVENT_INVENTORY_ITEM
      where ID_EVENT_INVENTORY_ITEM = :ID_EVENT_INVENTORY_ITEM;

    -- recreate perch fees
    execute procedure PERCH_FEES_RECALC(:ID_EVENT_INVENTORY);
  end
end ^

ALTER PROCEDURE EVENT_INVENTORY_ITEM_REPLACE (OLD_ID_EVENT_INVENTORY_ITEM INTEGER,
NEW_ID_EVENT_INVENTORY_ITEM INTEGER)
AS 
declare variable OLD_ID_BIRD integer;
declare variable BIRD_BETS numeric(15, 4);
declare variable IS_BET_ACTIVE smallint;
begin
  select bcc.IS_BET_ACTIVE, bcc.TOTAL_BETS
    from BIRD_BETS_CALC(:OLD_ID_EVENT_INVENTORY_ITEM) bcc
    into :IS_BET_ACTIVE, :BIRD_BETS;
  if (BIRD_BETS = 0) then begin
    BIRD_BETS = null;
  end

  update EVENT_INVENTORY_ITEM eii
  set eii.BIRD_NO = null,
      eii.PERCH_FEE_VALUE = null,
      eii.ENTRY_FEE_VALUE = null,
      eii.ENTRY_REFUND = null,
      eii.ENTRY_FEE_PAID = 0,
      eii.HOT_SPOT_FEE_VALUE = null,
      eii.HOT_SPOT_REFUND = null,
      eii.BETS_REFUND = :BIRD_BETS,
      eii.IS_BET_ACTIVE = 0,
      eii.ID_REPLACED_ITEM = :NEW_ID_EVENT_INVENTORY_ITEM
  where eii.ID_EVENT_INVENTORY_ITEM = :OLD_ID_EVENT_INVENTORY_ITEM;

  select eii.ID_BIRD
    from EVENT_INVENTORY_ITEM eii
    where eii.ID_EVENT_INVENTORY_ITEM = :OLD_ID_EVENT_INVENTORY_ITEM
    into :OLD_ID_BIRD;

  update BIRDS b
    set b.IS_ACTIVE = 0
    where b.ID_BIRD = :OLD_ID_BIRD;
end ^

ALTER PROCEDURE EVENT_INVENTORY_ITEM_RESTORE (ID_EVENT_INVENTORY_ITEM INTEGER)
RETURNS (ERR_CODE INTEGER,
ERR_TEXT VARCHAR(250) CHARACTER SET NONE)
AS 
declare variable ID_EVENT_INVENTORY integer;
declare variable ID_BIRD integer;
declare variable ID_REPLACED_ITEM integer;
declare variable BIRD_NO integer;
begin
  ERR_CODE = 0;
  ERR_TEXT = '';

  select eii.ID_EVENT_INVENTORY,
         eii.ID_BIRD,
         eii.ID_REPLACED_ITEM
    from EVENT_INVENTORY_ITEM eii
    where eii.ID_EVENT_INVENTORY_ITEM = :ID_EVENT_INVENTORY_ITEM
    into :ID_EVENT_INVENTORY,
         :ID_BIRD,
         :ID_REPLACED_ITEM;

  if (ID_REPLACED_ITEM is null) then begin
    ERR_CODE = 1;
    ERR_TEXT = 'The selected bird is not replaced!';
    exit;
  end

  select max(eii.BIRD_NO)
    from EVENT_INVENTORY_ITEM eii
    where eii.ID_EVENT_INVENTORY = :ID_EVENT_INVENTORY
    into :BIRD_NO;

  update EVENT_INVENTORY_ITEM
  set BIRD_NO = :BIRD_NO + 1,
      ID_REPLACED_ITEM = null
  where ID_EVENT_INVENTORY_ITEM = :ID_EVENT_INVENTORY_ITEM;

  execute procedure PERCH_FEES_RECALC(:ID_EVENT_INVENTORY);

  update BIRDS b
    set b.IS_ACTIVE = 1
    where b.ID_BIRD = :ID_BIRD;
end ^

ALTER PROCEDURE EVENT_INVENTORY_MODIFY (ID_EVENT_INVENTORY INTEGER,
ID_EVENT INTEGER,
ID_BREEDER INTEGER,
SIGN_IN_DATE DATE,
WAITING_DATE DATE,
IS_WAITING SMALLINT,
RESERVED_BIRDS INTEGER,
LOFT VARCHAR(30) CHARACTER SET NONE,
NOTE VARCHAR(250) CHARACTER SET NONE,
OPERATION VARCHAR(3) CHARACTER SET NONE)
RETURNS (NEW_ID_EVENT_INVENTORY INTEGER,
ERR_CODE INTEGER,
ERR_TEXT VARCHAR(255) CHARACTER SET NONE)
AS 
declare variable ID_BIRD integer;
begin
  ERR_CODE = 0;
  ERR_TEXT = '';
  NEW_ID_EVENT_INVENTORY = ID_EVENT_INVENTORY;

  if (IS_WAITING is null) then begin
    IS_WAITING = 1;
    WAITING_DATE = 'now';
  end
  if (RESERVED_BIRDS is null) then begin
    RESERVED_BIRDS = 0;
  end
  if (LOFT is null) then begin
    select b.LAST_NAME ||','|| b.FIRST_NAME ||'('|| b.ID_BREEDER ||')'
      from BREEDERS b
      where b.ID_BREEDER = :ID_BREEDER
      into :LOFT;
  end

  if ((OPERATION = 'add') or (OPERATION = 'mod')) then begin
    if (exists (select ei.ID_EVENT_INVENTORY
                  from EVENT_INVENTORY ei
                  where ei.ID_EVENT = :ID_EVENT
                    and ei.ID_BREEDER = :ID_BREEDER
                    and ei.ID_EVENT_INVENTORY <> :ID_EVENT_INVENTORY)) then begin
      ERR_CODE = 1;
      ERR_TEXT = 'This breeder alredy exist in the event inventory!';
      exit;
    end
  end

  if (OPERATION = 'add') then begin
    NEW_ID_EVENT_INVENTORY = gen_id(GEN_EVENT_INVENTORY_ID, 1);
    insert into EVENT_INVENTORY
      (ID_EVENT_INVENTORY, ID_EVENT, ID_BREEDER, SIGN_IN_DATE,
      WAITING_DATE, IS_WAITING, RESERVED_BIRDS, LOFT, NOTE)
    values
      (:NEW_ID_EVENT_INVENTORY, :ID_EVENT, :ID_BREEDER, :SIGN_IN_DATE,
      :WAITING_DATE, :IS_WAITING, :RESERVED_BIRDS, :LOFT, :NOTE);
  end else if (OPERATION = 'mod') then begin
    update EVENT_INVENTORY
    set ID_EVENT = :ID_EVENT,
        ID_BREEDER = :ID_BREEDER,
        SIGN_IN_DATE = :SIGN_IN_DATE,
        WAITING_DATE = :WAITING_DATE,
        IS_WAITING = :IS_WAITING,
        RESERVED_BIRDS = :RESERVED_BIRDS,
        LOFT = :LOFT,
        NOTE = :NOTE
    where ID_EVENT_INVENTORY = :ID_EVENT_INVENTORY;
  end else if (OPERATION = 'del') then begin
    for select eii.ID_BIRD
      from EVENT_INVENTORY_ITEM eii
      where eii.ID_EVENT_INVENTORY = :ID_EVENT_INVENTORY
      into :ID_BIRD
    do begin
      delete from BIRDS b
        where b.ID_BIRD = :ID_BIRD;
    end

    delete from EVENT_INVENTORY
      where ID_EVENT_INVENTORY = :ID_EVENT_INVENTORY;
  end
end ^

ALTER PROCEDURE EVENT_RACE_NUMBER_SET (ID_NUMBER_GROUP INTEGER,
ID_EVENT INTEGER,
NUMBER_RANGE_FROM INTEGER,
NUMBER_RANGE_TO INTEGER)
AS 
begin
  if (exists (select ern.ID_NUMBER_GROUP
                from EVENT_RACE_NUMBER ern
                where ern.ID_NUMBER_GROUP = :ID_NUMBER_GROUP and ern.ID_EVENT = :ID_EVENT)) then begin
    update EVENT_RACE_NUMBER
    set NUMBER_RANGE_FROM = :NUMBER_RANGE_FROM,
        NUMBER_RANGE_TO = :NUMBER_RANGE_TO
    where ID_NUMBER_GROUP = :ID_NUMBER_GROUP and ID_EVENT = :ID_EVENT;
  end else begin
    insert into EVENT_RACE_NUMBER(ID_NUMBER_GROUP, ID_EVENT, NUMBER_RANGE_FROM, NUMBER_RANGE_TO)
    values (:ID_NUMBER_GROUP, :ID_EVENT, :NUMBER_RANGE_FROM, :NUMBER_RANGE_TO);
  end
end ^

ALTER PROCEDURE FEE_SCHEME_MODIFY (ID_FEE_SCHEME INTEGER,
FEE_SCHEME_NAME VARCHAR(20) CHARACTER SET NONE,
ENTRY_FEE NUMERIC(15, 4),
IS_REFUNDABLE SMALLINT,
MIN_ENTRY_FEES SMALLINT,
MAX_BIRD_COUNT SMALLINT,
MAX_BACKUP_BIRD_COUNT SMALLINT,
IS_FLOATING_BACKUP SMALLINT,
FEES_CUT_PERCENT NUMERIC(15, 4),
HOT_SPOT1_FEE NUMERIC(15, 4),
HOT_SPOT2_FEE NUMERIC(15, 4),
HOT_SPOT3_FEE NUMERIC(15, 4),
HOT_SPOT_FINAL_FEE NUMERIC(15, 4),
OPERATION VARCHAR(9) CHARACTER SET NONE)
RETURNS (NEW_ID_FEE_SCHEME INTEGER,
ERR_CODE INTEGER,
ERR_TEXT VARCHAR(250) CHARACTER SET NONE)
AS 
begin
  ERR_CODE = 0;
  ERR_TEXT = '';
  NEW_ID_FEE_SCHEME = ID_FEE_SCHEME;
  /*
  if ((OPERATION = 'mod') or (OPERATION = 'mod')) then begin
    if (exists (select e.ID_EVENT
                  from EVENTS e
                  join EVENT_INVENTORY ei on ei.ID_EVENT = e.ID_EVENT
                  join EVENT_INVENTORY_ITEM eii on eii.ID_EVENT_INVENTORY = ei.ID_EVENT_INVENTORY
                  where e.ID_FEE_SCHEME = :ID_FEE_SCHEME)) then begin
      ERR_CODE = 1;
      ERR_TEXT = 'This fee scheme is already used in event inventory! You can''t make any changes!';
      exit;
    end
  end
  */

  if (OPERATION = 'add') then begin
    NEW_ID_FEE_SCHEME = gen_id(GEN_FEE_SCHEME_ID, 1);
    insert into FEE_SCHEME
      (ID_FEE_SCHEME, FEE_SCHEME_NAME, ENTRY_FEE, IS_REFUNDABLE, MIN_ENTRY_FEES, MAX_BIRD_COUNT, MAX_BACKUP_BIRD_COUNT,
      IS_FLOATING_BACKUP, FEES_CUT_PERCENT, HOT_SPOT1_FEE, HOT_SPOT2_FEE, HOT_SPOT3_FEE, HOT_SPOT_FINAL_FEE)
    values
      (:NEW_ID_FEE_SCHEME, :FEE_SCHEME_NAME, :ENTRY_FEE, :IS_REFUNDABLE, :MIN_ENTRY_FEES, :MAX_BIRD_COUNT, :MAX_BACKUP_BIRD_COUNT,
      :IS_FLOATING_BACKUP, :FEES_CUT_PERCENT, :HOT_SPOT1_FEE, :HOT_SPOT2_FEE, :HOT_SPOT3_FEE, :HOT_SPOT_FINAL_FEE);
  end else if (OPERATION = 'mod') then begin
    update FEE_SCHEME
    set FEE_SCHEME_NAME = :FEE_SCHEME_NAME,
        ENTRY_FEE = :ENTRY_FEE,
        IS_REFUNDABLE = :IS_REFUNDABLE,
        MIN_ENTRY_FEES = :MIN_ENTRY_FEES,
        MAX_BIRD_COUNT = :MAX_BIRD_COUNT,
        MAX_BACKUP_BIRD_COUNT = :MAX_BACKUP_BIRD_COUNT,
        IS_FLOATING_BACKUP = :IS_FLOATING_BACKUP,
        FEES_CUT_PERCENT = :FEES_CUT_PERCENT,
        HOT_SPOT1_FEE = :HOT_SPOT1_FEE,
        HOT_SPOT2_FEE = :HOT_SPOT2_FEE,
        HOT_SPOT3_FEE = :HOT_SPOT3_FEE,
        HOT_SPOT_FINAL_FEE = :HOT_SPOT_FINAL_FEE
    where (ID_FEE_SCHEME = :ID_FEE_SCHEME);
  end else if (OPERATION = 'del') then begin
    delete from FEE_SCHEME
    where (ID_FEE_SCHEME = :ID_FEE_SCHEME);
  end else if (OPERATION = 'del_items') then begin
    delete from PERCH_FEE_ITEM pi
    where pi.ID_FEE_SCHEME = :ID_FEE_SCHEME;
  end
  suspend;
end ^

ALTER PROCEDURE FORMAT_BAND_NUMBER (ASSC_PART VARCHAR(10) CHARACTER SET NONE,
YEAR_PART VARCHAR(10) CHARACTER SET NONE,
LETTER_PART VARCHAR(10) CHARACTER SET NONE,
NUMBER_PART VARCHAR(10) CHARACTER SET NONE)
RETURNS (BAND_NUMBER VARCHAR(50) CHARACTER SET NONE)
AS 
declare variable BAND_FORMAT varchar(200);
begin
  select sc.CFG_VALUE
    from SYSTEM_CFG sc
    where sc.CFG_KEY = 'db.band_format'
    into :BAND_FORMAT;
  if (coalesce(:BAND_FORMAT, '') = '') then begin
    BAND_NUMBER = :ASSC_PART || :YEAR_PART || :LETTER_PART || :NUMBER_PART;
  end else begin
    BAND_NUMBER = F_REPLSTR(:BAND_FORMAT, '%A', :ASSC_PART);
    BAND_NUMBER = F_REPLSTR(:BAND_NUMBER, '%Y', :YEAR_PART);
    BAND_NUMBER = F_REPLSTR(:BAND_NUMBER, '%L', :LETTER_PART);
    BAND_NUMBER = F_REPLSTR(:BAND_NUMBER, '%N', :NUMBER_PART);
  end
  suspend;
end ^

ALTER PROCEDURE GET_BIRD_STATUS (ID_BIRD INTEGER)
RETURNS (BAND VARCHAR(20) CHARACTER SET NONE,
RF_ID VARCHAR(20) CHARACTER SET NONE,
IS_LOST SMALLINT,
ID_LOST_RACE INTEGER,
IS_ACTIVE SMALLINT,
IS_RACE_VERIFIED SMALLINT)
AS 
begin
  select b.BAND, b.RF_ID, b.IS_LOST, B.LOST_ID_RACE, b.IS_ACTIVE, b.IS_RACE_VERIFIED
    FROM BIRDS b
    where b.ID_BIRD = :ID_BIRD
    into :BAND, :RF_ID, :IS_LOST, :ID_LOST_RACE, :IS_ACTIVE, :IS_RACE_VERIFIED;
  suspend;
end ^

ALTER PROCEDURE GET_PRIZE_VALUE (ID_PRIZE_SCHEME INTEGER,
ID_EVENT INTEGER,
ID_RACE_TYPE INTEGER,
FROM_POSITION INTEGER,
TO_POSITION INTEGER)
RETURNS (PRIZE_VALUE NUMERIC(15, 4))
AS 
declare variable TMP_FROM_POSITION INTEGER;
declare variable TMP_TO_POSITION INTEGER;
declare variable TMP_PRIZE_VALUE NUMERIC(15,4);
begin
  PRIZE_VALUE = null;
  for select psi.FROM_POSITION, psi.TO_POSITION, pv.PRIZE_VALUE
    from PRIZE_SCHEME_ITEM psi
    join PRIZE_VALUE pv on pv.ID_PRIZE_SCHEME_ITEM = psi.ID_PRIZE_SCHEME_ITEM and pv.ID_EVENT = :ID_EVENT  and pv.ID_RACE_TYPE = :ID_RACE_TYPE
    where psi.ID_PRIZE_SCHEME = :ID_PRIZE_SCHEME
      and psi.TO_POSITION >= :FROM_POSITION
      and psi.FROM_POSITION <= :TO_POSITION
    into :TMP_FROM_POSITION, :TMP_TO_POSITION, :TMP_PRIZE_VALUE
  do begin
    if ((TMP_FROM_POSITION < FROM_POSITION) and (TMP_TO_POSITION > TO_POSITION)) then begin
      PRIZE_VALUE = coalesce(PRIZE_VALUE, 0) + ((TO_POSITION - FROM_POSITION + 1) * TMP_PRIZE_VALUE);
    end else if (TMP_FROM_POSITION < FROM_POSITION) then begin
      PRIZE_VALUE = coalesce(PRIZE_VALUE, 0) + ((TMP_TO_POSITION - FROM_POSITION + 1) * TMP_PRIZE_VALUE);
    end else if (TMP_TO_POSITION > TO_POSITION) then begin
      PRIZE_VALUE = coalesce(PRIZE_VALUE, 0) + ((TO_POSITION - TMP_FROM_POSITION + 1) * TMP_PRIZE_VALUE);
    end else begin
      PRIZE_VALUE = coalesce(PRIZE_VALUE, 0) + ((TMP_TO_POSITION - TMP_FROM_POSITION + 1) * TMP_PRIZE_VALUE);
    end
  end
  suspend;
end ^

ALTER PROCEDURE GET_REPORTS RETURNS (IDENT VARCHAR(150) CHARACTER SET NONE,
CLASS_ VARCHAR(150) CHARACTER SET NONE,
DEFAULT_CAPTION VARCHAR(200) CHARACTER SET NONE,
FASTREPORT_CONTENT BLOB,
ID_REPORT INTEGER)
AS 
begin
  for
    select R.IDENT,
           R.CLASS_,
           R.DEFAULT_CAPTION,
           R.FASTREPORT_CONTENT,
           R.ID_REPORT
    from REPORTS R
    where IS_DELETED = 0
    INTO :IDENT,
         :CLASS_,
         :DEFAULT_CAPTION,
         :FASTREPORT_CONTENT,
         :ID_REPORT
  do suspend;
end ^

ALTER PROCEDURE GET_REPORT_CLASSES RETURNS (IDENT VARCHAR(150) CHARACTER SET NONE,
CAPTION VARCHAR(200) CHARACTER SET NONE,
COPIES INTEGER,
TYPE VARCHAR(50) CHARACTER SET NONE)
AS 
BEGIN
  FOR
    select IDENT,
           CAPTION,
           COPIES,
           "TYPE"
    from REPORT_CLASSES
    INTO :IDENT,
         :CAPTION,
         :COPIES,
         :"TYPE"
  DO
  BEGIN
    SUSPEND;
  END
END ^

ALTER PROCEDURE HOT_SPOT_CURRENT_FEE_GET (ID_EVENT INTEGER)
RETURNS (HOT_SPOT_FEE NUMERIC(15, 4))
AS 
declare variable HOT_SPOT1_FEE numeric(15, 4);
declare variable HOT_SPOT2_FEE numeric(15, 4);
declare variable HOT_SPOT3_FEE numeric(15, 4);
declare variable HOT_SPOT_FINAL_FEE numeric(15, 4);
declare variable HOT_SPOT_RACE_COUNT integer;
begin
  HOT_SPOT_FEE = null;
  select fs.HOT_SPOT1_FEE, fs.HOT_SPOT2_FEE, fs.HOT_SPOT3_FEE, fs.HOT_SPOT_FINAL_FEE
    from EVENTS e
    join FEE_SCHEME fs on fs.ID_FEE_SCHEME = e.ID_FEE_SCHEME
    where e.ID_EVENT = :ID_EVENT
    into :HOT_SPOT1_FEE, :HOT_SPOT2_FEE, :HOT_SPOT3_FEE, :HOT_SPOT_FINAL_FEE;


  if (not exists(select r.ID_RACE  from RACE r  where r.ID_EVENT = :ID_EVENT and r.ID_RACE_TYPE = 6)) then begin
    -- Hot spot fee before Hot spot 1
    HOT_SPOT_FEE = HOT_SPOT1_FEE;
  end else if (not exists(select r.ID_RACE  from RACE r  where r.ID_EVENT = :ID_EVENT and r.ID_RACE_TYPE = 7)) then begin
    -- Hot spot fee between Hot spot 1 and Hot spot 2
    HOT_SPOT_FEE = HOT_SPOT2_FEE;
  end else if (not exists(select r.ID_RACE  from RACE r  where r.ID_EVENT = :ID_EVENT and r.ID_RACE_TYPE = 8)) then begin
    -- Hot spot fee between Hot spot 2 and Hot spot 3
    HOT_SPOT_FEE = HOT_SPOT3_FEE;
  end else if (not exists(select r.ID_RACE  from RACE r  where r.ID_EVENT = :ID_EVENT and r.ID_RACE_TYPE = 5)) then begin
    -- Hot spot fee between Hot spot 3 and final race
    HOT_SPOT_FEE = HOT_SPOT_FINAL_FEE;
  end

  suspend;
end ^

ALTER PROCEDURE INVALIDATE_NOMEN (NOMEN VARCHAR(50) CHARACTER SET NONE)
AS 
begin
  post_event 'invalidate_' || lower(:nomen);
end ^

ALTER PROCEDURE INVENTORY_BETS_CALC (ID_EVENT_INVENTORY INTEGER)
RETURNS (BELGIAN_SHOW_1 NUMERIC(15, 4),
BELGIAN_SHOW_2 NUMERIC(15, 4),
BELGIAN_SHOW_3 NUMERIC(15, 4),
BELGIAN_SHOW_4 NUMERIC(15, 4),
BELGIAN_SHOW_5 NUMERIC(15, 4),
BELGIAN_SHOW_6 NUMERIC(15, 4),
BELGIAN_SHOW_7 NUMERIC(15, 4),
STANDARD_SHOW_1 NUMERIC(15, 4),
STANDARD_SHOW_2 NUMERIC(15, 4),
STANDARD_SHOW_3 NUMERIC(15, 4),
STANDARD_SHOW_4 NUMERIC(15, 4),
STANDARD_SHOW_5 NUMERIC(15, 4),
STANDARD_SHOW_6 NUMERIC(15, 4),
WTA_1 NUMERIC(15, 4),
WTA_2 NUMERIC(15, 4),
WTA_3 NUMERIC(15, 4),
WTA_4 NUMERIC(15, 4),
WTA_5 NUMERIC(15, 4),
TOTAL_BETS NUMERIC(15, 4))
AS 
begin
  select sum(eii.BELGIAN_SHOW_BET_1 * bs.BELGIAN_SHOW_1),
         sum(eii.BELGIAN_SHOW_BET_2 * bs.BELGIAN_SHOW_2),
         sum(eii.BELGIAN_SHOW_BET_3 * bs.BELGIAN_SHOW_3),
         sum(eii.BELGIAN_SHOW_BET_4 * bs.BELGIAN_SHOW_4),
         sum(eii.BELGIAN_SHOW_BET_5 * bs.BELGIAN_SHOW_5),
         sum(eii.BELGIAN_SHOW_BET_6 * bs.BELGIAN_SHOW_6),
         sum(eii.BELGIAN_SHOW_BET_7 * bs.BELGIAN_SHOW_7),
         sum(eii.STANDARD_SHOW_BET_1 * bs.STANDARD_SHOW_1),
         sum(eii.STANDARD_SHOW_BET_2 * bs.STANDARD_SHOW_2),
         sum(eii.STANDARD_SHOW_BET_3 * bs.STANDARD_SHOW_3),
         sum(eii.STANDARD_SHOW_BET_4 * bs.STANDARD_SHOW_4),
         sum(eii.STANDARD_SHOW_BET_5 * bs.STANDARD_SHOW_5),
         sum(eii.STANDARD_SHOW_BET_6 * bs.STANDARD_SHOW_6),
         sum(eii.WTA_BET_1 * bs.WTA_1),
         sum(eii.WTA_BET_2 * bs.WTA_2),
         sum(eii.WTA_BET_3 * bs.WTA_3),
         sum(eii.WTA_BET_4 * bs.WTA_4),
         sum(eii.WTA_BET_5 * bs.WTA_5)
    from EVENT_INVENTORY_ITEM eii
    join EVENT_INVENTORY ei on ei.ID_EVENT_INVENTORY = eii.ID_EVENT_INVENTORY
    join EVENTS e on e.ID_EVENT = ei.ID_EVENT
    join BETTING_SCHEME bs on bs.ID_BETTING_SCHEME = e.ID_BETTING_SCHEME
    where eii.ID_EVENT_INVENTORY = :ID_EVENT_INVENTORY
    into :BELGIAN_SHOW_1, :BELGIAN_SHOW_2, :BELGIAN_SHOW_3, :BELGIAN_SHOW_4,
         :BELGIAN_SHOW_5, :BELGIAN_SHOW_6, :BELGIAN_SHOW_7, :STANDARD_SHOW_1,
         :STANDARD_SHOW_2, :STANDARD_SHOW_3, :STANDARD_SHOW_4, :STANDARD_SHOW_5,
         :STANDARD_SHOW_6, :WTA_1, :WTA_2, :WTA_3, :WTA_4, :WTA_5;

  TOTAL_BETS = coalesce(BELGIAN_SHOW_1, 0)
             + coalesce(BELGIAN_SHOW_2, 0)
             + coalesce(BELGIAN_SHOW_3, 0)
             + coalesce(BELGIAN_SHOW_4, 0)
             + coalesce(BELGIAN_SHOW_5, 0)
             + coalesce(BELGIAN_SHOW_6, 0)
             + coalesce(BELGIAN_SHOW_7, 0)
             + coalesce(STANDARD_SHOW_1, 0)
             + coalesce(STANDARD_SHOW_2, 0)
             + coalesce(STANDARD_SHOW_3, 0)
             + coalesce(STANDARD_SHOW_4, 0)
             + coalesce(STANDARD_SHOW_5, 0)
             + coalesce(STANDARD_SHOW_6, 0)
             + coalesce(WTA_1, 0)
             + coalesce(WTA_2, 0)
             + coalesce(WTA_3, 0)
             + coalesce(WTA_4, 0);
  suspend;
end ^

ALTER PROCEDURE LOG_EVENT (CATEGORY VARCHAR(255) CHARACTER SET NONE,
CONTENT VARCHAR(500) CHARACTER SET NONE)
RETURNS (ERR_CODE INTEGER,
ERR_TEXT VARCHAR(255) CHARACTER SET NONE,
NEW_ID_LOG INTEGER)
AS 

DECLARE VARIABLE ID_USER INTEGER;
declare variable machine varchar(255);
begin
  err_code = 0;
  err_text = '';

  select U.ID_USER
  from SYSTEM_SESSION SS
       join USERS U on U.LOGIN_NAME = SS.SESSION_VALUE
  where SS.SESSION_KEY = 'current.user.loginname'
  into :id_user;

  select SS.session_value
  from SYSTEM_SESSION SS
  where SS.session_key = 'current.machine'
  into :machine;

  if (id_user is null) then begin
    if (user <> 'SYSDBA') then begin
      err_code = -2;
      exit;
    end
  end

  new_id_log = gen_id(GEN_LOG_ID,1);

  insert into LOG
    (ID_LOG, LOG_LEVEL, CATEGORY, CONTENT, DT_LOGGED, ID_USER, MACHINE)
  values
    (:new_id_log, 'EVENT', :category, :content, current_timestamp, :id_user, :machine);
end ^

