END ^

ALTER PROCEDURE LOG_EVENT_USER_LOGGEDOUT (ID_LOG INTEGER,
ID_USER INTEGER)
RETURNS (ERR_CODE INTEGER,
ERR_TEXT VARCHAR(255) CHARACTER SET NONE)
AS 

 declare variable id_log_started integer;
begin
  err_code = 0;
  err_text = '';
  
  select max(L.ID_LOG)
  from LOG_USER_LOGGEDIN L
  where L.ID_USER = :id_user
  into :id_log_started;

  insert into LOG_USER_LOGGEDOUT
    (ID_LOG, ID_LOGGED_IN)
  values (:id_log, :id_log_started);
END ^

ALTER PROCEDURE LOST_HISTORY_MODIFY (ID_BIRD INTEGER,
LOST_DATE DATE,
IS_LOST SMALLINT,
ID_RACE INTEGER,
OPERATION VARCHAR(5) CHARACTER SET NONE)
AS 
declare variable ID_LOST_HISTORY integer;
begin
