end ^

ALTER PROCEDURE NUMBER_GROUP_DESC_GET (ID_NUMBER_GROUP INTEGER)
RETURNS (NUMBER_GROUP_DESC VARCHAR(250) CHARACTER SET NONE)
AS 
declare variable TYPE_NAME varchar(50);
begin
  NUMBER_GROUP_DESC = '';
  for select rt.TYPE_NAME
    from RACE_TYPE rt
    where rt.ID_NUMBER_GROUP = :ID_NUMBER_GROUP
    into :TYPE_NAME
  do begin
    if (NUMBER_GROUP_DESC <> '') then begin
      NUMBER_GROUP_DESC = NUMBER_GROUP_DESC || ' / ';
    end
    NUMBER_GROUP_DESC = NUMBER_GROUP_DESC || TYPE_NAME;
  end
  suspend;
end ^

ALTER PROCEDURE ORGANIZER_DATA_MODIFY (NAME VARCHAR(50) CHARACTER SET NONE,
ADDRESS VARCHAR(100) CHARACTER SET NONE,
CITY VARCHAR(20) CHARACTER SET NONE,
STATE VARCHAR(2) CHARACTER SET NONE,
ZIP VARCHAR(10) CHARACTER SET NONE,
EMAIL VARCHAR(100) CHARACTER SET NONE,
WEB VARCHAR(100) CHARACTER SET NONE,
PHONE VARCHAR(20) CHARACTER SET NONE,
CELL VARCHAR(20) CHARACTER SET NONE,
FAX VARCHAR(20) CHARACTER SET NONE,
NOTE VARCHAR(250) CHARACTER SET NONE)
AS 
begin
  if (exists(select od.NAME from ORGANIZER_DATA od)) then begin
    update ORGANIZER_DATA
    set NAME = :NAME,
        ADDRESS = :ADDRESS,
        CITY = :CITY,
        STATE = :STATE,
        ZIP = :ZIP,
        EMAIL = :EMAIL,
        WEB = :WEB,
        PHONE = :PHONE,
        CELL = :CELL,
        FAX = :FAX,
        NOTE = :NOTE;
  end else begin
    insert into ORGANIZER_DATA(NAME, ADDRESS, CITY, STATE, ZIP, EMAIL, WEB, PHONE, CELL, FAX, NOTE)
    values (:NAME, :ADDRESS, :CITY, :STATE, :ZIP, :EMAIL, :WEB, :PHONE, :CELL, :FAX, :NOTE);
  end
end ^

ALTER PROCEDURE PARTNERS_GET (ID_EVENT_INVENTORY INTEGER)
RETURNS (PARTNER_LIST VARCHAR(1000) CHARACTER SET NONE)
AS 
declare variable PARTNER_NAME varchar(50);
begin
  PARTNER_LIST = '';
  for select b.LAST_NAME || ', ' || b.FIRST_NAME
    from PARTNERS pr
    join BREEDERS b on b.ID_BREEDER = pr.ID_BREEDER
    where pr.ID_EVENT_INVENTORY = :ID_EVENT_INVENTORY
    into :PARTNER_NAME
  do begin
    if (char_length(PARTNER_LIST) > 0) then begin
      PARTNER_LIST = PARTNER_LIST || '/';
    end
    PARTNER_LIST = PARTNER_LIST || PARTNER_NAME;
  end
  suspend;
end ^

ALTER PROCEDURE PARTNER_MODIFY (ID_EVENT_INVENTORY INTEGER,
ID_BREEDER INTEGER,
OPERATION VARCHAR(3) CHARACTER SET NONE)
AS 
begin
  if (OPERATION = 'set') then begin
    if (not exists (select p.ID_EVENT_INVENTORY
                  from PARTNERS p
                  where p.ID_EVENT_INVENTORY = :ID_EVENT_INVENTORY
                    and p.ID_BREEDER = :ID_BREEDER)) then begin
      insert into PARTNERS(ID_EVENT_INVENTORY, ID_BREEDER)
      values (:ID_EVENT_INVENTORY, :ID_BREEDER);
    end
  end else if (OPERATION = 'del') then begin
    delete from PARTNERS
    where ID_EVENT_INVENTORY = :ID_EVENT_INVENTORY
      and ID_BREEDER = :ID_BREEDER;
  end
end ^

ALTER PROCEDURE PAYMENT_CALC (ID_EVENT_INVENTORY INTEGER)
RETURNS (PERCH_FEE_PAYMENT NUMERIC(15, 4),
ENTRY_FEE_PAYMENT NUMERIC(15, 4),
BETS_PAYMENT NUMERIC(15, 4),
HOT_SPOT_PAYMENT NUMERIC(15, 4),
ENTRY_REFUND_PAYMENT NUMERIC(15, 4),
BETS_REFUND_PAYMENT NUMERIC(15, 4),
HOT_SPOT_REFUND_PAYMENT NUMERIC(15, 4),
TRANSFER_DUE_PAYMENT NUMERIC(15, 4),
WINNER_PAYOUT_PAYMENT NUMERIC(15, 4),
PAYMENT_TOTAL NUMERIC(15, 4))
AS 
declare variable PAYMENT_TYPE smallint;
declare variable PAYMENT_VALUE numeric(15, 4);
begin
  PERCH_FEE_PAYMENT = null;
  ENTRY_FEE_PAYMENT = null;
  BETS_PAYMENT = null;
  HOT_SPOT_PAYMENT = null;
  ENTRY_REFUND_PAYMENT = null;
  BETS_REFUND_PAYMENT = null;
  TRANSFER_DUE_PAYMENT = null;
  WINNER_PAYOUT_PAYMENT = null;
  PAYMENT_TOTAL = 0;
  for select p.PAYMENT_TYPE, sum(p.PAYMENT_VALUE)
    from PAYMENTS p
    where p.ID_EVENT_INVENTORY = :ID_EVENT_INVENTORY
    group by p.PAYMENT_TYPE
    into :PAYMENT_TYPE, :PAYMENT_VALUE
  do begin
    if (PAYMENT_TYPE = 0) then PERCH_FEE_PAYMENT = PAYMENT_VALUE;
    if (PAYMENT_TYPE = 1) then ENTRY_FEE_PAYMENT = PAYMENT_VALUE;
    if (PAYMENT_TYPE = 2) then BETS_PAYMENT = PAYMENT_VALUE;
    if (PAYMENT_TYPE = 3) then HOT_SPOT_PAYMENT = PAYMENT_VALUE;
    if (PAYMENT_TYPE = 4) then ENTRY_REFUND_PAYMENT = -1 * PAYMENT_VALUE;
    if (PAYMENT_TYPE = 5) then BETS_REFUND_PAYMENT = -1 * PAYMENT_VALUE;
    if (PAYMENT_TYPE = 6) then HOT_SPOT_REFUND_PAYMENT = -1 * PAYMENT_VALUE;
    if (PAYMENT_TYPE = 7) then TRANSFER_DUE_PAYMENT = PAYMENT_VALUE;
    if (PAYMENT_TYPE = 8) then WINNER_PAYOUT_PAYMENT = -1 * PAYMENT_VALUE;
    PAYMENT_TOTAL = coalesce(PERCH_FEE_PAYMENT, 0)
                  + coalesce(ENTRY_FEE_PAYMENT, 0)
                  + coalesce(BETS_PAYMENT, 0)
                  + coalesce(HOT_SPOT_PAYMENT, 0)
                  + coalesce(TRANSFER_DUE_PAYMENT, 0)
                  - coalesce(ENTRY_REFUND_PAYMENT, 0)
                  - coalesce(BETS_REFUND_PAYMENT, 0)
                  - coalesce(HOT_SPOT_REFUND_PAYMENT, 0)
                  - coalesce(WINNER_PAYOUT_PAYMENT, 0);

  end
  suspend;
end ^

ALTER PROCEDURE PAYMENT_MODIFY (ID_PAYMENT INTEGER,
ID_EVENT_INVENTORY INTEGER,
PAYMENT_TYPE SMALLINT,
PAYMENT_DATE DATE,
PAYMENT_VALUE NUMERIC(15, 4),
PAYMENT_METHOD SMALLINT,
PAYMENT_DESC VARCHAR(50) CHARACTER SET NONE,
ID_PICTURE INTEGER,
OPERATION VARCHAR(3) CHARACTER SET NONE)
RETURNS (ERR_CODE INTEGER,
ERR_TEXT VARCHAR(100) CHARACTER SET NONE,
NEW_ID_PAYMENT INTEGER)
AS 
declare variable OLD_ID_PICTURE integer;
begin
  NEW_ID_PAYMENT = ID_PAYMENT;
  if (OPERATION = 'add') then begin
    NEW_ID_PAYMENT = gen_id(GEN_PAYMENT_ID, 1);
    insert into PAYMENTS
      (ID_PAYMENT, ID_EVENT_INVENTORY, PAYMENT_TYPE, PAYMENT_DATE, PAYMENT_VALUE,
      PAYMENT_METHOD, PAYMENT_DESC, PAYMENT_TIMESTAMP, ID_PICTURE)
    values
      (:NEW_ID_PAYMENT, :ID_EVENT_INVENTORY, :PAYMENT_TYPE, :PAYMENT_DATE, :PAYMENT_VALUE,
      :PAYMENT_METHOD, :PAYMENT_DESC, 'now', :ID_PICTURE);
  end else if (OPERATION = 'mod') then begin
    select p.ID_PICTURE
      from PAYMENTS p
      where p.ID_PAYMENT = :ID_PAYMENT
      into :OLD_ID_PICTURE;
    update PAYMENTS
    set ID_EVENT_INVENTORY = :ID_EVENT_INVENTORY,
        PAYMENT_TYPE = :PAYMENT_TYPE,
        PAYMENT_DATE = :PAYMENT_DATE,
        PAYMENT_VALUE = :PAYMENT_VALUE,
        PAYMENT_METHOD = :PAYMENT_METHOD,
        PAYMENT_DESC = :PAYMENT_DESC,
        ID_PICTURE = :ID_PICTURE
    where ID_PAYMENT = :ID_PAYMENT;
    if ((ID_PICTURE is null) and (OLD_ID_PICTURE is not null)) then begin
      execute procedure PICTURE_MODIFY(:OLD_ID_PICTURE, null, null, null, 'del')
      returning_values :ERR_CODE, :ERR_TEXT, :OLD_ID_PICTURE;
    end
  end else if (OPERATION = 'del') then begin
    select p.ID_PICTURE
      from PAYMENTS p
      where p.ID_PAYMENT = :ID_PAYMENT
      into :OLD_ID_PICTURE;
    delete from PAYMENTS
      where ID_PAYMENT = :ID_PAYMENT;
    if (OLD_ID_PICTURE is not null) then begin
      execute procedure PICTURE_MODIFY(:OLD_ID_PICTURE, null, null, null, 'del')
      returning_values :ERR_CODE, :ERR_TEXT, :OLD_ID_PICTURE;
    end
  end
  suspend;
end ^

ALTER PROCEDURE PERCH_FEES_RECALC (ID_EVENT_INVENTORY INTEGER)
AS 
declare variable BIRD_NO integer;
declare variable TMP_INVENTORY_ITEM_ID integer;
declare variable ID_FEE_SCHEME integer;
begin
  -- recreate bird numbers
  BIRD_NO = 0;
  for select eii.ID_EVENT_INVENTORY_ITEM
        from EVENT_INVENTORY_ITEM eii
        where eii.ID_EVENT_INVENTORY = :ID_EVENT_INVENTORY
          and eii.BIRD_NO is not null
        order by eii.BIRD_NO
        into :TMP_INVENTORY_ITEM_ID
  do begin
    BIRD_NO = BIRD_NO + 1;
    update EVENT_INVENTORY_ITEM eii
      set eii.BIRD_NO = :BIRD_NO
      where eii.ID_EVENT_INVENTORY_ITEM = :TMP_INVENTORY_ITEM_ID;
  end

  for select eii.ID_EVENT_INVENTORY_ITEM, eii.BIRD_NO, e.ID_FEE_SCHEME
    from EVENT_INVENTORY_ITEM eii
    join EVENT_INVENTORY ei on ei.ID_EVENT_INVENTORY = eii.ID_EVENT_INVENTORY
    join EVENTS e on e.ID_EVENT = ei.ID_EVENT
    where eii.ID_EVENT_INVENTORY = :ID_EVENT_INVENTORY
      and eii.BIRD_NO is not null
      and eii.IS_BACKUP = 0
    order by eii.BIRD_NO
    into :TMP_INVENTORY_ITEM_ID, :BIRD_NO, :ID_FEE_SCHEME
    do begin
      update EVENT_INVENTORY_ITEM eii
        set eii.PERCH_FEE_VALUE = (select pfi.PERCH_FEE
                                    from PERCH_FEE_ITEM pfi
                                    where pfi.ID_FEE_SCHEME = :ID_FEE_SCHEME and pfi.BIRD_NO = :BIRD_NO)
        where eii.ID_EVENT_INVENTORY_ITEM = :TMP_INVENTORY_ITEM_ID;
    end
end ^

ALTER PROCEDURE PERCH_FEE_ITEM_MODIFY (BIRD_NO SMALLINT,
PERCH_FEE NUMERIC(15, 4),
ID_FEE_SCHEME INTEGER)
RETURNS (NEW_ID_PERCH_FEE_ITEM INTEGER)
AS 
begin
  NEW_ID_PERCH_FEE_ITEM = gen_id(GEN_PERCH_FEE_ITEM_ID, 1);
  insert into PERCH_FEE_ITEM
    (ID_PERCH_FEE_ITEM, BIRD_NO, PERCH_FEE, ID_FEE_SCHEME)
  values
    (:NEW_ID_PERCH_FEE_ITEM, :BIRD_NO, :PERCH_FEE, :ID_FEE_SCHEME);
  suspend;
end ^

ALTER PROCEDURE PICTURE_MODIFY (ID_PICTURE VARCHAR(50) CHARACTER SET NONE,
PICTURE BLOB,
PICTURE_TYPE VARCHAR(50) CHARACTER SET NONE,
PICTURE_LAYOUT VARCHAR(50) CHARACTER SET NONE,
OPERATION VARCHAR(20) CHARACTER SET NONE)
RETURNS (ERR_CODE INTEGER,
ERR_TEXT VARCHAR(100) CHARACTER SET NONE,
NEW_ID_PICTURE INTEGER)
AS 
begin
  err_code = 0;
  err_text = '';
  if (:operation is null) then operation = 'null';
  if (:operation not in ('add', 'mod', 'del')) then begin
    err_code = -85;
    err_text = 'Unknown value for operation in PICTURE_MODIFY, value='||:operation;
    exit;
  end

  new_id_picture = :id_picture;

  if (:operation = 'add') then begin
    if ((:id_picture is null) or (:id_picture <= 0))  then
      new_id_picture = gen_id(GEN_PICTURE_ID, 1);

    insert into PICTURE(
      ID_PICTURE,
      PICTURE, PICTURE_TYPE, PICTURE_LAYOUT)
    values (
      :new_id_picture,
      :picture, :picture_type, :picture_layout);
  end else if (:operation = 'mod') then begin
    update PICTURE
    set PICTURE = :picture,
        PICTURE_TYPE = :picture_type,
        PICTURE_LAYOUT = :PICTURE_LAYOUT
    where ID_PICTURE = :id_PICTURE;
  end else if (:operation = 'del') then begin
    delete from PICTURE
    where ID_PICTURE = :id_PICTURE;
  end
END ^

ALTER PROCEDURE PRIZE_SCHEME_ITEM_FINALIZE (ID_PRIZE_SCHEME INTEGER)
RETURNS (IS_CORECT SMALLINT)
AS 
declare variable TMP_FROM_POSITION smallint;
declare variable TMP_TO_POSITION smallint;
declare variable FROM_POSITION smallint;
declare variable TO_POSITION smallint;
begin
  IS_CORECT = 1;
  TMP_FROM_POSITION = null;
  TMP_TO_POSITION = null;
  for
    select pi.FROM_POSITION, pi.TO_POSITION
    from PRIZE_SCHEME_ITEM pi
    where pi.ID_PRIZE_SCHEME = :ID_PRIZE_SCHEME
    order by pi.FROM_POSITION, pi.TO_POSITION
    into :FROM_POSITION, :TO_POSITION
  do begin
    if ((TMP_FROM_POSITION is not null) and (TMP_TO_POSITION is not null)) then begin
      if (FROM_POSITION > TO_POSITION) then begin
        IS_CORECT = 0;
        break;
      end
      if ((TMP_FROM_POSITION = FROM_POSITION) or (TMP_TO_POSITION = TO_POSITION)) then begin
        IS_CORECT = 0;
        break;
      end
      if ((TMP_TO_POSITION + 1) <> FROM_POSITION) then begin
        IS_CORECT = 0;
        break;
      end
    end
    TMP_FROM_POSITION = FROM_POSITION;
    TMP_TO_POSITION = TO_POSITION;
  end
  suspend;
end ^

ALTER PROCEDURE PRIZE_SCHEME_ITEM_MODIFY (ID_PRIZE_SCHEME_ITEM INTEGER,
FROM_POSITION SMALLINT,
TO_POSITION SMALLINT,
PRIZE_VALUE NUMERIC(15, 4),
ID_PRIZE_SCHEME INTEGER,
OPERATION VARCHAR(3) CHARACTER SET NONE)
RETURNS (NEW_ID_PRIZE_SCHEME_ITEM INTEGER)
AS 
begin
  NEW_ID_PRIZE_SCHEME_ITEM = ID_PRIZE_SCHEME_ITEM;
  if (OPERATION = 'add') then begin
    NEW_ID_PRIZE_SCHEME_ITEM = gen_id(GEN_PRIZE_SCHEME_ITEM_ID, 1);
    insert into PRIZE_SCHEME_ITEM(ID_PRIZE_SCHEME_ITEM, FROM_POSITION, TO_POSITION, PRIZE_VALUE, ID_PRIZE_SCHEME)
    values (:NEW_ID_PRIZE_SCHEME_ITEM, :FROM_POSITION, :TO_POSITION, :PRIZE_VALUE, :ID_PRIZE_SCHEME);
  end else if (OPERATION = 'mod') then begin
    update PRIZE_SCHEME_ITEM
    set FROM_POSITION = :FROM_POSITION,
        TO_POSITION = :TO_POSITION,
        PRIZE_VALUE = :PRIZE_VALUE,
        ID_PRIZE_SCHEME = :ID_PRIZE_SCHEME
    where ID_PRIZE_SCHEME_ITEM = :ID_PRIZE_SCHEME_ITEM;
  end else if (OPERATION = 'del') then begin
    delete from PRIZE_SCHEME_ITEM
    where ID_PRIZE_SCHEME_ITEM = :ID_PRIZE_SCHEME_ITEM;
  end
  suspend;
end ^

ALTER PROCEDURE PRIZE_SCHEME_MODIFY (ID_PRIZE_SCHEME INTEGER,
PRIZE_NAME VARCHAR(20) CHARACTER SET NONE,
OPERATION VARCHAR(3) CHARACTER SET NONE)
RETURNS (NEW_ID_PRIZE_SCHEME INTEGER,
ERR_CODE INTEGER,
ERR_TEXT VARCHAR(250) CHARACTER SET NONE)
AS 
begin
  ERR_CODE = 0;
  ERR_TEXT = '';
  NEW_ID_PRIZE_SCHEME = ID_PRIZE_SCHEME;
  if (OPERATION = 'add') then begin
    NEW_ID_PRIZE_SCHEME = gen_id(GEN_PRIZE_SCHEME_ID, 1);
    insert into PRIZE_SCHEME(ID_PRIZE_SCHEME, PRIZE_NAME)
    values (:NEW_ID_PRIZE_SCHEME, :PRIZE_NAME);
  end else if (OPERATION = 'mod') then begin
    update PRIZE_SCHEME
    set PRIZE_NAME = :PRIZE_NAME
    where (ID_PRIZE_SCHEME = :ID_PRIZE_SCHEME);
  end else if (OPERATION = 'del') then begin
    delete from PRIZE_SCHEME
    where (ID_PRIZE_SCHEME = :ID_PRIZE_SCHEME);
  end
  suspend;
end ^

ALTER PROCEDURE PRIZE_VALUE_MODIFY (ID_EVENT INTEGER,
ID_RACE_TYPE INTEGER,
ID_PRIZE_SCHEME_ITEM INTEGER,
PRIZE_VALUE NUMERIC(15, 4),
OPERATION VARCHAR(5) CHARACTER SET NONE)
RETURNS (NEW_ID_PRIZE_VALUE INTEGER)
AS 
begin
  if (OPERATION = 'set') then begin
    NEW_ID_PRIZE_VALUE = gen_id(GEN_PRIZE_VALUE_ID, 1);
    insert into PRIZE_VALUE(ID_PRIZE_VALUE, ID_EVENT, ID_RACE_TYPE, ID_PRIZE_SCHEME_ITEM, PRIZE_VALUE)
    values (:NEW_ID_PRIZE_VALUE, :ID_EVENT, :ID_RACE_TYPE, :ID_PRIZE_SCHEME_ITEM, :PRIZE_VALUE);
  end else if (OPERATION = 'clear') then begin
    delete from PRIZE_VALUE pv
    where pv.ID_EVENT = :ID_EVENT and pv.ID_RACE_TYPE = :ID_RACE_TYPE;
  end
end ^

ALTER PROCEDURE P_CLONE_EVENT_INVENTORY AS 
