ID_EVENT_INVENTORY_NEW = GEN_ID(GEN_EVENT_INVENTORY_ID, 1);

INSERT INTO EVENT_INVENTORY
(
  ID_EVENT_INVENTORY,
  ID_EVENT,
  ID_BREEDER,
  SIGN_IN_DATE,
  WAITING_DATE,
  IS_WAITING,
  RESERVED_BIRDS,
  LOFT,
