ALTER PROCEDURE P_CLONE_RACE AS 
DECLARE VARIABLE  ID_RACE                               INTEGER ;
DECLARE VARIABLE  ID_RACE_TYPE                      INTEGER ;
DECLARE VARIABLE  RACE_NUMBER                     INTEGER ;
DECLARE VARIABLE  ID_EVENT                          INTEGER ;
DECLARE VARIABLE  LOCATION                         VARCHAR(50) ;
DECLARE VARIABLE  DESCRIPTION                     VARCHAR(250) ;
DECLARE VARIABLE  DISTANCE                        INTEGER ;
DECLARE VARIABLE  START_TIME                      TIMESTAMP ;
DECLARE VARIABLE  END_TIME                        TIMESTAMP ;
DECLARE VARIABLE  SUNRISE                            TIME ;
DECLARE VARIABLE  SUNSET                             TIME ;
DECLARE VARIABLE  IS_CLOSED                        SMALLINT ;
DECLARE VARIABLE  WEATHER                         VARCHAR(100) ;
DECLARE VARIABLE  WIND                            VARCHAR(100) ;
DECLARE VARIABLE  TEMPERATURE                     VARCHAR(100) ;
DECLARE VARIABLE  ARRIVAL_WEATHER                 VARCHAR(100) ;
DECLARE VARIABLE  ARRIVAL_WIND                    VARCHAR(100) ;
DECLARE VARIABLE  ARRIVAL_TEMPERATURE             VARCHAR(100) ;
    
begin

FOR 
SELECT
  ID_RACE_TYPE,
  RACE_NUMBER,
  LOCATION,
  DESCRIPTION,
  DISTANCE,
  START_TIME,
  END_TIME,
  SUNRISE,
  SUNSET,
  IS_CLOSED,
  WEATHER,
  WIND,
  TEMPERATURE,
  ARRIVAL_WEATHER,
  ARRIVAL_WIND,
  ARRIVAL_TEMPERATURE
FROM
  RACE
WHERE (ID_EVENT = 17)
INTO
  :ID_RACE_TYPE,
  :RACE_NUMBER,
  :LOCATION,
  :DESCRIPTION,
  :DISTANCE,
  :START_TIME,
  :END_TIME,
  :SUNRISE,
  :SUNSET,
  :IS_CLOSED,
  :WEATHER,
  :WIND,
  :TEMPERATURE,
  :ARRIVAL_WEATHER,
  :ARRIVAL_WIND,
  :ARRIVAL_TEMPERATURE
DO BEGIN

INSERT INTO RACE
(
  ID_RACE,
  ID_RACE_TYPE,
  RACE_NUMBER,
  ID_EVENT,
  LOCATION,
  DESCRIPTION,
  DISTANCE,
  START_TIME,
  END_TIME,
  SUNRISE,
  SUNSET,
  IS_CLOSED,
  WEATHER,
  WIND,
  TEMPERATURE,
  ARRIVAL_WEATHER,
  ARRIVAL_WIND,
  ARRIVAL_TEMPERATURE
)
VALUES
(
  GEN_ID(GEN_RACE_ID, 1),
  :ID_RACE_TYPE,
  :RACE_NUMBER,
  18,
  :LOCATION,
  :DESCRIPTION,
  :DISTANCE,
  :START_TIME,
  :END_TIME,
  :SUNRISE,
  :SUNSET,
  :IS_CLOSED,
  :WEATHER,
  :WIND,
  :TEMPERATURE,
  :ARRIVAL_WEATHER,
  :ARRIVAL_WIND,
  :ARRIVAL_TEMPERATURE
);

END 
  
end ^

ALTER PROCEDURE RACE_AVG_SPEED_GET (SELECTED_TAG VARCHAR(50) CHARACTER SET NONE,
ID_EVENT INTEGER,
ONLY_HOT_SPOT_PAID SMALLINT,
HOT_SPOT_CALC_PRIZE SMALLINT)
RETURNS (ID_EVENT_INVENTORY_ITEM INTEGER,
BIRD_POSITION INTEGER,
RACE_COUNT INTEGER,
TOTAL_FLIGHT_TIME BIGINT,
TOTAL_FLIGHT_DISTANCE INTEGER,
AVG_SPEED_IN_YARDS NUMERIC(15, 4),
AVG_SPEED_IN_MILES NUMERIC(15, 4),
HOT_SPOT_PRIZE_VALUE NUMERIC(15, 4))
AS 
declare variable ID_PRIZE_SCHEME integer;
begin
 select e.ID_HOT_SPOT_AVG_PRIZE_SCHEME
  from EVENTS e
  where e.ID_EVENT = :ID_EVENT
  into :ID_PRIZE_SCHEME;

 BIRD_POSITION = 0;
 for select ras.ID_EVENT_INVENTORY_ITEM, ras.RACE_COUNT, ras.TOTAL_FLIGHT_DISTANCE, ras.TOTAL_FLIGHT_TIME,
   ras.AVG_SPEED_IN_YARDS, ras.AVG_SPEED_IN_MILES
   from CALC_RACE_AVG_SPEED_INT(:SELECTED_TAG, :ONLY_HOT_SPOT_PAID) ras
   order by ras.RACE_COUNT desc, ras.AVG_SPEED_IN_YARDS desc, ras.AVG_SPEED_IN_MILES desc
   into :ID_EVENT_INVENTORY_ITEM, :RACE_COUNT, :TOTAL_FLIGHT_DISTANCE, :TOTAL_FLIGHT_TIME,
     :AVG_SPEED_IN_YARDS, :AVG_SPEED_IN_MILES
 do begin
   BIRD_POSITION = BIRD_POSITION + 1;

   if (coalesce(HOT_SPOT_CALC_PRIZE, 0) > 0) then begin
     execute procedure GET_PRIZE_VALUE(:ID_PRIZE_SCHEME, :ID_EVENT, 9 /* avg winner prize */ , :BIRD_POSITION, :BIRD_POSITION)
     returning_values :HOT_SPOT_PRIZE_VALUE;
   end

   suspend;
 end
end ^

ALTER PROCEDURE RACE_BETS_CALC (ID_RACE INTEGER)
RETURNS (ID_RACE_ITEM INTEGER,
ID_EVENT_INVENTORY_ITEM INTEGER,
BELGIAN_SHOW_1 NUMERIC(15, 4),
BELGIAN_SHOW_2 NUMERIC(15, 4),
BELGIAN_SHOW_3 NUMERIC(15, 4),
BELGIAN_SHOW_4 NUMERIC(15, 4),
BELGIAN_SHOW_5 NUMERIC(15, 4),
BELGIAN_SHOW_6 NUMERIC(15, 4),
BELGIAN_SHOW_7 NUMERIC(15, 4),
STANDARD_SHOW_1 NUMERIC(15, 4),
STANDARD_SHOW_2 NUMERIC(15, 4),
STANDARD_SHOW_3 NUMERIC(15, 4),
STANDARD_SHOW_4 NUMERIC(15, 4),
STANDARD_SHOW_5 NUMERIC(15, 4),
STANDARD_SHOW_6 NUMERIC(15, 4),
WTA_1 NUMERIC(15, 4),
WTA_2 NUMERIC(15, 4),
WTA_3 NUMERIC(15, 4),
WTA_4 NUMERIC(15, 4),
WTA_5 NUMERIC(15, 4),
TOTAL NUMERIC(15, 4))
AS 
declare variable ID_EVENT integer;
  declare variable ID_BETTING_SCHEME integer;
  declare variable TOTAL_BELGIAN_SHOW_1 numeric(15,4);
  declare variable TOTAL_BELGIAN_SHOW_2 numeric(15,4);
  declare variable TOTAL_BELGIAN_SHOW_3 numeric(15,4);
  declare variable TOTAL_BELGIAN_SHOW_4 numeric(15,4);
  declare variable TOTAL_BELGIAN_SHOW_5 numeric(15,4);
  declare variable TOTAL_BELGIAN_SHOW_6 numeric(15,4);
  declare variable TOTAL_BELGIAN_SHOW_7 numeric(15,4);
  declare variable TOTAL_STANDARD_SHOW_1 numeric(15,4);
  declare variable TOTAL_STANDARD_SHOW_2 numeric(15,4);
  declare variable TOTAL_STANDARD_SHOW_3 numeric(15,4);
  declare variable TOTAL_STANDARD_SHOW_4 numeric(15,4);
  declare variable TOTAL_STANDARD_SHOW_5 numeric(15,4);
  declare variable TOTAL_STANDARD_SHOW_6 numeric(15,4);
  declare variable TOTAL_WTA_1 numeric(15,4);
  declare variable TOTAL_WTA_2 numeric(15,4);
  declare variable TOTAL_WTA_3 numeric(15,4);
  declare variable TOTAL_WTA_4 numeric(15,4);
  declare variable TOTAL_WTA_5 numeric(15,4);
  declare variable BELGIAN_SHOW_BET_1 smallint;
  declare variable BELGIAN_SHOW_BET_2 smallint;
  declare variable BELGIAN_SHOW_BET_3 smallint;
  declare variable BELGIAN_SHOW_BET_4 smallint;
  declare variable BELGIAN_SHOW_BET_5 smallint;
  declare variable BELGIAN_SHOW_BET_6 smallint;
  declare variable BELGIAN_SHOW_BET_7 smallint;
  declare variable STANDARD_SHOW_BET_1 smallint;
  declare variable STANDARD_SHOW_BET_2 smallint;
  declare variable STANDARD_SHOW_BET_3 smallint;
  declare variable STANDARD_SHOW_BET_4 smallint;
  declare variable STANDARD_SHOW_BET_5 smallint;
  declare variable STANDARD_SHOW_BET_6 smallint;
  declare variable WTA_BET_1 smallint;
  declare variable WTA_BET_2 smallint;
  declare variable WTA_BET_3 smallint;
  declare variable WTA_BET_4 smallint;
  declare variable WTA_BET_5 smallint;
  declare variable VALUE_BELGIAN_SHOW_1 numeric(15,4);
  declare variable VALUE_BELGIAN_SHOW_2 numeric(15,4);
  declare variable VALUE_BELGIAN_SHOW_3 numeric(15,4);
  declare variable VALUE_BELGIAN_SHOW_4 numeric(15,4);
  declare variable VALUE_BELGIAN_SHOW_5 numeric(15,4);
  declare variable VALUE_BELGIAN_SHOW_6 numeric(15,4);
  declare variable VALUE_BELGIAN_SHOW_7 numeric(15,4);
  declare variable REST_STANDARD_SHOW_1 numeric(15,4);
  declare variable REST_STANDARD_SHOW_2 numeric(15,4);
  declare variable REST_STANDARD_SHOW_3 numeric(15,4);
  declare variable REST_STANDARD_SHOW_4 numeric(15,4);
  declare variable REST_STANDARD_SHOW_5 numeric(15,4);
  declare variable REST_STANDARD_SHOW_6 numeric(15,4);
  declare variable TMP_STANDARD_SHOW_1_PLACE integer;
  declare variable TMP_STANDARD_SHOW_2_PLACE integer;
  declare variable TMP_STANDARD_SHOW_3_PLACE integer;
  declare variable TMP_STANDARD_SHOW_4_PLACE integer;
  declare variable TMP_STANDARD_SHOW_5_PLACE integer;
  declare variable TMP_STANDARD_SHOW_6_PLACE integer;
  declare variable SSP_PERCENT numeric(15,4);
  declare variable BIRD_DROP integer;
  declare variable BIRD_IN_DROP integer;
  declare variable TOTAL_BET_VALUE numeric(15,4);
  declare variable ID_RACE_TYPE integer;
  declare variable BIRD_POSITION integer;
  declare variable EXEC_TIME timestamp;
  declare variable IS_BET_ACTIVE smallint;
begin
  select r.ID_EVENT, r.ID_RACE_TYPE, e.ID_BETTING_SCHEME
    from RACE r
    join EVENTS e on e.ID_EVENT = r.ID_EVENT
    where r.ID_RACE = :ID_RACE
    into :ID_EVENT, :ID_RACE_TYPE, :ID_BETTING_SCHEME;
  if (ID_RACE_TYPE <> 5 /* final race */) then begin
    exit;
  end

  /* Calculating totals */
  select ebt.BELGIAN_SHOW_1_WO_COM, ebt.BELGIAN_SHOW_2_WO_COM, ebt.BELGIAN_SHOW_3_WO_COM,
      ebt.BELGIAN_SHOW_4_WO_COM, ebt.BELGIAN_SHOW_5_WO_COM, ebt.BELGIAN_SHOW_6_WO_COM,
      ebt.BELGIAN_SHOW_7_WO_COM, ebt.STANDARD_SHOW_1_WO_COM, ebt.STANDARD_SHOW_2_WO_COM,
      ebt.STANDARD_SHOW_3_WO_COM, ebt.STANDARD_SHOW_4_WO_COM, ebt.STANDARD_SHOW_5_WO_COM,
      ebt.STANDARD_SHOW_6_WO_COM, ebt.WTA_1_WO_COM, ebt.WTA_2_WO_COM, ebt.WTA_3_WO_COM, ebt.WTA_4_WO_COM,
      ebt.WTA_5_WO_COM
    from EVENT_BET_TOTALS(:ID_EVENT) ebt
    into :TOTAL_BELGIAN_SHOW_1, :TOTAL_BELGIAN_SHOW_2, :TOTAL_BELGIAN_SHOW_3,
      :TOTAL_BELGIAN_SHOW_4, :TOTAL_BELGIAN_SHOW_5, :TOTAL_BELGIAN_SHOW_6,
      :TOTAL_BELGIAN_SHOW_7, :TOTAL_STANDARD_SHOW_1, :TOTAL_STANDARD_SHOW_2,
      :TOTAL_STANDARD_SHOW_3, :TOTAL_STANDARD_SHOW_4, :TOTAL_STANDARD_SHOW_5,
      :TOTAL_STANDARD_SHOW_6, :TOTAL_WTA_1, :TOTAL_WTA_2, :TOTAL_WTA_3, :TOTAL_WTA_4,
      :TOTAL_WTA_5;

  /* Selecting betting pools for belgian show (10 to 1)*/
  select bs.BELGIAN_SHOW_1, bs.BELGIAN_SHOW_2, bs.BELGIAN_SHOW_3, bs.BELGIAN_SHOW_4,
      bs.BELGIAN_SHOW_5, bs.BELGIAN_SHOW_6, bs.BELGIAN_SHOW_7
    from BETTING_SCHEME bs
    where bs.ID_BETTING_SCHEME = :ID_BETTING_SCHEME
    into :VALUE_BELGIAN_SHOW_1, :VALUE_BELGIAN_SHOW_2, :VALUE_BELGIAN_SHOW_3, :VALUE_BELGIAN_SHOW_4,
      :VALUE_BELGIAN_SHOW_5, :VALUE_BELGIAN_SHOW_6, :VALUE_BELGIAN_SHOW_7;

  TMP_STANDARD_SHOW_1_PLACE = 1;
  TMP_STANDARD_SHOW_2_PLACE = 1;
  TMP_STANDARD_SHOW_3_PLACE = 1;
  TMP_STANDARD_SHOW_4_PLACE = 1;
  TMP_STANDARD_SHOW_5_PLACE = 1;
  TMP_STANDARD_SHOW_6_PLACE = 1;
  REST_STANDARD_SHOW_1 = TOTAL_STANDARD_SHOW_1;
  REST_STANDARD_SHOW_2 = TOTAL_STANDARD_SHOW_2;
  REST_STANDARD_SHOW_3 = TOTAL_STANDARD_SHOW_3;
  REST_STANDARD_SHOW_4 = TOTAL_STANDARD_SHOW_4;
  REST_STANDARD_SHOW_5 = TOTAL_STANDARD_SHOW_5;
  REST_STANDARD_SHOW_6 = TOTAL_STANDARD_SHOW_6;
  EXEC_TIME = 'now';
  for select ri.ID_RACE_ITEM, rir.BIRD_POSITION, rir.BIRD_DROP, eii.BELGIAN_SHOW_BET_1,
      eii.BELGIAN_SHOW_BET_2, eii.BELGIAN_SHOW_BET_3, eii.BELGIAN_SHOW_BET_4,
      eii.BELGIAN_SHOW_BET_5, eii.BELGIAN_SHOW_BET_6, eii.BELGIAN_SHOW_BET_7,
      eii.STANDARD_SHOW_BET_1, eii.STANDARD_SHOW_BET_2, eii.STANDARD_SHOW_BET_3,
      eii.STANDARD_SHOW_BET_4, eii.STANDARD_SHOW_BET_5, eii.STANDARD_SHOW_BET_6,
      eii.WTA_BET_1, eii.WTA_BET_2, eii.WTA_BET_3, eii.WTA_BET_4, eii.WTA_BET_5,
      eii.IS_BET_ACTIVE
    from RACE_ITEM ri
    join EVENT_INVENTORY_ITEM eii on eii.ID_EVENT_INVENTORY_ITEM = ri.ID_INVENTORY_ITEM
    left join RACE_ITEM_RESULT rir on rir.ID_RACE_ITEM = ri.ID_RACE_ITEM
    where ri.ID_RACE = :ID_RACE
    order by rir.BIRD_POSITION nulls last, rir.ARRIVAL_TIME, rir.BIRD_DROP
    into :ID_RACE_ITEM, :BIRD_POSITION, :BIRD_DROP, :BELGIAN_SHOW_BET_1, :BELGIAN_SHOW_BET_2, :BELGIAN_SHOW_BET_3,
      :BELGIAN_SHOW_BET_4, :BELGIAN_SHOW_BET_5, :BELGIAN_SHOW_BET_6,
      :BELGIAN_SHOW_BET_7, :STANDARD_SHOW_BET_1, :STANDARD_SHOW_BET_2,
      :STANDARD_SHOW_BET_3, :STANDARD_SHOW_BET_4, :STANDARD_SHOW_BET_5,
      :STANDARD_SHOW_BET_6, :WTA_BET_1, :WTA_BET_2, :WTA_BET_3,
      :WTA_BET_4, :WTA_BET_5, :IS_BET_ACTIVE
  do begin
    /* Calculating winning prize for the different betting schemes for each bet bird */
    /* Calculating winning prize for BELGIAN SHOW */
    BELGIAN_SHOW_1 = null;
    if ((IS_BET_ACTIVE <> 0) and (BIRD_POSITION is not null) and (VALUE_BELGIAN_SHOW_1 is not null) and (BELGIAN_SHOW_BET_1 = 1)) then begin
      BELGIAN_SHOW_1 = 0;
      if (TOTAL_BELGIAN_SHOW_1 > 0) then begin
        BELGIAN_SHOW_1 = VALUE_BELGIAN_SHOW_1 * 10;
        if (BELGIAN_SHOW_1 > TOTAL_BELGIAN_SHOW_1) then begin
          BELGIAN_SHOW_1 = TOTAL_BELGIAN_SHOW_1;
          TOTAL_BELGIAN_SHOW_1 = 0;
        end else begin
          TOTAL_BELGIAN_SHOW_1 = TOTAL_BELGIAN_SHOW_1 - BELGIAN_SHOW_1;
        end
      end
    end

    BELGIAN_SHOW_2 = null;
    if ((IS_BET_ACTIVE <> 0) and (BIRD_POSITION is not null) and (VALUE_BELGIAN_SHOW_2 is not null) and (BELGIAN_SHOW_BET_2 = 1)) then begin
      BELGIAN_SHOW_2 = 0;
