    if ((IS_BET_ACTIVE <> 0) and (BIRD_POSITION is not null) and (VALUE_BELGIAN_SHOW_3 is not null) and (BELGIAN_SHOW_BET_3 = 1)) then begin
      BELGIAN_SHOW_3 = 0;
      if (TOTAL_BELGIAN_SHOW_3 > 0) then begin
       BELGIAN_SHOW_3 = VALUE_BELGIAN_SHOW_3 * 10;
        if (BELGIAN_SHOW_3 > TOTAL_BELGIAN_SHOW_3) then begin
          BELGIAN_SHOW_3 = TOTAL_BELGIAN_SHOW_3;
