    if ((IS_BET_ACTIVE <> 0) and (BIRD_POSITION is not null) and (VALUE_BELGIAN_SHOW_4 is not null) and (BELGIAN_SHOW_BET_4 = 1)) then begin
      BELGIAN_SHOW_4 = 0;
      if (TOTAL_BELGIAN_SHOW_4 > 0) then begin
        BELGIAN_SHOW_4 = VALUE_BELGIAN_SHOW_4 * 10;
        if (BELGIAN_SHOW_4 > TOTAL_BELGIAN_SHOW_4) then begin
          BELGIAN_SHOW_4 = TOTAL_BELGIAN_SHOW_4;
          TOTAL_BELGIAN_SHOW_4 = 0;
        end else begin
          TOTAL_BELGIAN_SHOW_4 = TOTAL_BELGIAN_SHOW_4 - BELGIAN_SHOW_4;
        end
