    end

    BELGIAN_SHOW_5 = null;
    if ((IS_BET_ACTIVE <> 0) and (BIRD_POSITION is not null) and (VALUE_BELGIAN_SHOW_5 is not null) and (BELGIAN_SHOW_BET_5 = 1)) then begin
      BELGIAN_SHOW_5 = 0;
      if (TOTAL_BELGIAN_SHOW_5 > 0) then begin
        BELGIAN_SHOW_5 = VALUE_BELGIAN_SHOW_5 * 10;
        if (BELGIAN_SHOW_5 > TOTAL_BELGIAN_SHOW_5) then begin
          BELGIAN_SHOW_5 = TOTAL_BELGIAN_SHOW_5;
          TOTAL_BELGIAN_SHOW_5 = 0;
        end else begin
          TOTAL_BELGIAN_SHOW_5 = TOTAL_BELGIAN_SHOW_5 - BELGIAN_SHOW_5;
        end
      end
    end
    
    BELGIAN_SHOW_6 = null;
    if ((IS_BET_ACTIVE <> 0) and (BIRD_POSITION is not null) and (VALUE_BELGIAN_SHOW_6 is not null) and (BELGIAN_SHOW_BET_6 = 1)) then begin
