    end
    
    BELGIAN_SHOW_7 = null;
    if ((IS_BET_ACTIVE <> 0) and (BIRD_POSITION is not null) and (VALUE_BELGIAN_SHOW_7 is not null) and (BELGIAN_SHOW_BET_7 = 1)) then begin
      TOTAL_BELGIAN_SHOW_7 = 0;
      if (TOTAL_BELGIAN_SHOW_7 > 0) then begin
        BELGIAN_SHOW_7 = VALUE_BELGIAN_SHOW_7 * 10;
        if (BELGIAN_SHOW_7 > TOTAL_BELGIAN_SHOW_7) then begin
