        end else begin
          TOTAL_BELGIAN_SHOW_7 = TOTAL_BELGIAN_SHOW_7 - BELGIAN_SHOW_7;
        end
      end
    end

    /* Calculating winning prize for STANDARD SHOW */
    STANDARD_SHOW_1 = null;
    if ((IS_BET_ACTIVE <> 0) and (BIRD_POSITION is not null) and (STANDARD_SHOW_BET_1 = 1)) then begin
      STANDARD_SHOW_1 = 0;
      if (REST_STANDARD_SHOW_1 > 0) then begin
        select ssp.PERC_VALUE
          from STANDARD_SHOW_PERCENTAGE ssp
          where ssp.ID_BETTING_SCHEME = :ID_BETTING_SCHEME and ssp.PLACE = :TMP_STANDARD_SHOW_1_PLACE
          into :SSP_PERCENT;
        TMP_STANDARD_SHOW_1_PLACE = TMP_STANDARD_SHOW_1_PLACE + 1;
        STANDARD_SHOW_1 = (TOTAL_STANDARD_SHOW_1 * SSP_PERCENT) / 100;
        if (STANDARD_SHOW_1 > REST_STANDARD_SHOW_1) then begin
          STANDARD_SHOW_1 = REST_STANDARD_SHOW_1;
          REST_STANDARD_SHOW_1 = 0;
        end else begin
          REST_STANDARD_SHOW_1 = REST_STANDARD_SHOW_1 - STANDARD_SHOW_1;
        end
      end
    end

    STANDARD_SHOW_2 = null;
    if ((IS_BET_ACTIVE <> 0) and (BIRD_POSITION is not null) and (STANDARD_SHOW_BET_2 = 1)) then begin
