    if ((IS_BET_ACTIVE <> 0) and (BIRD_POSITION is not null) and (STANDARD_SHOW_BET_3 = 1)) then begin
      STANDARD_SHOW_3 = 0;
      if (REST_STANDARD_SHOW_3 > 0) then begin
        select ssp.PERC_VALUE
          from STANDARD_SHOW_PERCENTAGE ssp
          where ssp.ID_BETTING_SCHEME = :ID_BETTING_SCHEME and ssp.PLACE = :TMP_STANDARD_SHOW_3_PLACE
          into :SSP_PERCENT;
        TMP_STANDARD_SHOW_3_PLACE = TMP_STANDARD_SHOW_3_PLACE + 1;
        STANDARD_SHOW_3 = (TOTAL_STANDARD_SHOW_3 * SSP_PERCENT) / 100;
        if (STANDARD_SHOW_3 > REST_STANDARD_SHOW_3) then begin
          STANDARD_SHOW_3 = REST_STANDARD_SHOW_3;
          REST_STANDARD_SHOW_3 = 0;
        end else begin
          REST_STANDARD_SHOW_3 = REST_STANDARD_SHOW_3 - STANDARD_SHOW_3;
        end
      end
    end
    
    STANDARD_SHOW_4 = null;
    if ((IS_BET_ACTIVE <> 0) and (BIRD_POSITION is not null) and (STANDARD_SHOW_BET_4 = 1)) then begin
      STANDARD_SHOW_4 = 0;
      if (REST_STANDARD_SHOW_4 > 0) then begin
        select ssp.PERC_VALUE
          from STANDARD_SHOW_PERCENTAGE ssp
          where ssp.ID_BETTING_SCHEME = :ID_BETTING_SCHEME and ssp.PLACE = :TMP_STANDARD_SHOW_4_PLACE
          into :SSP_PERCENT;
        TMP_STANDARD_SHOW_4_PLACE = TMP_STANDARD_SHOW_4_PLACE + 1;
        STANDARD_SHOW_4 = (TOTAL_STANDARD_SHOW_4 * SSP_PERCENT) / 100;
        if (STANDARD_SHOW_4 > REST_STANDARD_SHOW_4) then begin
          STANDARD_SHOW_4 = REST_STANDARD_SHOW_4;
          REST_STANDARD_SHOW_4 = 0;
        end else begin
          REST_STANDARD_SHOW_4 = REST_STANDARD_SHOW_4 - STANDARD_SHOW_4;
        end
      end
    end

    STANDARD_SHOW_5 = null;
    if ((IS_BET_ACTIVE <> 0) and (BIRD_POSITION is not null) and (STANDARD_SHOW_BET_5 = 1)) then begin
      STANDARD_SHOW_5 = 0;
      if (REST_STANDARD_SHOW_5 > 0) then begin
        select ssp.PERC_VALUE
          from STANDARD_SHOW_PERCENTAGE ssp
          where ssp.ID_BETTING_SCHEME = :ID_BETTING_SCHEME and ssp.PLACE = :TMP_STANDARD_SHOW_5_PLACE
          into :SSP_PERCENT;
        TMP_STANDARD_SHOW_5_PLACE = TMP_STANDARD_SHOW_5_PLACE + 1;
        STANDARD_SHOW_5 = (TOTAL_STANDARD_SHOW_5 * SSP_PERCENT) / 100;
        if (STANDARD_SHOW_5 > REST_STANDARD_SHOW_5) then begin
