        end
      end
    end

    STANDARD_SHOW_6 = null;
    if ((IS_BET_ACTIVE <> 0) and (BIRD_POSITION is not null) and (STANDARD_SHOW_BET_6 = 1)) then begin
      STANDARD_SHOW_6 = 0;
      if (REST_STANDARD_SHOW_6 > 0) then begin
        select ssp.PERC_VALUE
          from STANDARD_SHOW_PERCENTAGE ssp
          where ssp.ID_BETTING_SCHEME = :ID_BETTING_SCHEME and ssp.PLACE = :TMP_STANDARD_SHOW_6_PLACE
