        end else begin
          REST_STANDARD_SHOW_6 = REST_STANDARD_SHOW_6 - STANDARD_SHOW_6;
        end
      end
    end
    
    /* Calculating winning prize for WINNER TAKE ALL */
    WTA_1 = null;
    if ((IS_BET_ACTIVE <> 0) and (BIRD_POSITION is not null) and (WTA_BET_1 = 1)) then begin
      WTA_1 = 0;
      if (TOTAL_WTA_1 > 0) then begin
        WTA_1 = TOTAL_WTA_1;
        TOTAL_WTA_1 = 0;
      end
    end
    
    WTA_2 = null;
    if ((IS_BET_ACTIVE <> 0) and (BIRD_POSITION is not null) and (WTA_BET_2 = 1)) then begin
      WTA_2 = 0;
      if (TOTAL_WTA_2 > 0) then begin
        WTA_2 = TOTAL_WTA_2;
        TOTAL_WTA_2 = 0;
      end
    end
    
    WTA_3 = null;
    if ((IS_BET_ACTIVE <> 0) and (BIRD_POSITION is not null) and (WTA_BET_3 = 1)) then begin
      WTA_3 = 0;
      if (TOTAL_WTA_3 > 0) then begin
        WTA_3 = TOTAL_WTA_3;
        TOTAL_WTA_3 = 0;
      end
    end

    WTA_4 = null;
    if ((IS_BET_ACTIVE <> 0) and (BIRD_POSITION is not null) and (WTA_BET_4 = 1)) then begin
      WTA_4 = 0;
      if (TOTAL_WTA_4 > 0) then begin
        WTA_4 = TOTAL_WTA_4;
        TOTAL_WTA_4 = 0;
      end
    end

    WTA_5 = null;
    if ((IS_BET_ACTIVE <> 0) and (BIRD_POSITION is not null) and (WTA_BET_5 = 1)) then begin
      WTA_5 = 0;
      if (TOTAL_WTA_5 > 0) then begin
        WTA_5 = TOTAL_WTA_5;
        TOTAL_WTA_5 = 0;
      end
    end
  
    /* Putting the calculated winning prizes to temporary table for the bird drop calculation */
    insert into TMP_BETS(ID_RACE_ITEM, BIRD_DROP, BELGIAN_SHOW_1, BELGIAN_SHOW_2, BELGIAN_SHOW_3,
      BELGIAN_SHOW_4, BELGIAN_SHOW_5, BELGIAN_SHOW_6, BELGIAN_SHOW_7, STANDARD_SHOW_1,
      STANDARD_SHOW_2, STANDARD_SHOW_3, STANDARD_SHOW_4, STANDARD_SHOW_5, STANDARD_SHOW_6,
      WTA_1, WTA_2, WTA_3, WTA_4, WTA_5, EXEC_TIME)
    values (:ID_RACE_ITEM, :BIRD_DROP, :BELGIAN_SHOW_1, :BELGIAN_SHOW_2, :BELGIAN_SHOW_3,
      :BELGIAN_SHOW_4, :BELGIAN_SHOW_5, :BELGIAN_SHOW_6, :BELGIAN_SHOW_7, :STANDARD_SHOW_1,
      :STANDARD_SHOW_2, :STANDARD_SHOW_3, :STANDARD_SHOW_4, :STANDARD_SHOW_5, :STANDARD_SHOW_6,
      :WTA_1, :WTA_2, :WTA_3, :WTA_4, :WTA_5, :EXEC_TIME);
  end

  /* Separating the winnig prize by bird drops for each betting scheme */
  for select tb.BIRD_DROP, count(tb.ID_RACE_ITEM), sum(tb.BELGIAN_SHOW_1)
    from TMP_BETS tb
    where (tb.EXEC_TIME = :EXEC_TIME) and (tb.BIRD_DROP is not null) and (tb.BELGIAN_SHOW_1 is not null)
    group by tb.BIRD_DROP
    into :BIRD_DROP, :BIRD_IN_DROP, :TOTAL_BET_VALUE
  do begin
    if (BIRD_IN_DROP > 1) then begin
      update TMP_BETS tb
        set tb.BELGIAN_SHOW_1 = (:TOTAL_BET_VALUE / :BIRD_IN_DROP)
        where (tb.BIRD_DROP = :BIRD_DROP) and (tb.BELGIAN_SHOW_1 is not null);
    end
  end

  for select tb.BIRD_DROP, count(tb.ID_RACE_ITEM), sum(tb.BELGIAN_SHOW_2)
    from TMP_BETS tb
    where (tb.EXEC_TIME = :EXEC_TIME) and (tb.BIRD_DROP is not null) and (tb.BELGIAN_SHOW_2 is not null)
    group by tb.BIRD_DROP
    into :BIRD_DROP, :BIRD_IN_DROP, :TOTAL_BET_VALUE
  do begin
