        where (tb.BIRD_DROP = :BIRD_DROP) and (tb.BELGIAN_SHOW_2 is not null);
    end
  end

  for select tb.BIRD_DROP, count(tb.ID_RACE_ITEM), sum(tb.BELGIAN_SHOW_3)
