    end
  end

  for select tb.BIRD_DROP, count(tb.ID_RACE_ITEM), sum(tb.BELGIAN_SHOW_4)
    from TMP_BETS tb
    where (tb.EXEC_TIME = :EXEC_TIME) and (tb.BIRD_DROP is not null) and (tb.BELGIAN_SHOW_4 is not null)
    group by tb.BIRD_DROP
    into :BIRD_DROP, :BIRD_IN_DROP, :TOTAL_BET_VALUE
  do begin
