      update TMP_BETS tb
        set tb.BELGIAN_SHOW_4 = (:TOTAL_BET_VALUE / :BIRD_IN_DROP)
        where (tb.BIRD_DROP = :BIRD_DROP) and (tb.BELGIAN_SHOW_4 is not null);
    end
  end

  for select tb.BIRD_DROP, count(tb.ID_RACE_ITEM), sum(tb.BELGIAN_SHOW_5)
    from TMP_BETS tb
    where (tb.EXEC_TIME = :EXEC_TIME) and (tb.BIRD_DROP is not null) and (tb.BELGIAN_SHOW_5 is not null)
    group by tb.BIRD_DROP
    into :BIRD_DROP, :BIRD_IN_DROP, :TOTAL_BET_VALUE
  do begin
    if (BIRD_IN_DROP > 1) then begin
      update TMP_BETS tb
        set tb.BELGIAN_SHOW_5 = (:TOTAL_BET_VALUE / :BIRD_IN_DROP)
        where (tb.BIRD_DROP = :BIRD_DROP) and (tb.BELGIAN_SHOW_5 is not null);
    end
  end

  for select tb.BIRD_DROP, count(tb.ID_RACE_ITEM), sum(tb.BELGIAN_SHOW_6)
    from TMP_BETS tb
    where (tb.EXEC_TIME = :EXEC_TIME) and (tb.BIRD_DROP is not null) and (tb.BELGIAN_SHOW_6 is not null)
    group by tb.BIRD_DROP
    into :BIRD_DROP, :BIRD_IN_DROP, :TOTAL_BET_VALUE
  do begin
