  for select tb.BIRD_DROP, count(tb.ID_RACE_ITEM), sum(tb.BELGIAN_SHOW_7)
    from TMP_BETS tb
    where (tb.EXEC_TIME = :EXEC_TIME) and (tb.BIRD_DROP is not null) and (tb.BELGIAN_SHOW_7 is not null)
    group by tb.BIRD_DROP
    into :BIRD_DROP, :BIRD_IN_DROP, :TOTAL_BET_VALUE
  do begin
    if (BIRD_IN_DROP > 1) then begin
      update TMP_BETS tb
        set tb.BELGIAN_SHOW_7 = (:TOTAL_BET_VALUE / :BIRD_IN_DROP)
        where (tb.BIRD_DROP = :BIRD_DROP) and (tb.BELGIAN_SHOW_7 is not null);
    end
  end

  for select tb.BIRD_DROP, count(tb.ID_RACE_ITEM), sum(tb.STANDARD_SHOW_1)
    from TMP_BETS tb
    where (tb.EXEC_TIME = :EXEC_TIME) and (tb.BIRD_DROP is not null) and (tb.STANDARD_SHOW_1 is not null)
    group by tb.BIRD_DROP
    into :BIRD_DROP, :BIRD_IN_DROP, :TOTAL_BET_VALUE
  do begin
    if (BIRD_IN_DROP > 1) then begin
      update TMP_BETS tb
        set tb.STANDARD_SHOW_1 = (:TOTAL_BET_VALUE / :BIRD_IN_DROP)
        where (tb.BIRD_DROP = :BIRD_DROP) and (tb.STANDARD_SHOW_1 is not null);
    end
  end

  for select tb.BIRD_DROP, count(tb.ID_RACE_ITEM), sum(tb.STANDARD_SHOW_2)
    from TMP_BETS tb
    where (tb.EXEC_TIME = :EXEC_TIME) and (tb.BIRD_DROP is not null) and (tb.STANDARD_SHOW_2 is not null)
    group by tb.BIRD_DROP
    into :BIRD_DROP, :BIRD_IN_DROP, :TOTAL_BET_VALUE
  do begin
    if (BIRD_IN_DROP > 1) then begin
      update TMP_BETS tb
        set tb.STANDARD_SHOW_2 = (:TOTAL_BET_VALUE / :BIRD_IN_DROP)
        where (tb.BIRD_DROP = :BIRD_DROP) and (tb.STANDARD_SHOW_2 is not null);
    end
  end

  for select tb.BIRD_DROP, count(tb.ID_RACE_ITEM), sum(tb.STANDARD_SHOW_3)
    from TMP_BETS tb
    where (tb.EXEC_TIME = :EXEC_TIME) and (tb.BIRD_DROP is not null) and (tb.STANDARD_SHOW_3 is not null)
    group by tb.BIRD_DROP
    into :BIRD_DROP, :BIRD_IN_DROP, :TOTAL_BET_VALUE
  do begin
    if (BIRD_IN_DROP > 1) then begin
      update TMP_BETS tb
        set tb.STANDARD_SHOW_3 = (:TOTAL_BET_VALUE / :BIRD_IN_DROP)
        where (tb.BIRD_DROP = :BIRD_DROP) and (tb.STANDARD_SHOW_3 is not null);
    end
  end
  
  for select tb.BIRD_DROP, count(tb.ID_RACE_ITEM), sum(tb.STANDARD_SHOW_4)
    from TMP_BETS tb
    where (tb.EXEC_TIME = :EXEC_TIME) and (tb.BIRD_DROP is not null) and (tb.STANDARD_SHOW_4 is not null)
    group by tb.BIRD_DROP
    into :BIRD_DROP, :BIRD_IN_DROP, :TOTAL_BET_VALUE
  do begin
    if (BIRD_IN_DROP > 1) then begin
      update TMP_BETS tb
        set tb.STANDARD_SHOW_4 = (:TOTAL_BET_VALUE / :BIRD_IN_DROP)
        where (tb.BIRD_DROP = :BIRD_DROP) and (tb.STANDARD_SHOW_4 is not null);
    end
  end
  
  for select tb.BIRD_DROP, count(tb.ID_RACE_ITEM), sum(tb.STANDARD_SHOW_5)
    from TMP_BETS tb
    where (tb.EXEC_TIME = :EXEC_TIME) and (tb.BIRD_DROP is not null) and (tb.STANDARD_SHOW_5 is not null)
    group by tb.BIRD_DROP
    into :BIRD_DROP, :BIRD_IN_DROP, :TOTAL_BET_VALUE
  do begin
    if (BIRD_IN_DROP > 1) then begin
      update TMP_BETS tb
        set tb.STANDARD_SHOW_5 = (:TOTAL_BET_VALUE / :BIRD_IN_DROP)
        where (tb.BIRD_DROP = :BIRD_DROP) and (tb.STANDARD_SHOW_5 is not null);
    end
  end
  
  for select tb.BIRD_DROP, count(tb.ID_RACE_ITEM), sum(tb.STANDARD_SHOW_6)
    from TMP_BETS tb
    where (tb.EXEC_TIME = :EXEC_TIME) and (tb.BIRD_DROP is not null) and (tb.STANDARD_SHOW_6 is not null)
    group by tb.BIRD_DROP
    into :BIRD_DROP, :BIRD_IN_DROP, :TOTAL_BET_VALUE
  do begin
    if (BIRD_IN_DROP > 1) then begin
      update TMP_BETS tb
        set tb.STANDARD_SHOW_6 = (:TOTAL_BET_VALUE / :BIRD_IN_DROP)
        where (tb.BIRD_DROP = :BIRD_DROP) and (tb.STANDARD_SHOW_6 is not null);
    end
  end
  
  for select tb.BIRD_DROP, count(tb.ID_RACE_ITEM), sum(tb.WTA_1)
    from TMP_BETS tb
    where (tb.EXEC_TIME = :EXEC_TIME) and (tb.BIRD_DROP is not null) and (tb.WTA_1 is not null)
    group by tb.BIRD_DROP
    into :BIRD_DROP, :BIRD_IN_DROP, :TOTAL_BET_VALUE
  do begin
    if (BIRD_IN_DROP > 1) then begin
      update TMP_BETS tb
        set tb.WTA_1 = (:TOTAL_BET_VALUE / :BIRD_IN_DROP)
        where (tb.BIRD_DROP = :BIRD_DROP) and (tb.WTA_1 is not null);
    end
  end

  for select tb.BIRD_DROP, count(tb.ID_RACE_ITEM), sum(tb.WTA_2)
    from TMP_BETS tb
    where (tb.EXEC_TIME = :EXEC_TIME) and (tb.BIRD_DROP is not null) and (tb.WTA_2 is not null)
    group by tb.BIRD_DROP
    into :BIRD_DROP, :BIRD_IN_DROP, :TOTAL_BET_VALUE
  do begin
    if (BIRD_IN_DROP > 1) then begin
      update TMP_BETS tb
        set tb.WTA_2 = (:TOTAL_BET_VALUE / :BIRD_IN_DROP)
        where (tb.BIRD_DROP = :BIRD_DROP) and (tb.WTA_2 is not null);
    end
  end

  for select tb.BIRD_DROP, count(tb.ID_RACE_ITEM), sum(tb.WTA_3)
    from TMP_BETS tb
    where (tb.EXEC_TIME = :EXEC_TIME) and (tb.BIRD_DROP is not null) and (tb.WTA_3 is not null)
    group by tb.BIRD_DROP
    into :BIRD_DROP, :BIRD_IN_DROP, :TOTAL_BET_VALUE
  do begin
    if (BIRD_IN_DROP > 1) then begin
      update TMP_BETS tb
        set tb.WTA_3 = (:TOTAL_BET_VALUE / :BIRD_IN_DROP)
        where (tb.BIRD_DROP = :BIRD_DROP) and (tb.WTA_3 is not null);
    end
  end

  for select tb.BIRD_DROP, count(tb.ID_RACE_ITEM), sum(tb.WTA_4)
    from TMP_BETS tb
    where (tb.EXEC_TIME = :EXEC_TIME) and (tb.BIRD_DROP is not null) and (tb.WTA_4 is not null)
    group by tb.BIRD_DROP
    into :BIRD_DROP, :BIRD_IN_DROP, :TOTAL_BET_VALUE
  do begin
    if (BIRD_IN_DROP > 1) then begin
      update TMP_BETS tb
        set tb.WTA_4 = (:TOTAL_BET_VALUE / :BIRD_IN_DROP)
        where (tb.BIRD_DROP = :BIRD_DROP) and (tb.WTA_4 is not null);
    end
  end

  for select tb.BIRD_DROP, count(tb.ID_RACE_ITEM), sum(tb.WTA_5)
    from TMP_BETS tb
    where (tb.EXEC_TIME = :EXEC_TIME) and (tb.BIRD_DROP is not null) and (tb.WTA_5 is not null)
    group by tb.BIRD_DROP
    into :BIRD_DROP, :BIRD_IN_DROP, :TOTAL_BET_VALUE
  do begin
    if (BIRD_IN_DROP > 1) then begin
      update TMP_BETS tb
        set tb.WTA_5 = (:TOTAL_BET_VALUE / :BIRD_IN_DROP)
        where (tb.BIRD_DROP = :BIRD_DROP) and (tb.WTA_5 is not null);
    end
  end

  /* Selecting and suspending the final calculation results */
  for select tb.ID_RACE_ITEM, tb.BELGIAN_SHOW_1, tb.BELGIAN_SHOW_2, tb.BELGIAN_SHOW_3,
    tb.BELGIAN_SHOW_4, tb.BELGIAN_SHOW_5, tb.BELGIAN_SHOW_6,  tb.BELGIAN_SHOW_7,
    tb.STANDARD_SHOW_1, tb.STANDARD_SHOW_2, tb.STANDARD_SHOW_3, tb.STANDARD_SHOW_4,
    tb.STANDARD_SHOW_5, tb.STANDARD_SHOW_6, tb.WTA_1, tb.WTA_2, tb.WTA_3, tb.WTA_4,
    tb.WTA_5, ri.ID_INVENTORY_ITEM
    from TMP_BETS tb
    join RACE_ITEM ri on ri.ID_RACE_ITEM = tb.ID_RACE_ITEM
    where tb.EXEC_TIME = :EXEC_TIME
    into :ID_RACE_ITEM, :BELGIAN_SHOW_1, :BELGIAN_SHOW_2, :BELGIAN_SHOW_3,
    :BELGIAN_SHOW_4, :BELGIAN_SHOW_5, :BELGIAN_SHOW_6,  :BELGIAN_SHOW_7,
    :STANDARD_SHOW_1, :STANDARD_SHOW_2, :STANDARD_SHOW_3, :STANDARD_SHOW_4,
    :STANDARD_SHOW_5, :STANDARD_SHOW_6, :WTA_1, :WTA_2, :WTA_3, :WTA_4,
    :WTA_5, :ID_EVENT_INVENTORY_ITEM
  do begin  
    TOTAL = coalesce(:BELGIAN_SHOW_1, 0)
            + coalesce(:BELGIAN_SHOW_2, 0)
            + coalesce(:BELGIAN_SHOW_3, 0)
            + coalesce(:BELGIAN_SHOW_4, 0)
            + coalesce(:BELGIAN_SHOW_5, 0)
            + coalesce(:BELGIAN_SHOW_6, 0)
            + coalesce(:BELGIAN_SHOW_7, 0)
            + coalesce(:STANDARD_SHOW_1, 0)
            + coalesce(:STANDARD_SHOW_2, 0)
            + coalesce(:STANDARD_SHOW_3, 0)
            + coalesce(:STANDARD_SHOW_4, 0)
            + coalesce(:STANDARD_SHOW_5, 0)
            + coalesce(:STANDARD_SHOW_6, 0)
            + coalesce(:WTA_1, 0)
            + coalesce(:WTA_2, 0)
            + coalesce(:WTA_3, 0)
            + coalesce(:WTA_4, 0)
            + coalesce(:WTA_5, 0);
    suspend;
  end

  /* Clearing the temporary table */
  delete from TMP_BETS tb where tb.EXEC_TIME = :EXEC_TIME;
end ^

ALTER PROCEDURE RACE_CLOSE (ID_RACE INTEGER)
RETURNS (ERR_CODE INTEGER,
ERR_TEXT VARCHAR(250) CHARACTER SET NONE)
AS 
declare variable ID_RACE_TYPE integer;
declare variable IS_CLOSED smallint;
declare variable ID_EVENT integer;
declare variable ID_RACE_ITEM integer;
declare variable IS_LOST smallint;
declare variable ARRIVAL_TIME timestamp;
declare variable ID_BIRD integer;
declare variable ID_EVENT_INVENTORY_ITEM integer;
begin
  ERR_CODE = 0;
  ERR_TEXT = '';
  select r.ID_RACE_TYPE, r.IS_CLOSED, r.ID_EVENT
    from RACE r
    where r.ID_RACE = :ID_RACE
    into :ID_RACE_TYPE, :IS_CLOSED, :ID_EVENT;
  if (IS_CLOSED = 1) then begin
    ERR_CODE = 1;
    ERR_TEXT = 'The selected race is already closed!';
  end

  -- mark not arrived birds as lost birds
  for select ri.ID_RACE_ITEM, ri.IS_LOST, rir.ARRIVAL_TIME, eii.ID_BIRD
    from RACE_ITEM ri
    join EVENT_INVENTORY_ITEM eii on eii.ID_EVENT_INVENTORY_ITEM = ri.ID_INVENTORY_ITEM
    left join RACE_ITEM_RESULT rir on rir.ID_RACE_ITEM = ri.ID_RACE_ITEM
    where ri.ID_RACE = :ID_RACE
    into :ID_RACE_ITEM, :IS_LOST, :ARRIVAL_TIME, :ID_BIRD
  do begin
    if ((IS_LOST = 0) and (ARRIVAL_TIME is null)) then begin
      execute procedure BIRD_LOST_STATUS_MODIFY(:ID_BIRD, 1, 'now', :ID_RACE);
      execute procedure RACE_ITEM_LOST_MODIFY(:ID_RACE_ITEM, 1, :ID_RACE);
    end else if ((IS_LOST = 1) and (ARRIVAL_TIME is not null)) then begin
      execute procedure BIRD_LOST_STATUS_MODIFY(:ID_BIRD, 0, 'now', :ID_RACE);
      execute procedure RACE_ITEM_LOST_MODIFY(:ID_RACE_ITEM, 0, :ID_RACE);
    end
  end

  -- set refund for bet birds not included in the final race
  if (ID_RACE_TYPE = 5 /* final race */) then begin
    for select eii.ID_EVENT_INVENTORY_ITEM
      from EVENT_INVENTORY_ITEM eii
      join EVENT_INVENTORY ei on ei.ID_EVENT_INVENTORY = eii.ID_EVENT_INVENTORY
      join BIRDS b on b.ID_BIRD = eii.ID_BIRD
      left join RACE_ITEM ri on ri.ID_INVENTORY_ITEM = eii.ID_EVENT_INVENTORY_ITEM and ri.ID_RACE = :ID_RACE
      where (ei.ID_EVENT = :ID_EVENT) and (ri.ID_RACE_ITEM is null) and (b.IS_LOST = 0)
      into :ID_EVENT_INVENTORY_ITEM
    do begin
      execute procedure BIRD_BETS_REFUND_SET(:ID_EVENT_INVENTORY_ITEM);
    end
  end

  -- set race closed
  update RACE r
    set r.IS_CLOSED = 1
    where r.ID_RACE = :ID_RACE;
end ^

ALTER PROCEDURE RACE_DROP_PRIZE_VALUE_SET_INT (ID_RACE INTEGER,
ID_RACE_TYPE INTEGER,
BIRD_DROP INTEGER,
PRIZE_VALUE NUMERIC(15, 4))
AS 
declare variable ID_RACE_ITEM integer;
begin
  if (ID_RACE_TYPE not in (5, 6, 7, 8)) then exit;

  for select ri.ID_RACE_ITEM
    from RACE_ITEM ri
    join RACE_ITEM_RESULT rir on rir.ID_RACE_ITEM = ri.ID_RACE_ITEM
    where ri.ID_RACE = :ID_RACE
      and rir.BIRD_DROP = :BIRD_DROP
      and ((:ID_RACE_TYPE is null)
        or ((:ID_RACE_TYPE = 5) and (rir.BIRD_POSITION is not null))
        or ((:ID_RACE_TYPE in (6, 7, 8)) and (rir.BIRD_POSITION_HOT_SPOT is not null)))
    into :ID_RACE_ITEM
  do begin
    update RACE_ITEM_RESULT rir
      set rir.PRIZE_VALUE = :PRIZE_VALUE
      where rir.ID_RACE_ITEM = :ID_RACE_ITEM;
  end
end ^

ALTER PROCEDURE RACE_IGNORE_BIRD_MODIFY (ID_IGNORE_BIRD INTEGER,
ID_RACE INTEGER,
ID_EVENT_INVENTORY_ITEM INTEGER,
NOTE VARCHAR(100) CHARACTER SET NONE,
PROCESS_HOT_SPOT_REFUND SMALLINT,
OPERATION VARCHAR(3) CHARACTER SET NONE)
RETURNS (NEW_ID_IGNORE_BIRD INTEGER)
AS 
declare variable ID_BIRD integer;
begin
  NEW_ID_IGNORE_BIRD = ID_IGNORE_BIRD;
  if (OPERATION = 'add') then begin
    NEW_ID_IGNORE_BIRD = gen_id(GEN_RACE_IGNORE_BIRD_ID, 1);
    insert into RACE_IGNORE_BIRD(ID_IGNORE_BIRD, ID_RACE, ID_EVENT_INVENTORY_ITEM, NOTE)
    values (:NEW_ID_IGNORE_BIRD, :ID_RACE, :ID_EVENT_INVENTORY_ITEM, :NOTE);

    select eii.ID_BIRD
      from EVENT_INVENTORY_ITEM eii
      where eii.ID_EVENT_INVENTORY_ITEM = :ID_EVENT_INVENTORY_ITEM
      into :ID_BIRD;
    if (ID_BIRD is not null) then begin
      update BIRDS b
        set b.NOTE = iif(b.NOTE <> '', b.NOTE || '; ' || :NOTE, :NOTE)
        where b.ID_BIRD = :ID_BIRD;
    end
    if (PROCESS_HOT_SPOT_REFUND <> 0) then begin
      update EVENT_INVENTORY_ITEM eii
        set eii.HOT_SPOT_REFUND = eii.HOT_SPOT_FEE_VALUE
        where eii.ID_EVENT_INVENTORY_ITEM = :ID_EVENT_INVENTORY_ITEM;
    end
  end else if (OPERATION = 'mod') then begin
    update RACE_IGNORE_BIRD
    set ID_RACE = :ID_RACE,
        ID_EVENT_INVENTORY_ITEM = :ID_EVENT_INVENTORY_ITEM,
        NOTE = :NOTE
    where ID_IGNORE_BIRD = :ID_IGNORE_BIRD;
  end else if (OPERATION = 'del') then begin  
    select rib.ID_EVENT_INVENTORY_ITEM
      from RACE_IGNORE_BIRD rib
      where rib.ID_IGNORE_BIRD = :ID_IGNORE_BIRD
      into :ID_EVENT_INVENTORY_ITEM;
    delete from RACE_IGNORE_BIRD
    where ID_IGNORE_BIRD = :ID_IGNORE_BIRD;
    if (PROCESS_HOT_SPOT_REFUND <> 0) then begin
      update EVENT_INVENTORY_ITEM eii
        set eii.HOT_SPOT_REFUND = null
        where eii.ID_EVENT_INVENTORY_ITEM = :ID_EVENT_INVENTORY_ITEM;
    end
  end
  suspend;
end ^

ALTER PROCEDURE RACE_ITEM_LOST_MODIFY (ID_RACE_ITEM INTEGER,
IS_LOST SMALLINT,
LOST_ID_RACE INTEGER)
AS 
declare variable BIRD_BAND VARCHAR(20);
declare variable BIRD_RFID VARCHAR(20);
begin
  if (IS_LOST = 0) then begin
    LOST_ID_RACE = null;
  end
  update RACE_ITEM ri
    set ri.IS_LOST = :IS_LOST/*,
        ri.LOST_ID_RACE = :LOST_ID_RACE*/
    where ri.ID_RACE_ITEM = :ID_RACE_ITEM;
end ^

ALTER PROCEDURE RACE_ITEM_MODIFY (ID_RACE_ITEM INTEGER,
ID_RACE INTEGER,
ID_INVENTORY_ITEM INTEGER,
ID_DIST_BASKET INTEGER,
IS_DIST_BASKETED SMALLINT,
ID_RACE_BASKET INTEGER,
IS_LOST SMALLINT,
LOST_ID_RACE INTEGER,
RACE_BASKET_TIME TIMESTAMP,
OPERATION VARCHAR(3) CHARACTER SET NONE)
RETURNS (NEW_ID_RACE_ITEM INTEGER,
ERR_CODE INTEGER,
ERR_TEXT VARCHAR(250) CHARACTER SET NONE)
AS 
declare variable BIRD_BAND VARCHAR(20);
declare variable BIRD_RFID VARCHAR(20);
begin
  ERR_CODE = 0;
  ERR_TEXT = '';

  NEW_ID_RACE_ITEM = ID_RACE_ITEM;
  if ((OPERATION = 'add') or (OPERATION = 'mod')) then begin
    if ((ID_DIST_BASKET is not null) and (not exists (select * from BASKET b where b.ID_BASKET = :ID_DIST_BASKET))) then begin
      ID_DIST_BASKET = null;
    end
    if ((ID_RACE_BASKET is not null) and (not exists (select * from BASKET b where b.ID_BASKET = :ID_RACE_BASKET))) then begin
      ID_RACE_BASKET = null;
      RACE_BASKET_TIME = null;
    end

    if (ID_RACE_BASKET is not null) then begin
      select b.BAND, b.RF_ID
        from EVENT_INVENTORY_ITEM eii
        join BIRDS b on b.ID_BIRD = eii.ID_BIRD
        where eii.ID_EVENT_INVENTORY_ITEM = :ID_INVENTORY_ITEM
        into :BIRD_BAND, :BIRD_RFID;
      if (IS_LOST = 1) then begin
        ERR_CODE = 1;
        ERR_TEXT = 'Bird with band ' || :BIRD_BAND || ' and EID ' || :BIRD_RFID || ' is lost and basketing is not allowed!';
      end
    end
  end

  if (OPERATION = 'add') then begin
    NEW_ID_RACE_ITEM = gen_id(GEN_RACE_ITEM_ID, 1);
    insert into RACE_ITEM(ID_RACE_ITEM, ID_RACE, ID_INVENTORY_ITEM, ID_DIST_BASKET, IS_DIST_BASKETED, ID_RACE_BASKET, IS_LOST, LOST_ID_RACE, RACE_BASKET_TIME)
    values (:NEW_ID_RACE_ITEM, :ID_RACE, :ID_INVENTORY_ITEM, :ID_DIST_BASKET, :IS_DIST_BASKETED, :ID_RACE_BASKET, :IS_LOST, :LOST_ID_RACE, :RACE_BASKET_TIME);
  end else if (OPERATION = 'mod') then begin
    update RACE_ITEM
    set ID_RACE = :ID_RACE,
        ID_INVENTORY_ITEM = :ID_INVENTORY_ITEM,
        ID_DIST_BASKET = :ID_DIST_BASKET,
        IS_DIST_BASKETED = :IS_DIST_BASKETED,
        ID_RACE_BASKET = :ID_RACE_BASKET,
        IS_LOST = :IS_LOST,
        LOST_ID_RACE = :LOST_ID_RACE,
        RACE_BASKET_TIME = :RACE_BASKET_TIME
    where (ID_RACE_ITEM = :ID_RACE_ITEM);
  end else if (OPERATION = 'del') then begin
    delete from RACE_ITEM
    where (ID_RACE_ITEM = :ID_RACE_ITEM);
  end
  suspend;
end ^

ALTER PROCEDURE RACE_ITEM_PRIZE_VALUE_CALC (ID_RACE_ITEM INTEGER)
AS 
declare variable ID_EVENT integer;
declare variable ID_RACE integer;
declare variable ID_RACE_TYPE integer;
declare variable BIRD_DROP integer;
declare variable BIRD_POSITION integer;
declare variable BIRD_POSITION_HOT_SPOT integer;
declare variable PRIZE_VALUE numeric(15,4);
declare variable DROP_PRIZE_VALUE numeric(15,4);
declare variable DROP_BIRD_COUNT integer;
declare variable ID_FINAL_PRIZE_SCHEME integer;
declare variable ID_HS1_PRIZE_SCHEME integer;
declare variable ID_HS2_PRIZE_SCHEME integer;
declare variable ID_HS3_PRIZE_SCHEME integer;
declare variable ID_HS_AVG_PRIZE_SCHEME integer;
begin
  select r.ID_RACE,
         r.ID_EVENT,
         r.ID_RACE_TYPE,
         e.ID_FINAL_PRIZE_SCHEME,
         e.ID_HOT_SPOT1_PRIZE_SCHEME,
         e.ID_HOT_SPOT2_PRIZE_SCHEME,
         e.ID_HOT_SPOT3_PRIZE_SCHEME,
         rir.BIRD_POSITION,
         rir.BIRD_POSITION_HOT_SPOT,
         rir.BIRD_DROP
    from RACE_ITEM_RESULT rir
    join RACE_ITEM ri on ri.ID_RACE_ITEM = rir.ID_RACE_ITEM
    join RACE r on r.ID_RACE = ri.ID_RACE
    join EVENTS e on e.ID_EVENT = r.ID_EVENT
    where rir.ID_RACE_ITEM = :ID_RACE_ITEM
    into :ID_RACE,
         :ID_EVENT,
         :ID_RACE_TYPE,
         :ID_FINAL_PRIZE_SCHEME,
         :ID_HS1_PRIZE_SCHEME,
         :ID_HS2_PRIZE_SCHEME,
         :ID_HS3_PRIZE_SCHEME,
         :BIRD_POSITION,
         :BIRD_POSITION_HOT_SPOT,
         :BIRD_DROP;

  if (ID_RACE_TYPE not in (5, 6, 7, 8)) then exit; -- only hot spot and final races can have a prize

  execute procedure RACE_ITEM_PRIZE_VALUE_CALC_INT(:ID_EVENT, :ID_RACE, :ID_RACE_TYPE, :ID_RACE_ITEM, :BIRD_DROP,
    :BIRD_POSITION, :BIRD_POSITION_HOT_SPOT, :ID_FINAL_PRIZE_SCHEME, :ID_HS1_PRIZE_SCHEME, :ID_HS2_PRIZE_SCHEME, :ID_HS3_PRIZE_SCHEME);
end ^

ALTER PROCEDURE RACE_ITEM_PRIZE_VALUE_CALC_INT (ID_EVENT INTEGER,
ID_RACE INTEGER,
ID_RACE_TYPE INTEGER,
ID_RACE_ITEM INTEGER,
BIRD_DROP INTEGER,
BIRD_POSITION INTEGER,
BIRD_POSITION_HOT_SPOT INTEGER,
ID_FINAL_PRIZE_SCHEME INTEGER,
ID_HS1_PRIZE_SCHEME INTEGER,
ID_HS2_PRIZE_SCHEME INTEGER,
ID_HS3_PRIZE_SCHEME INTEGER)
AS 
declare variable PRIZE_VALUE numeric(15,4);
declare variable DROP_PRIZE_VALUE numeric(15,4);
declare variable DROP_BIRD_COUNT integer;
begin
  if (ID_RACE_TYPE not in (5, 6, 7, 8)) then exit; -- only hot spot and final races can have a prize

  PRIZE_VALUE = null;
  if (ID_RACE_TYPE = 5 /* final race */) then begin
    if (BIRD_DROP is null) then begin
      if (BIRD_POSITION is not null) then begin
        execute procedure GET_PRIZE_VALUE(:ID_FINAL_PRIZE_SCHEME, :ID_EVENT, :ID_RACE_TYPE, :BIRD_POSITION, :BIRD_POSITION)
        returning_values :PRIZE_VALUE;
      end
      update RACE_ITEM_RESULT rir
        set rir.PRIZE_VALUE = :PRIZE_VALUE
        where rir.ID_RACE_ITEM = :ID_RACE_ITEM;
    end else begin
      -- if the birds are in drop then the prize will be separated equally
      DROP_PRIZE_VALUE = 0;
      DROP_BIRD_COUNT = 0;
      for select rir.BIRD_POSITION
        from RACE_ITEM ri
        join RACE_ITEM_RESULT rir on rir.ID_RACE_ITEM = ri.ID_RACE_ITEM
        where ri.ID_RACE = :ID_RACE
          and rir.BIRD_DROP = :BIRD_DROP
          and (rir.BIRD_POSITION is not null)
        order by rir.BIRD_POSITION
        into :BIRD_POSITION
      do begin
        execute procedure GET_PRIZE_VALUE(ID_FINAL_PRIZE_SCHEME, :ID_EVENT, :ID_RACE_TYPE, :BIRD_POSITION, :BIRD_POSITION)
        returning_values :PRIZE_VALUE;
        DROP_PRIZE_VALUE = DROP_PRIZE_VALUE + coalesce(PRIZE_VALUE, 0);
        DROP_BIRD_COUNT = DROP_BIRD_COUNT + 1;
      end
      if (DROP_BIRD_COUNT > 0) then begin
        if ((DROP_PRIZE_VALUE / DROP_BIRD_COUNT) > 0) then begin
          PRIZE_VALUE = (DROP_PRIZE_VALUE / DROP_BIRD_COUNT);
        end
        -- first clear prize all values by drop
        execute procedure RACE_DROP_PRIZE_VALUE_SET_INT(:ID_RACE, null, :BIRD_DROP, null);
        if (PRIZE_VALUE is not null) then begin
          -- set prizes only for birds with position
          execute procedure RACE_DROP_PRIZE_VALUE_SET_INT(:ID_RACE, 5 /* final race */, :BIRD_DROP, :PRIZE_VALUE);
        end
      end
    end
  end else /* hot spot races */ begin
    -- first clear hot spot prize
    update RACE_ITEM_RESULT rir
      set rir.PRIZE_VALUE = null
      where rir.ID_RACE_ITEM = :ID_RACE_ITEM;

    if (BIRD_POSITION_HOT_SPOT is not null) then begin
      if (ID_RACE_TYPE = 6) then begin
        execute procedure GET_PRIZE_VALUE(:ID_HS1_PRIZE_SCHEME, :ID_EVENT, :ID_RACE_TYPE, :BIRD_POSITION_HOT_SPOT, :BIRD_POSITION_HOT_SPOT)
        returning_values :PRIZE_VALUE;
      end else if (ID_RACE_TYPE = 7) then begin
        execute procedure GET_PRIZE_VALUE(:ID_HS2_PRIZE_SCHEME, :ID_EVENT, :ID_RACE_TYPE, :BIRD_POSITION_HOT_SPOT, :BIRD_POSITION_HOT_SPOT)
        returning_values :PRIZE_VALUE;
      end else if (ID_RACE_TYPE = 8) then begin
        execute procedure GET_PRIZE_VALUE(:ID_HS3_PRIZE_SCHEME, :ID_EVENT, :ID_RACE_TYPE, :BIRD_POSITION_HOT_SPOT, :BIRD_POSITION_HOT_SPOT)
        returning_values :PRIZE_VALUE;
      end
      update RACE_ITEM_RESULT rir
        set rir.PRIZE_VALUE = :PRIZE_VALUE
        where rir.ID_RACE_ITEM = :ID_RACE_ITEM;
    end
  end
end ^

ALTER PROCEDURE RACE_ITEM_RESULT_ADD_ID (ID_BIRD VARCHAR(20) CHARACTER SET NONE,
ARRIVAL_TIME TIMESTAMP,
BIRD_DROP INTEGER,
ID_RACE INTEGER)
RETURNS (ID_RACE_ITEM INTEGER,
RES_CODE INTEGER,
RES_TEXT VARCHAR(250) CHARACTER SET NONE,
ERR_CODE INTEGER,
ERR_TEXT VARCHAR(250) CHARACTER SET NONE)
AS 
declare variable BAND VARCHAR(20);
declare variable RF_ID VARCHAR(20);
declare variable IS_LOST_BIRD SMALLINT;
declare variable ID_LOST_RACE INTEGER;
declare variable RETURN_FROM_RACE INTEGER;
declare variable ID_EVENT integer;
declare variable ID_EVENT_INVENTORY_ITEM integer;
begin
  ERR_CODE = 0;
  ERR_TEXT = '';
  RES_CODE = 0;
  RES_TEXT = '';

  select ri.ID_RACE_ITEM, ri.IS_LOST, ri.LOST_ID_RACE, b.BAND, b.RF_ID
    from RACE r
    join RACE_ITEM ri on ri.ID_RACE = r.ID_RACE
    join EVENT_INVENTORY_ITEM eii on eii.ID_EVENT_INVENTORY_ITEM = ri.ID_INVENTORY_ITEM
    join BIRDS b on b.ID_BIRD = eii.ID_BIRD
    where (ri.ID_RACE = :ID_RACE) and (eii.ID_BIRD = :ID_BIRD)
    into :ID_RACE_ITEM, :IS_LOST_BIRD, :ID_LOST_RACE, :BAND, :RF_ID;

  if (ID_RACE_ITEM is null) then begin
    -- check if this bird is lost from the race event
    select r.ID_EVENT
      from RACE r
      where r.ID_RACE = :ID_RACE
      into :ID_EVENT;

    select eii.ID_EVENT_INVENTORY_ITEM, b.IS_LOST, b.LOST_ID_RACE, b.BAND, b.RF_ID
      from EVENT_INVENTORY ei
      join EVENT_INVENTORY_ITEM eii on eii.ID_EVENT_INVENTORY = ei.ID_EVENT_INVENTORY
      join BIRDS b on b.ID_BIRD = eii.ID_BIRD
      where ei.ID_EVENT = :ID_EVENT and eii.ID_BIRD = :ID_BIRD and b.IS_LOST = 1
      into :ID_EVENT_INVENTORY_ITEM, :IS_LOST_BIRD, :ID_LOST_RACE, :BAND, :RF_ID;
    if (ID_EVENT_INVENTORY_ITEM is not null) then begin
      execute procedure RACE_ITEM_MODIFY(null, :ID_RACE, :ID_EVENT_INVENTORY_ITEM, null, 0, null, :IS_LOST_BIRD, :ID_LOST_RACE, null, 'add')
      returning_values :ID_RACE_ITEM, :ERR_CODE, :ERR_TEXT;
      if (ERR_CODE <> 0) then begin
        exit;
      end
    end else begin
      RES_CODE = 1000;
      RES_TEXT = 'Bird with band not found in the race!';
      exit;
    end
  end

  if (exists (select rir.ID_RACE_ITEM from RACE_ITEM_RESULT rir where rir.ID_RACE_ITEM = :ID_RACE_ITEM)) then begin
    RES_CODE = 2000;
    RES_TEXT = 'Bird with band ' || :BAND || ' and EID ' || :RF_ID || ' already arrived!';
    exit;
  end

  RETURN_FROM_RACE = null;
  if (IS_LOST_BIRD = 1) then begin
    BIRD_DROP = null;
    RETURN_FROM_RACE = ID_LOST_RACE;
  end
  if (ARRIVAL_TIME is null) then begin
    ARRIVAL_TIME = 'now';
  end
  execute procedure RACE_ITEM_RESULT_MODIFY(:ID_RACE_ITEM, :ARRIVAL_TIME, :BIRD_DROP, 'set')
  returning_values  :ERR_CODE, :ERR_TEXT;

  post_event 'BIRD_ADD';
end ^

ALTER PROCEDURE RACE_ITEM_RESULT_ADD_RFID (RF_ID VARCHAR(20) CHARACTER SET NONE,
ARRIVAL_TIME TIMESTAMP,
BIRD_DROP INTEGER,
ID_RACE INTEGER)
RETURNS (ID_RACE_ITEM INTEGER,
ID_BIRD INTEGER,
OUT_ID_RACE INTEGER,
RES_CODE INTEGER,
RES_TEXT VARCHAR(250) CHARACTER SET NONE,
ERR_CODE INTEGER,
ERR_TEXT VARCHAR(250) CHARACTER SET NONE)
AS 
declare variable ID_EVENT integer;
declare variable ID_RACE_TYPE integer;
begin
  ERR_CODE = 0;
  ERR_TEXT = '';
  RES_CODE = 0;
  RES_TEXT = '';
  OUT_ID_RACE = null;

  if (ARRIVAL_TIME is null) then begin
    ARRIVAL_TIME = 'now';
  end

  select b.ID_BIRD
    from BIRDS b
    where b.RF_ID = :RF_ID
    into :ID_BIRD;

  if (ID_BIRD is null) then begin
    RES_CODE = 3000;
    RES_TEXT = 'Bird with EID ' || :RF_ID || ' not exist in the system!';
    execute procedure RACE_PHANTOM_BIRD_MODIFY(null, :ID_RACE, null, :RF_ID, :ARRIVAL_TIME, null, 'add');
    exit;
  end

  select r.ID_RACE_TYPE
    from RACE r
    where r.ID_RACE = :ID_RACE
    into :ID_RACE_TYPE;

  execute procedure RACE_ITEM_RESULT_ADD_ID(:ID_BIRD, :ARRIVAL_TIME, :BIRD_DROP, :ID_RACE)
  returning_values (:ID_RACE_ITEM, :RES_CODE, :RES_TEXT, :ERR_CODE, :ERR_TEXT);

  if (RES_CODE = 1000) then begin
    select ei.ID_EVENT
      from EVENT_INVENTORY_ITEM eii
      join EVENT_INVENTORY ei on ei.ID_EVENT_INVENTORY = eii.ID_EVENT_INVENTORY
      where eii.ID_BIRD = :ID_BIRD
      into :ID_EVENT;
    execute procedure RACE_PHANTOM_BIRD_MODIFY(null, :ID_RACE, :ID_BIRD, :RF_ID, :ARRIVAL_TIME, :ID_EVENT, 'add');

    if (ID_RACE_TYPE = 5 /* final race */) then begin
      -- bird not found in the race, try to found another race
      select r.ID_RACE
        from RACE r
        join EVENTS e on e.ID_EVENT = r.ID_EVENT
        join RACE_ITEM ri on ri.ID_RACE = r.ID_RACE
        join EVENT_INVENTORY_ITEM eii on eii.ID_EVENT_INVENTORY_ITEM = ri.ID_INVENTORY_ITEM
        where (r.ID_RACE_TYPE = 5 /* final race */) and (eii.ID_BIRD = :ID_BIRD)
        into :OUT_ID_RACE;
    end
  end
end ^

ALTER PROCEDURE RACE_ITEM_RESULT_HS_POS_CALC (ID_RACE INTEGER)
AS 
declare variable TMP_BIRD_POSITION integer;
declare variable ID_RACE_ITEM integer;
begin
  -- clear hot spot position first
  for select rir.ID_RACE_ITEM
    from RACE_ITEM_RESULT rir
    join RACE_ITEM ri on ri.ID_RACE_ITEM = rir.ID_RACE_ITEM
    where ri.ID_RACE = :ID_RACE
    into :ID_RACE_ITEM
  do begin  
    update RACE_ITEM_RESULT rir
      set rir.BIRD_POSITION_HOT_SPOT = null
      where rir.ID_RACE_ITEM = :ID_RACE_ITEM;
  end

  TMP_BIRD_POSITION = 1;
  for select rir.ID_RACE_ITEM
    from RACE_ITEM_RESULT rir
    join RACE_ITEM ri on ri.ID_RACE_ITEM = rir.ID_RACE_ITEM
    join RACE r on r.ID_RACE = ri.ID_RACE
    join EVENT_INVENTORY_ITEM eii on eii.ID_EVENT_INVENTORY_ITEM = ri.ID_INVENTORY_ITEM
    where ri.ID_RACE = :ID_RACE and (ri.IS_LOST = 0) and ((r.ID_RACE_TYPE in (5, 6, 7, 8) /* final race and hot spot races */) and (coalesce(eii.HOT_SPOT_FEE_VALUE, 0) > 0))
    order by rir.ARRIVAL_TIME
    into :ID_RACE_ITEM
  do begin
    update RACE_ITEM_RESULT rir
      set rir.BIRD_POSITION_HOT_SPOT = :TMP_BIRD_POSITION
      where rir.ID_RACE_ITEM = :ID_RACE_ITEM;
    TMP_BIRD_POSITION = TMP_BIRD_POSITION + 1;
  end
end ^

ALTER PROCEDURE RACE_ITEM_RESULT_MODIFY (ID_RACE_ITEM INTEGER,
ARRIVAL_TIME TIMESTAMP,
BIRD_DROP INTEGER,
OPERATION VARCHAR(3) CHARACTER SET NONE)
RETURNS (ERR_CODE INTEGER,
ERR_TEXT VARCHAR(250) CHARACTER SET NONE)
AS 
declare variable ID_RACE integer;
declare variable ID_RACE_TYPE integer;
declare variable IS_LOST smallint;
declare variable TMP_ARRIVAL_TIME timestamp;
declare variable OLD_BIRD_DROP integer;
declare variable TMP_BIRD_POSITION integer;
declare variable TMP_BIRD_POSITION_HOT_SPOT integer;
declare variable NEW_BIRD_POSITION integer;
declare variable NEW_BIRD_POSITION_HOT_SPOT integer;
declare variable IS_ENTRY_FEE_PAID smallint;
declare variable IS_HOT_SPOT_FEE_PAID smallint;
declare variable HOT_SPOT_FEE_VALUE numeric(15, 4);

begin
  select ri.ID_RACE, ri.IS_LOST, r.ID_RACE_TYPE
    from RACE_ITEM ri
    join RACE r on r.ID_RACE = ri.ID_RACE
    where ri.ID_RACE_ITEM = :ID_RACE_ITEM
    into :ID_RACE, :IS_LOST, :ID_RACE_TYPE;

  -- bird drop is not allowed for lost birds
  if (IS_LOST = 1) then begin
    BIRD_DROP = null;
  end

  if (OPERATION = 'set') then begin
    select rir.BIRD_DROP, rir.BIRD_POSITION, rir.BIRD_POSITION_HOT_SPOT, rir.ARRIVAL_TIME
      from RACE_ITEM_RESULT rir
      where rir.ID_RACE_ITEM = :ID_RACE_ITEM
      into :OLD_BIRD_DROP, :TMP_BIRD_POSITION, :TMP_BIRD_POSITION_HOT_SPOT, :TMP_ARRIVAL_TIME;

    if (TMP_ARRIVAL_TIME is not null) then begin
      update RACE_ITEM_RESULT
      set ARRIVAL_TIME = :ARRIVAL_TIME,
          BIRD_DROP = :BIRD_DROP
      where ID_RACE_ITEM = :ID_RACE_ITEM;

      if (IS_LOST = 0) then begin
        -- only non lost bird can have a rank and prize
        -- position reclac is necessary only if the arrival time is different
        if (TMP_ARRIVAL_TIME is distinct from ARRIVAL_TIME) then begin
          execute procedure RACE_ITEM_RESULT_POSITION_CALC(:ID_RACE, :ID_RACE_TYPE);
          if (ID_RACE_TYPE in (5, 6, 7, 8)) then begin
            execute procedure RACE_ITEM_RESULT_HS_POS_CALC(:ID_RACE);
          end
        end

        if (ID_RACE_TYPE in (5, 6, 7, 8 /* hot spots and final race */ )) then begin
          -- getting the new bird positions
          select rir.BIRD_POSITION, rir.BIRD_POSITION_HOT_SPOT
            from RACE_ITEM_RESULT rir
            where rir.ID_RACE_ITEM = :ID_RACE_ITEM
            into :NEW_BIRD_POSITION, :NEW_BIRD_POSITION_HOT_SPOT;

          -- if positions are changed then prize calculation for all birds is required
          -- prizes are allowed for hot spots and final race
          if (((ID_RACE_TYPE = 5) and (TMP_BIRD_POSITION is distinct from NEW_BIRD_POSITION))
            or ((ID_RACE_TYPE in (6, 7, 8)) and (TMP_BIRD_POSITION_HOT_SPOT is distinct from NEW_BIRD_POSITION_HOT_SPOT))) then begin
            execute procedure RACE_PRIZE_VALUE_CALC(:ID_RACE)
            returning_values  :ERR_CODE, :ERR_TEXT;
          end else if (ID_RACE_TYPE in (5 /* final race */ )) then begin
            if ((OLD_BIRD_DROP is not null) and (BIRD_DROP is null)) then begin
              execute procedure RACE_ITEM_PRIZE_VALUE_CALC(:ID_RACE_ITEM);
              execute procedure RACE_PRIZE_VALUE_CALC(:ID_RACE, :OLD_BIRD_DROP)
              returning_values  :ERR_CODE, :ERR_TEXT;
            end else if ((OLD_BIRD_DROP is null) and (BIRD_DROP is not null)) then begin
              execute procedure RACE_ITEM_PRIZE_VALUE_CALC(:ID_RACE_ITEM);
            end else if ((OLD_BIRD_DROP is not null) and (BIRD_DROP is not null) and (OLD_BIRD_DROP <> BIRD_DROP)) then begin
              execute procedure RACE_ITEM_PRIZE_VALUE_CALC(:ID_RACE_ITEM);
              execute procedure RACE_PRIZE_VALUE_CALC(:ID_RACE, :OLD_BIRD_DROP)
              returning_values  :ERR_CODE, :ERR_TEXT;
            end
          end
        end
      end
    end else begin
      -- check if this bird is paid for (entry fee and hot spot fee)
      -- if it is not in the finala race will be disqualificated
      select eii.ENTRY_FEE_PAID, eii.HOT_SPOT_FEE_VALUE
        from RACE_ITEM ri
        join EVENT_INVENTORY_ITEM eii on eii.ID_EVENT_INVENTORY_ITEM = ri.ID_INVENTORY_ITEM
        join EVENT_INVENTORY ei on ei.ID_EVENT_INVENTORY = eii.ID_EVENT_INVENTORY
        join RACE r on r.ID_RACE = ri.ID_RACE
        where ri.ID_RACE_ITEM = :ID_RACE_ITEM
        into :IS_ENTRY_FEE_PAID, :HOT_SPOT_FEE_VALUE;

      IS_HOT_SPOT_FEE_PAID = 0;
      if (HOT_SPOT_FEE_VALUE > 0) then begin
        IS_HOT_SPOT_FEE_PAID = 1;
      end

      TMP_BIRD_POSITION = null;
      TMP_BIRD_POSITION_HOT_SPOT = null;
      TMP_ARRIVAL_TIME = null;

      if (IS_LOST = 0) then begin
        select max(rir.ARRIVAL_TIME), max(rir.BIRD_POSITION), max(rir.BIRD_POSITION_HOT_SPOT)
          from RACE_ITEM_RESULT rir
          join RACE_ITEM ri on ri.ID_RACE_ITEM = rir.ID_RACE_ITEM
          where ri.ID_RACE = :ID_RACE
          into :TMP_ARRIVAL_TIME, :TMP_BIRD_POSITION, :TMP_BIRD_POSITION_HOT_SPOT;

        if ((TMP_ARRIVAL_TIME is null) or (TMP_ARRIVAL_TIME <= ARRIVAL_TIME)) then begin
          if ((ID_RACE_TYPE <> 5) or (IS_ENTRY_FEE_PAID <> 0)) then begin
            TMP_BIRD_POSITION = coalesce(TMP_BIRD_POSITION, 0) + 1;
          end else begin
            TMP_BIRD_POSITION = null;
          end
          if ((ID_RACE_TYPE in (5, 6, 7, 8)) and (IS_HOT_SPOT_FEE_PAID <> 0)) then begin
            TMP_BIRD_POSITION_HOT_SPOT = coalesce(TMP_BIRD_POSITION_HOT_SPOT, 0) + 1;
          end else begin
            TMP_BIRD_POSITION_HOT_SPOT = null;
          end
        end else begin
          TMP_BIRD_POSITION = null;
          TMP_BIRD_POSITION_HOT_SPOT = null;
        end
      end

      insert into RACE_ITEM_RESULT(ID_RACE_ITEM, BIRD_POSITION, BIRD_POSITION_HOT_SPOT, ARRIVAL_TIME, BIRD_DROP, PRIZE_VALUE)
      values (:ID_RACE_ITEM, :TMP_BIRD_POSITION, :TMP_BIRD_POSITION_HOT_SPOT, :ARRIVAL_TIME, :BIRD_DROP, null);

      if (IS_LOST = 0) then begin
        -- only birds started and arrived in same race can have race position
        if (TMP_BIRD_POSITION is null) then begin
          -- recalculating is required only if the previous statement can't find bird position
          execute procedure RACE_ITEM_RESULT_POSITION_CALC(:ID_RACE, :ID_RACE_TYPE);
        end
        -- only birds started and arrived in same race and are paid can have race hot spot position
        if ((ID_RACE_TYPE in (6, 7, 8)) and (TMP_BIRD_POSITION_HOT_SPOT is null)) then begin
          -- recalculating is required only if the previous statement can't find bird position
          execute procedure RACE_ITEM_RESULT_HS_POS_CALC(:ID_RACE);
        end

        if (ID_RACE_TYPE in (5, 6, 7, 8)) then begin
          -- calc prize only for hot spot races and final race
          if (TMP_BIRD_POSITION is not null) then begin
            -- TMP_BIRD_POSITION is not null then no position recalculating so it is possible to set prize for single item
            execute procedure RACE_ITEM_PRIZE_VALUE_CALC(:ID_RACE_ITEM);
          end else begin
            -- position is recalculated so it is necessary to recalc all items prizes
            execute procedure RACE_PRIZE_VALUE_CALC(:ID_RACE)
            returning_values  :ERR_CODE, :ERR_TEXT;
          end
        end
      end

      -- set race verified bird status
      update BIRDS b
        set b.IS_RACE_VERIFIED = 1
        where b.ID_BIRD = (select eii.ID_BIRD
                            from RACE_ITEM ri
                            join EVENT_INVENTORY_ITEM eii on eii.ID_EVENT_INVENTORY_ITEM = ri.ID_INVENTORY_ITEM
                            where ri.ID_RACE_ITEM = :ID_RACE_ITEM);
    end
  end else if (OPERATION = 'del') then begin
    delete from RACE_ITEM_RESULT
    where ID_RACE_ITEM = :ID_RACE_ITEM;

    -- recalculating positions
    execute procedure RACE_ITEM_RESULT_POSITION_CALC(:ID_RACE, :ID_RACE_TYPE);
    if (ID_RACE_TYPE in (6, 7, 8)) then begin
      execute procedure RACE_ITEM_RESULT_HS_POS_CALC(:ID_RACE);
    end

   -- price calculation for every deleted item slow down the work in case
   -- there are many items for deleting
   -- DON'T forget to recalc prizes after all items deleting
   /* if (ID_RACE_TYPE in (5, 6, 7, 8)) then begin
      -- calc prize only for hot spot races and final race
      execute procedure RACE_PRIZE_VALUE_CALC(:ID_RACE)
      returning_values  :ERR_CODE, :ERR_TEXT;
    end */
  end
end ^

ALTER PROCEDURE RACE_ITEM_RESULT_POSITION_CALC (ID_RACE INTEGER,
ID_RACE_TYPE INTEGER)
AS 
declare variable TMP_BIRD_POSITION integer;
declare variable ID_RACE_ITEM integer;
declare variable ENTRY_FEE_PAID smallint;
begin
  -- clear bird position first
  for select rir.ID_RACE_ITEM
    from RACE_ITEM_RESULT rir
    join RACE_ITEM ri on ri.ID_RACE_ITEM = rir.ID_RACE_ITEM
    where ri.ID_RACE = :ID_RACE
    into :ID_RACE_ITEM
  do begin
    update RACE_ITEM_RESULT rir
      set rir.BIRD_POSITION = null
      where rir.ID_RACE_ITEM = :ID_RACE_ITEM;
  end

  TMP_BIRD_POSITION = 1;
  for select rir.ID_RACE_ITEM, eii.ENTRY_FEE_PAID
    from RACE_ITEM_RESULT rir
    join RACE_ITEM ri on ri.ID_RACE_ITEM = rir.ID_RACE_ITEM
    join RACE r on r.ID_RACE = ri.ID_RACE
    join EVENT_INVENTORY_ITEM eii on eii.ID_EVENT_INVENTORY_ITEM = ri.ID_INVENTORY_ITEM
    where ri.ID_RACE = :ID_RACE and ri.IS_LOST = 0
    order by rir.ARRIVAL_TIME
    into :ID_RACE_ITEM, :ENTRY_FEE_PAID
  do begin
    if ((ID_RACE_TYPE <> 5 /* final race */) or (ENTRY_FEE_PAID = 1)) then begin
      update RACE_ITEM_RESULT rir
        set rir.BIRD_POSITION = :TMP_BIRD_POSITION
        where rir.ID_RACE_ITEM = :ID_RACE_ITEM;
      TMP_BIRD_POSITION = TMP_BIRD_POSITION + 1;
    end
  end
end ^

ALTER PROCEDURE RACE_ITEM_SCAN_ADD_RFID (ID_RACE INTEGER,
RF_ID VARCHAR(20) CHARACTER SET NONE)
RETURNS (ID_RACE_ITEM INTEGER,
ERR_CODE INTEGER,
ERR_TEXT VARCHAR(250) CHARACTER SET NONE)
AS 
begin
  ERR_CODE = 0;
  ERR_TEXT = '';
  select ri.ID_RACE_ITEM
    from BIRDS b
    join EVENT_INVENTORY_ITEM eii on eii.ID_BIRD = b.ID_BIRD
    join RACE_ITEM ri on ri.ID_INVENTORY_ITEM = eii.ID_EVENT_INVENTORY_ITEM
    where ri.ID_RACE = :ID_RACE and b.RF_ID = :RF_ID
    into :ID_RACE_ITEM;
  if (ID_RACE_ITEM is null) then begin
    ERR_CODE = 1;
    ERR_TEXT = 'Bird with EID ' || :RF_ID || ' not found in the race!';
    exit;
  end
  execute procedure RACE_ITEM_SCAN_MODIFY(:ID_RACE, :ID_RACE_ITEM, 'add');
end ^

ALTER PROCEDURE RACE_ITEM_SCAN_MODIFY (ID_RACE INTEGER,
ID_RACE_ITEM INTEGER,
OPERATION VARCHAR(5) CHARACTER SET NONE)
AS 
declare variable SCAN_POS integer;
begin
  if (OPERATION = 'add') then begin
    if (not exists (select ris.ID_RACE
                      from RACE_ITEM_SCAN ris
                      where ris.ID_RACE = :ID_RACE and ris.ID_RACE_ITEM = :ID_RACE_ITEM)) then begin

      select max(ris.SCAN_POS)
        from RACE_ITEM_SCAN ris
        where ris.ID_RACE = :ID_RACE
        into :SCAN_POS;
      insert into RACE_ITEM_SCAN
        (ID_RACE, ID_RACE_ITEM, SCAN_POS)
      values
        (:ID_RACE, :ID_RACE_ITEM, coalesce(:SCAN_POS, 0) + 1);
    end
  end else if (OPERATION = 'clear') then begin
    delete from RACE_ITEM_SCAN
    where ID_RACE = :ID_RACE;
  end
end ^

ALTER PROCEDURE RACE_MODIFY (ID_RACE INTEGER,
RACE_NUMBER INTEGER,
ID_EVENT INTEGER,
LOCATION VARCHAR(50) CHARACTER SET NONE,
DESCRIPTION VARCHAR(250) CHARACTER SET NONE,
DISTANCE INTEGER,
START_TIME TIMESTAMP,
END_TIME TIMESTAMP,
SUNRISE TIME,
SUNSET TIME,
WEATHER VARCHAR(100) CHARACTER SET NONE,
WIND VARCHAR(100) CHARACTER SET NONE,
TEMPERATURE VARCHAR(100) CHARACTER SET NONE,
ARRIVAL_WEATHER VARCHAR(100) CHARACTER SET NONE,
ARRIVAL_WIND VARCHAR(100) CHARACTER SET NONE,
ARRIVAL_TEMPERATURE VARCHAR(100) CHARACTER SET NONE,
ID_RACE_TYPE INTEGER,
OPERATION VARCHAR(3) CHARACTER SET NONE)
RETURNS (NEW_ID_RACE INTEGER,
ERR_CODE INTEGER,
ERR_TEXT VARCHAR(250) CHARACTER SET NONE)
AS 
declare variable RACE_COUNT integer;
declare variable EVENT_NAME varchar(50);
declare variable RACE_TYPE_NAME varchar(50);
begin
  NEW_ID_RACE = ID_RACE;
  ERR_CODE = 0;
  ERR_TEXT = '';
  if (((OPERATION = 'add') or (OPERATION = 'mod')) and (ID_RACE_TYPE in (5, 6, 7, 8))) then begin
    select e.EVENT_NAME, rt.TYPE_NAME, count(r.ID_RACE)
      from RACE r
      join EVENTS e on r.ID_EVENT = e.ID_EVENT
      join RACE_TYPE rt on rt.ID_RACE_TYPE = r.ID_RACE_TYPE
      where (r.ID_EVENT = :ID_EVENT)
        and (r.ID_RACE <> coalesce(:ID_RACE, 0))
        and (r.ID_RACE_TYPE = :ID_RACE_TYPE)
      group by e.EVENT_NAME, rt.TYPE_NAME
      into :EVENT_NAME, :RACE_TYPE_NAME, :RACE_COUNT;
    if (RACE_COUNT > 0) then begin
      ERR_CODE = 1;
      ERR_TEXT = 'Only one race of type ' || :RACE_TYPE_NAME || ' is allowed for event ' || :EVENT_NAME || '!';
      exit;
    end
  end

  /*
  Unmark if this check is necessary

  if ((OPERATION = 'add') and (OPERATION = 'mod')) then begin
    if (exists (select r.ID_RACE
      from RACE r
      where r.ID_EVENT = :ID_EVENT and r.ID_RACE <> :ID_RACE and r.RACE_NUMBER = :RACE_NUMBER)) then begin
      ERR_CODE = 1;
      ERR_TEXT = 'Event ' || EVENT_NAME || ' already have race with number '|| RACE_NUMBER ||'!';
    end
  end
  */
  if (OPERATION = 'add') then begin
    NEW_ID_RACE = gen_id(GEN_RACE_ID, 1);
    if (NEW_ID_RACE in (9999, 8888, 7777)) then begin
      -- skip reserved for lost codes numbers
      NEW_ID_RACE = gen_id(GEN_RACE_ID, 1);
    end
    insert into RACE(ID_RACE, RACE_NUMBER, ID_EVENT, LOCATION, DESCRIPTION, DISTANCE,
        START_TIME, END_TIME, SUNRISE, SUNSET, WEATHER, WIND, TEMPERATURE, ID_RACE_TYPE,
        ARRIVAL_WEATHER, ARRIVAL_WIND, ARRIVAL_TEMPERATURE)
    values (:NEW_ID_RACE, :RACE_NUMBER, :ID_EVENT, :LOCATION, :DESCRIPTION, :DISTANCE,
        :START_TIME, :END_TIME, :SUNRISE, :SUNSET, :WEATHER, :WIND, :TEMPERATURE, :ID_RACE_TYPE,
        :ARRIVAL_WEATHER, :ARRIVAL_WIND, :ARRIVAL_TEMPERATURE);
  end else if (OPERATION = 'mod') then begin
    update RACE
    set RACE_NUMBER = :RACE_NUMBER,
        ID_EVENT = :ID_EVENT,
        LOCATION = :LOCATION,
        DESCRIPTION = :DESCRIPTION,
        DISTANCE = :DISTANCE,
        START_TIME = :START_TIME,
        END_TIME = :END_TIME,
        SUNRISE = :SUNRISE,
        SUNSET = :SUNSET,
        WEATHER = :WEATHER,
        WIND = :WIND,
        TEMPERATURE = :TEMPERATURE,
        ARRIVAL_WEATHER = :ARRIVAL_WEATHER,
        ARRIVAL_WIND = :ARRIVAL_WIND,
        ARRIVAL_TEMPERATURE = :ARRIVAL_TEMPERATURE,
        ID_RACE_TYPE = :ID_RACE_TYPE
    where (ID_RACE = :ID_RACE);
  end else if (OPERATION = 'del') then begin
    delete from RACE
    where (ID_RACE = :ID_RACE);
  end
  suspend;
end ^

ALTER PROCEDURE RACE_PHANTOM_BIRD_MODIFY (ID_RACE_PHANTOM_BIRD INTEGER,
ID_RACE INTEGER,
ID_BIRD INTEGER,
RF_ID VARCHAR(20) CHARACTER SET NONE,
ARRIVAL_TIME TIMESTAMP,
ID_EVENT INTEGER,
OPERATION VARCHAR(3) CHARACTER SET NONE)
AS 
begin
  if (OPERATION = 'add') then begin
    if (not exists (select rpb.ID_RACE_PHANTOM_BIRD from RACE_PHANTOM_BIRD rpb
      where rpb.ID_RACE = :ID_RACE and rpb.RF_ID = :RF_ID)) then begin
      insert into RACE_PHANTOM_BIRD
        (ID_RACE_PHANTOM_BIRD, ID_RACE, ID_BIRD, RF_ID, ARRIVAL_TIME, ID_EVENT)
      values
        (gen_id(GEN_RACE_PHANTOM_BIRD_ID, 1), :ID_RACE, :ID_BIRD, :RF_ID, :ARRIVAL_TIME, :ID_EVENT);
    end
  end else if (OPERATION = 'del') then begin
    delete from RACE_PHANTOM_BIRD
    where ID_RACE_PHANTOM_BIRD = :ID_RACE_PHANTOM_BIRD;
  end
end ^

ALTER PROCEDURE RACE_PRIZE_VALUE_CALC (ID_RACE INTEGER,
IN_BIRD_DROP INTEGER = NULL)
RETURNS (ERR_CODE INTEGER,
ERR_TEXT VARCHAR(250) CHARACTER SET NONE)
AS 
declare variable ID_EVENT integer;
declare variable ID_RACE_TYPE integer;
declare variable ID_RACE_ITEM integer;
declare variable BIRD_DROP integer;
declare variable BIRD_POSITION integer;
declare variable BIRD_POSITION_HOT_SPOT integer;
declare variable ID_FINAL_PRIZE_SCHEME integer;
declare variable ID_HS1_PRIZE_SCHEME integer;
declare variable ID_HS2_PRIZE_SCHEME integer;
declare variable ID_HS3_PRIZE_SCHEME integer;
begin
  ERR_CODE = 0;
  ERR_TEXT = '';
  select r.ID_EVENT,
         r.ID_RACE_TYPE,
         e.ID_FINAL_PRIZE_SCHEME,
         e.ID_HOT_SPOT1_PRIZE_SCHEME,
         e.ID_HOT_SPOT2_PRIZE_SCHEME,
         e.ID_HOT_SPOT3_PRIZE_SCHEME
    from RACE r
    join EVENTS e on e.ID_EVENT = r.ID_EVENT
    where r.ID_RACE = :ID_RACE
    into :ID_EVENT,
         :ID_RACE_TYPE,
         :ID_FINAL_PRIZE_SCHEME,
         :ID_HS1_PRIZE_SCHEME,
         :ID_HS2_PRIZE_SCHEME,
         :ID_HS3_PRIZE_SCHEME;

  if (ID_RACE_TYPE not in (5, 6, 7, 8)) then exit; -- only hot spot and final races can have a prize

  for select rir.ID_RACE_ITEM, rir.BIRD_DROP, rir.BIRD_POSITION, rir.BIRD_POSITION_HOT_SPOT
    from RACE_ITEM ri
    join RACE_ITEM_RESULT rir on rir.ID_RACE_ITEM = ri.ID_RACE_ITEM
    where ri.ID_RACE = :ID_RACE and ((:IN_BIRD_DROP is null) or (rir.BIRD_DROP = :IN_BIRD_DROP))
    into :ID_RACE_ITEM, :BIRD_DROP, :BIRD_POSITION, :BIRD_POSITION_HOT_SPOT
  do begin
    execute procedure RACE_ITEM_PRIZE_VALUE_CALC_INT(:ID_EVENT, :ID_RACE, :ID_RACE_TYPE, :ID_RACE_ITEM,
      :BIRD_DROP, :BIRD_POSITION, :BIRD_POSITION_HOT_SPOT, :ID_FINAL_PRIZE_SCHEME,
      :ID_HS1_PRIZE_SCHEME, :ID_HS2_PRIZE_SCHEME, :ID_HS3_PRIZE_SCHEME);
  end
end ^

ALTER PROCEDURE RACE_RECALC (ID_RACE INTEGER)
RETURNS (ERR_CODE INTEGER,
ERR_TEXT VARCHAR(250) CHARACTER SET NONE)
AS 
declare variable ID_RACE_TYPE integer;
begin
  select r.ID_RACE_TYPE
    from RACE r
    where r.ID_RACE = :ID_RACE
    into :ID_RACE_TYPE;

  execute procedure RACE_ITEM_RESULT_POSITION_CALC(:ID_RACE, :ID_RACE_TYPE);
  if (ID_RACE_TYPE in (5, 6, 7, 8 /* final race and hot spots */)) then begin
    execute procedure RACE_ITEM_RESULT_HS_POS_CALC(:ID_RACE);
    -- calc prize only for hot spot races and final race
    execute procedure RACE_PRIZE_VALUE_CALC(:ID_RACE)
    returning_values  :ERR_CODE, :ERR_TEXT;
  end
end ^

ALTER PROCEDURE RACE_RESULT_GET (ID_RACE INTEGER,
SHOW_STRAY_BIRDS SMALLINT,
SHOW_FOREIGN_BIRDS SMALLINT,
SHOW_IGNORED_BIRDS SMALLINT)
RETURNS (BIRD_POSITION INTEGER,
BIRD_POSITION_HOT_SPOT INTEGER,
ID_RACE_ITEM INTEGER,
ID_BREEDER INTEGER,
ID_BIRD INTEGER,
ID_EVENT_INVENTORY INTEGER,
ID_EVENT_INVENTORY_ITEM INTEGER,
RF_ID VARCHAR(20) CHARACTER SET NONE,
ARRIVAL_TIME TIMESTAMP,
BIRD_DROP INTEGER,
PRIZE_VALUE NUMERIC(15, 4),
AVG_SPEED_IN_MILES NUMERIC(15, 4),
AVG_SPEED_IN_YARDS NUMERIC(15, 4),
DIFFERENCE_TIME TIMESTAMP,
ID_PHANTOM INTEGER,
ID_IGNORED INTEGER,
IGNORE_NOTE VARCHAR(100) CHARACTER SET NONE,
BIRD_TYPE SMALLINT)
AS 
DECLARE VARIABLE DISTANCE INTEGER;
DECLARE VARIABLE START_TIME TIMESTAMP;
DECLARE VARIABLE SUNRISE TIME;
DECLARE VARIABLE SUNSET TIME;
DECLARE VARIABLE LOST_ID_RACE INTEGER;
DECLARE VARIABLE FLIGHT_TIME BIGINT;
begin
  /*BIRD_TYPE: arrived 0; stray 1; foreign 2; not arrived 3; ignored 4*/
  select r.DISTANCE, r.START_TIME, r.SUNRISE, r.SUNSET
    from RACE r
    where r.ID_RACE = :ID_RACE
    into :DISTANCE, :START_TIME, :SUNRISE, :SUNSET;

  if (SHOW_STRAY_BIRDS is null) then begin  
    SHOW_STRAY_BIRDS = 0;
  end
  if (SHOW_FOREIGN_BIRDS is null) then begin
    SHOW_FOREIGN_BIRDS = 0;
  end

  for select rir.BIRD_POSITION, rir.BIRD_POSITION_HOT_SPOT, ri.ID_RACE_ITEM, ei.ID_BREEDER, eii.ID_BIRD,
    rir.ARRIVAL_TIME, rir.BIRD_DROP, rir.PRIZE_VALUE, ri.LOST_ID_RACE, br.RF_ID,
    ei.ID_EVENT_INVENTORY, eii.ID_EVENT_INVENTORY_ITEM
    from RACE_ITEM ri
    join EVENT_INVENTORY_ITEM eii on eii.ID_EVENT_INVENTORY_ITEM = ri.ID_INVENTORY_ITEM
    join EVENT_INVENTORY ei on ei.ID_EVENT_INVENTORY = eii.ID_EVENT_INVENTORY
    join BREEDERS b on b.ID_BREEDER = ei.ID_BREEDER
    join BIRDS br on br.ID_BIRD = eii.ID_BIRD
    left join RACE_ITEM_RESULT rir on rir.ID_RACE_ITEM = ri.ID_RACE_ITEM
    where (ri.ID_RACE = :ID_RACE)
    into :BIRD_POSITION, :BIRD_POSITION_HOT_SPOT, :ID_RACE_ITEM, :ID_BREEDER, :ID_BIRD, :ARRIVAL_TIME,
      :BIRD_DROP, :PRIZE_VALUE, :LOST_ID_RACE, :RF_ID, :ID_EVENT_INVENTORY, :ID_EVENT_INVENTORY_ITEM
  do begin
    AVG_SPEED_IN_MILES = null;
    AVG_SPEED_IN_YARDS = null;
    DIFFERENCE_TIME = null; -- TODO
    ID_PHANTOM = null;
    ID_IGNORED = null;
    IGNORE_NOTE = null;
    BIRD_TYPE = 0;
    if (ARRIVAL_TIME is null) then begin
      BIRD_TYPE = 3;
    end
    if ((ARRIVAL_TIME is not null) and (LOST_ID_RACE is not null)) then begin
      BIRD_TYPE = 1;
    end
    if ((SHOW_STRAY_BIRDS > 0) or (BIRD_TYPE <> 1))  then begin
      if ((LOST_ID_RACE is null) and (DISTANCE is not null) and (DISTANCE > 0)) then begin
        execute procedure CALC_AVG_SPEED_INT(:DISTANCE, :START_TIME, :ARRIVAL_TIME, :SUNRISE, :SUNSET)
        returning_values :AVG_SPEED_IN_YARDS, :AVG_SPEED_IN_MILES, :FLIGHT_TIME;
      end
      suspend;
    end
  end
  if (SHOW_FOREIGN_BIRDS > 0) then begin
    BIRD_TYPE = 2;
    BIRD_POSITION = null;
    BIRD_POSITION_HOT_SPOT = null;
    ID_RACE_ITEM = null;
    BIRD_DROP = null;
    PRIZE_VALUE = null;
    AVG_SPEED_IN_YARDS = null;
    AVG_SPEED_IN_MILES = null;
    DIFFERENCE_TIME = null;
    for select ei.ID_BREEDER, rpb.ID_BIRD, rpb.RF_ID, rpb.ARRIVAL_TIME, rpb.ID_RACE_PHANTOM_BIRD,
      ei.ID_EVENT_INVENTORY, eii.ID_EVENT_INVENTORY_ITEM
      from RACE_PHANTOM_BIRD rpb
      left join EVENT_INVENTORY_ITEM eii on eii.ID_BIRD = rpb.ID_BIRD
      left join EVENT_INVENTORY ei on ei.ID_EVENT_INVENTORY = eii.ID_EVENT_INVENTORY
      where rpb.ID_RACE = :ID_RACE
      into :ID_BREEDER, :ID_BIRD, :RF_ID, :ARRIVAL_TIME, :ID_PHANTOM, :ID_EVENT_INVENTORY,
        :ID_EVENT_INVENTORY_ITEM
    do begin
      suspend;
    end
  end
  if (SHOW_IGNORED_BIRDS > 0) then begin
    BIRD_TYPE = 4;
    BIRD_POSITION = null;
    BIRD_POSITION_HOT_SPOT = null;
    ID_RACE_ITEM = null;
    BIRD_DROP = null;
    ARRIVAL_TIME = null;
    PRIZE_VALUE = null;
    AVG_SPEED_IN_YARDS = null;
    AVG_SPEED_IN_MILES = null;
    DIFFERENCE_TIME = null;
    for select ei.ID_BREEDER, eii.ID_BIRD, b.RF_ID, rib.ID_IGNORE_BIRD, RIB.NOTE,
      ei.ID_EVENT_INVENTORY, eii.ID_EVENT_INVENTORY_ITEM
      from RACE_IGNORE_BIRD rib
      join EVENT_INVENTORY_ITEM eii on eii.ID_EVENT_INVENTORY_ITEM = rib.ID_EVENT_INVENTORY_ITEM
      join BIRDS b on b.ID_BIRD = eii.ID_BIRD
      join EVENT_INVENTORY ei on ei.ID_EVENT_INVENTORY = eii.ID_EVENT_INVENTORY
      where rib.ID_RACE = :ID_RACE
      into :ID_BREEDER, :ID_BIRD, :RF_ID, :ID_IGNORED, :IGNORE_NOTE,
        :ID_EVENT_INVENTORY, :ID_EVENT_INVENTORY_ITEM
    do begin
      suspend;
    end
  end
end ^

ALTER PROCEDURE RACE_TOTAL_GET RETURNS (ID_RACE INTEGER,
IN_RACE INTEGER,
BASKETED INTEGER,
ARRIVAL INTEGER,
NOT_ARRIVAL INTEGER,
LOST INTEGER,
STRAY INTEGER,
FOREIGN_ INTEGER,
TOTAL INTEGER)
AS 
declare variable ID_RACE_BASKET integer;
declare variable IS_LOST smallint;
declare variable ARRIVAL_TIME timestamp;
declare variable ID_RETURN_RACE integer;
begin
  for select r.ID_RACE
    from RACE r
    into :ID_RACE
  do begin
    IN_RACE = 0;
    BASKETED = 0;
    ARRIVAL = 0;
    NOT_ARRIVAL = 0;
    LOST = 0;
    STRAY = 0;
    TOTAL = 0;
    for select ri.ID_RACE_BASKET, ri.IS_LOST, rir.ARRIVAL_TIME, ri.LOST_ID_RACE
      from RACE_ITEM ri
      left join RACE_ITEM_RESULT rir on rir.ID_RACE_ITEM = ri.ID_RACE_ITEM
      where ri.ID_RACE = :ID_RACE
      into :ID_RACE_BASKET, :IS_LOST, :ARRIVAL_TIME, :ID_RETURN_RACE
    do begin
      IN_RACE = IN_RACE + 1;
      if (ID_RACE_BASKET is not null) then begin
        BASKETED = BASKETED + 1;
      end
      if (ARRIVAL_TIME is not null) then begin
        ARRIVAL = ARRIVAL + 1;
        if (ID_RETURN_RACE is not null) then begin
          STRAY = STRAY + 1;
        end
      end else begin
        NOT_ARRIVAL = NOT_ARRIVAL + 1;
      end
      if (IS_LOST > 0) then begin
        LOST = LOST + 1;
      end
    end
    FOREIGN_ = 0;
    select count(rpb.ID_RACE_PHANTOM_BIRD)
      from RACE_PHANTOM_BIRD rpb
      where rpb.ID_RACE = :ID_RACE
      into :FOREIGN_;
    TOTAL = ARRIVAL + NOT_ARRIVAL + FOREIGN_;
    suspend;
  end
end ^

ALTER PROCEDURE REGEN_BREEDER_NUMBERS AS 
declare variable NUMBER integer;
declare variable ID_BREEDER integer;
begin
  NUMBER = 0;
  for select b.ID_BREEDER
    from BREEDERS b
    into :ID_BREEDER
  do begin
    NUMBER = NUMBER + 1;
    update BREEDERS b
      set b.NUMBER = :NUMBER
      where b.ID_BREEDER = :ID_BREEDER;
  end
end ^

ALTER PROCEDURE REPORT_CLASS_MODIFY (IDENT VARCHAR(150) CHARACTER SET NONE,
CLASS_ VARCHAR(150) CHARACTER SET NONE,
TYPE VARCHAR(20) CHARACTER SET NONE,
CAPTION VARCHAR(200) CHARACTER SET NONE,
COPIES INTEGER,
OPERATION VARCHAR(20) CHARACTER SET NONE)
RETURNS (NEW_ID_REPORT INTEGER)
AS 
begin
  if (:operation is null) then operation = 'null';
  if (:operation not in ('add', 'mod', 'del')) then
    exception ERR 'Unknown value for operation in REPORT_CLASS_MODIFY, value='||:operation;

  if (:operation = 'add') then begin
    insert into REPORT_CLASSES (IDENT, CAPTION, COPIES, "TYPE")
    values (:ident, :caption, :copies, :"TYPE");
  end else if (:operation = 'mod') then begin
    update REPORT_CLASSES
    set CAPTION = :caption,
        COPIES = :copies,
        "TYPE" = :"TYPE"
    where IDENT = :ident;
  end else if (:operation = 'del') then begin
    delete from REPORT_CLASSES
    where IDENT = :ident;
  end
end ^

ALTER PROCEDURE REPORT_MODIFY (ID_REPORT INTEGER,
IDENT VARCHAR(150) CHARACTER SET NONE,
CLASS_ VARCHAR(150) CHARACTER SET NONE,
FASTREPORT_CONTENT BLOB,
DEFAULT_CAPTION VARCHAR(200) CHARACTER SET NONE,
OPERATION VARCHAR(20) CHARACTER SET NONE)
RETURNS (NEW_ID_REPORT INTEGER)
AS 
begin
  if (:operation is null) then operation = 'null';
  if (:operation not in ('add', 'mod', 'del', 'mod_content', 'mod_content_i')) then
    exception ERR 'Unknown value for operation in REPORT_MODIFY, value='||:operation;

  new_id_report = :id_report;

  if (:operation = 'add') then begin
    if ((:id_report is null) or (:id_report <= 0))  then
      new_id_report = gen_id(GEN_REPORTS_ID, 1);
      
    if (exists (select * from REPORTS where IDENT = :ident and IS_DELETED = 0)) then
      exception ERR 'Duplicate Ident';

    insert into REPORTS(
      ID_REPORT,
      IDENT, CLASS_, FASTREPORT_CONTENT, DEFAULT_CAPTION,
      IS_DELETED)
    values (
      :new_id_report,
      :ident, :class_, null, :default_caption,
      0);
  end else if (:operation = 'mod') then begin
    if (exists (select * from REPORTS where IDENT = :ident and IS_DELETED = 0 and ID_REPORT <> :id_report)) then
      exception ERR 'Duplicate Ident';

    update REPORTS
    set IDENT = :ident,
        CLASS_ = :class_,
        DEFAULT_CAPTION = :default_caption
    where ID_REPORT = :id_report;
  end else if (:operation = 'del') then begin
    update REPORTS
    set IS_DELETED = 1
    where ID_REPORT = :id_report;
  end else if (:operation = 'mod_content') then begin
    update REPORTS
    set FASTREPORT_CONTENT = :fastreport_content
    where ID_REPORT = :id_report;
  end else if (:operation = 'mod_content_i') then begin
    update REPORTS
    set FASTREPORT_CONTENT = :fastreport_content
    where IDENT = :ident
      and IS_DELETED = 0;
  end
end ^

ALTER PROCEDURE RETURN_BIRD (ID_BIRD INTEGER,
RETURN_DATE DATE)
AS 
begin
  update EVENT_INVENTORY_ITEM eii
    set eii.DEPARTURE_DATE = :RETURN_DATE
    where eii.ID_BIRD = :ID_BIRD;

  update BIRDS b
    set b.RF_ID = null
    where b.ID_BIRD = :ID_BIRD;
end ^

ALTER PROCEDURE RIGHTS_PROTECT (RIGHT_CODE VARCHAR(30) CHARACTER SET NONE)
RETURNS (ERR_CODE INTEGER)
AS 
declare variable granted_users_cnt integer;
begin
  err_code = 0;
  if (:right_code is not null) then begin
    select count(distinct RUG.ID_USER)
    from   RIGHT_GROUP_LINES RGL
           join USER_RIGHT_GROUPS RUG on RUG.ID_RIGHT_GROUP = RGL.ID_RIGHT_GROUP
           join USERS U on U.ID_USER = RUG.ID_USER
    where  RGL.RIGHT_CODE = :right_code
      and  U.IS_ACTIVE = 1
    into   :granted_users_cnt;
  
    if (:granted_users_cnt = 0) then begin
      err_code = -4;
    end
  end else begin
    execute procedure RIGHTS_PROTECT('rights.users.edit') returning_values (:err_code);
    if (err_code <> 0) then exit;
    execute procedure RIGHTS_PROTECT('rights.edit') returning_values (:err_code);
  end
end ^

ALTER PROCEDURE RIGHTS_REGRANT AS 
declare variable my_user_name varchar (30);
begin
delete from RDB$USER_PRIVILEGES 
      where RDB$USER <> 'SYSDBA' 
            and RDB$USER <> 'PUBLIC'; 



 INSERT INTO RDB$USER_PRIVILEGES (RDB$USER, RDB$GRANTOR, RDB$PRIVILEGE, RDB$GRANT_OPTION, RDB$RELATION_NAME, RDB$FIELD_NAME, RDB$USER_TYPE, RDB$OBJECT_TYPE)
 SELECT 'PUBLIC' , 'SYSDBA' , RDB$PRIVILEGE, 0 , RDB$RELATION_NAME, RDB$FIELD_NAME, RDB$USER_TYPE, RDB$OBJECT_TYPE
 FROM RDB$USER_PRIVILEGES u
 WHERE u.RDB$USER = 'SYSDBA'
        and 
        ( not exists  
          (SELECT 'X'
           FROM RDB$USER_PRIVILEGES u2
           WHERE u2.RDB$USER = 'PUBLIC'
                 and u2.RDB$PRIVILEGE = u.RDB$PRIVILEGE 
                 and u2.RDB$RELATION_NAME = u.RDB$RELATION_NAME));
end ^

ALTER PROCEDURE RIGHT_GROUPS_MODIFY (ID_RIGHT_GROUP INTEGER,
NAME VARCHAR(50) CHARACTER SET NONE,
OPERATION VARCHAR(20) CHARACTER SET NONE)
RETURNS (ERR_CODE INTEGER,
ERR_TEXT VARCHAR(100) CHARACTER SET NONE,
NEW_ID_RIGHT_GROUP INTEGER)
AS 
begin
  err_code = 0;
  err_text = '';
  if (:operation is null) then operation = 'null';
  if (:operation not in ('add', 'mod', 'del')) then begin
    err_code = -1;
    err_text = 'Unknown value for operation in RIGHT_GROUPS_MODIFY, value='||:operation;
    exit;
  end

  if ((:id_right_group is null) or (:id_right_group <= 0))  then
    new_id_right_group = gen_id(GEN_RIGHT_GROUPS_ID, 1);
  else new_id_right_group = :id_right_group;

  if (:operation = 'add') then begin
    insert into RIGHT_GROUPS
      (ID_RIGHT_GROUP, NAME)
    values
      (:new_id_right_group, :name);
  end else if (:operation = 'mod') then begin
    update RIGHT_GROUPS UG
    set    UG.NAME  = :name
    where  UG.ID_RIGHT_GROUP = :id_right_group;
  end else if (:operation = 'del') then begin
    delete from RIGHT_GROUPS
    where ID_RIGHT_GROUP = :id_right_group;
  end
  execute procedure RIGHTS_PROTECT(null) returning_values :err_code;
end ^

ALTER PROCEDURE RIGHT_GROUP_RIGHTS_MODIFY (ID_RIGHT_GROUP INTEGER,
RIGHT_CODE VARCHAR(50) CHARACTER SET NONE,
OPERATION VARCHAR(20) CHARACTER SET NONE)
RETURNS (ERR_CODE INTEGER,
ERR_TEXT VARCHAR(255) CHARACTER SET NONE)
AS 
begin
  err_code = 0;
  err_text = '';
  if (:operation is null) then operation = 'null';
  if (:operation not in ('grant', 'revoke')) then begin
    err_code = -3;
    err_text = 'Unknown value for operation in RIGHT_GROUP_RIGHTS_MODIFY, value='||:operation;
    exit;
  end

  if (:operation = 'grant') then begin
    if (not exists(select *
                   from   RIGHT_GROUP_LINES RGL
                   where  RGL.ID_RIGHT_GROUP = :id_right_group
                     and  RGL.RIGHT_CODE = :right_code)) then
      insert into RIGHT_GROUP_LINES
        (ID_RIGHT_GROUP, RIGHT_CODE, GRANT_LEVEL)
      values
        (:id_right_group, :right_code, 2);
  end else if (:operation = 'revoke') then begin
    delete
    from   RIGHT_GROUP_LINES RGL
    where  RGL.ID_RIGHT_GROUP = :id_right_group
      and  RGL.RIGHT_CODE = :right_code;
  end
  execute procedure RIGHTS_PROTECT(null) returning_values :err_code;
end ^

ALTER PROCEDURE SS_DESC_BY_SCHEME_GET (ID_SCHEME INTEGER)
RETURNS (DESCRIPTION VARCHAR(100) CHARACTER SET NONE)
AS 
declare variable PERC_VALUE integer;
begin
  DESCRIPTION = '';
  for select ssp.PERC_VALUE
    from STANDARD_SHOW_PERCENTAGE ssp
    where ssp.ID_BETTING_SCHEME = :ID_SCHEME
    order by ssp.PLACE
    into :PERC_VALUE
  do begin
    if (DESCRIPTION <> '') then begin
      DESCRIPTION = DESCRIPTION || '-';
    end
    DESCRIPTION = DESCRIPTION || PERC_VALUE;
  end
  if (DESCRIPTION <> '') then begin
    DESCRIPTION = 'Standard show (' || DESCRIPTION || ')';
  end
  suspend;
end ^

ALTER PROCEDURE STANDARD_SHOW_DESC_GET (ID_EVENT INTEGER)
RETURNS (DESCRIPTION VARCHAR(100) CHARACTER SET NONE)
AS 
declare variable ID_SCHEME integer;
begin
  select e.ID_BETTING_SCHEME
    from EVENTS e
    where e.ID_EVENT = :ID_EVENT
    into :ID_SCHEME;

  DESCRIPTION = '';
  if (ID_SCHEME is not null) then begin
    execute procedure SS_DESC_BY_SCHEME_GET(:ID_SCHEME)
    returning_values :DESCRIPTION;
  end

  suspend;
end ^

ALTER PROCEDURE STANDARD_SHOW_PARSE_GET (ID_EVENT INTEGER,
BETS_SUMMARY NUMERIC(15, 4))
RETURNS (DESCRIPTION VARCHAR(250) CHARACTER SET NONE)
AS 
declare variable PERC_VALUE integer;
declare variable REST_VALUE numeric(15, 4);
begin
  DESCRIPTION = '';
  REST_VALUE = BETS_SUMMARY;
  for select ssp.PERC_VALUE
    from EVENTS e
    join BETTING_SCHEME bs on bs.ID_BETTING_SCHEME = e.ID_BETTING_SCHEME
    join STANDARD_SHOW_PERCENTAGE ssp on ssp.ID_BETTING_SCHEME = bs.ID_BETTING_SCHEME
    where e.ID_EVENT = :ID_EVENT
    order by ssp.PLACE
    into :PERC_VALUE
  do begin
    if (DESCRIPTION <> '') then begin
      DESCRIPTION = DESCRIPTION || ' - ';
    end
    if (REST_VALUE < (BETS_SUMMARY * PERC_VALUE) / 100) then begin
      DESCRIPTION = DESCRIPTION || '$' || cast(REST_VALUE as numeric(15, 2));
      REST_VALUE = 0;
    end else begin
      DESCRIPTION = DESCRIPTION || '$' || cast(((BETS_SUMMARY * PERC_VALUE) / 100) as numeric(15, 2));
      REST_VALUE = REST_VALUE - ((BETS_SUMMARY * PERC_VALUE) / 100);
    end
  end
  suspend;
end ^

ALTER PROCEDURE STANDARD_SHOW_PERC_MODIFY (ID_STANDARD_SHOW_PERCENTAGE INTEGER,
ID_BETTING_SCHEME INTEGER,
PLACE INTEGER,
PERC_VALUE NUMERIC(15, 4),
OPERATION VARCHAR(3) CHARACTER SET NONE)
RETURNS (NEW_ID_STANDARD_SHOW_PERCENTAGE INTEGER)
AS 
begin
  NEW_ID_STANDARD_SHOW_PERCENTAGE = ID_STANDARD_SHOW_PERCENTAGE;
  if (OPERATION = 'add') then begin
    NEW_ID_STANDARD_SHOW_PERCENTAGE = gen_id(GEN_STANDARD_SHOW_PERCENTAGE_ID, 1);
    insert into STANDARD_SHOW_PERCENTAGE(ID_STANDARD_SHOW_PERCENTAGE, ID_BETTING_SCHEME, PLACE, PERC_VALUE)
    values (:NEW_ID_STANDARD_SHOW_PERCENTAGE, :ID_BETTING_SCHEME, :PLACE, :PERC_VALUE);
  end else if (OPERATION = 'mod') then begin
    update STANDARD_SHOW_PERCENTAGE
    set ID_BETTING_SCHEME = :ID_BETTING_SCHEME,
        PLACE = :PLACE,
        PERC_VALUE = :PERC_VALUE
    where ID_STANDARD_SHOW_PERCENTAGE = :ID_STANDARD_SHOW_PERCENTAGE;
  end else if (OPERATION = 'del') then begin
    delete from STANDARD_SHOW_PERCENTAGE
    where ID_STANDARD_SHOW_PERCENTAGE = :ID_STANDARD_SHOW_PERCENTAGE;
  end
  suspend;
end ^

ALTER PROCEDURE SYSTEM_CFG_GET (CFG_KEY VARCHAR(200) CHARACTER SET NONE)
RETURNS (CFG_VALUE VARCHAR(255) CHARACTER SET NONE)
AS 
begin
  select sc.CFG_VALUE
    from SYSTEM_CFG sc
    where sc.CFG_KEY = :CFG_KEY
    into :CFG_VALUE;
  if (CFG_VALUE is null) then begin
    exception CFG_VALUE_NOT_FOUND 'Configuration value not found! (key ' || :CFG_KEY || ')';
  end
  suspend;
end ^

ALTER PROCEDURE SYSTEM_CFG_MODIFY (CFG_KEY VARCHAR(200) CHARACTER SET NONE,
CFG_VALUE VARCHAR(255) CHARACTER SET NONE,
OPERATION VARCHAR(10) CHARACTER SET NONE)
RETURNS (ERR_CODE INTEGER,
ERR_TEXT VARCHAR(255) CHARACTER SET NONE)
AS 

begin
  err_code = 0;
  err_text = '';

  if (:operation not in ('clear','set')) then begin
    err_code = -1;
    err_text = 'procedure SYSTEM_CFG_MODIFY, value ' || :operation;
    exit;
  end

  if (:operation = 'clear') then begin
    delete
    from SYSTEM_CFG SC
    where SC.CFG_KEY like :cfg_key||'%';
  end else
  if (:operation = 'set') then begin
    if (exists(select * from SYSTEM_CFG SC where SC.CFG_KEY = :cfg_key)) then begin
      update SYSTEM_CFG SC
      set SC.CFG_VALUE = :cfg_value
      where SC.CFG_KEY = :cfg_key;
    end else begin
      insert into SYSTEM_CFG(CFG_KEY, CFG_VALUE)
      values (:CFG_KEY, :CFG_VALUE);
    end
  end
end ^

ALTER PROCEDURE SYSTEM_LOGIN (LOGIN_NAME VARCHAR(30) CHARACTER SET NONE,
PASSWORD_ VARCHAR(30) CHARACTER SET NONE)
RETURNS (ERR_CODE INTEGER,
ERR_TEXT VARCHAR(255) CHARACTER SET NONE)
AS 

begin
  err_code = 0;
  err_text = '';

  if (not exists(select *
                 from USERS U
                 where U.LOGIN_NAME = :login_name
                   and U."PASSWORD" = :password_
                   and U.IS_ACTIVE = 1)) then begin
    err_code = -3;
  end
end ^

ALTER PROCEDURE SYSTEM_SESSION_MODIFY (SESSION_KEY VARCHAR(50) CHARACTER SET NONE,
SESSION_VALUE VARCHAR(255) CHARACTER SET NONE,
OPERATION VARCHAR(10) CHARACTER SET NONE)
RETURNS (ERR_CODE INTEGER,
ERR_TEXT VARCHAR(255) CHARACTER SET NONE)
AS 

begin
  err_code = 0;
  err_text = '';

  if (:operation not in ('clear','set')) then begin
    err_code = -1;
    err_text = 'procedure SYSTEM_SESSION_MODIFY, value ' || :operation;
    exit;
  end

  if (:operation = 'clear') then begin
    delete
    from SYSTEM_SESSION SS
    where SS.SESSION_KEY = :session_key;
  end else
  if (:operation = 'set') then begin
    if (exists(select * from SYSTEM_SESSION SS where SS.SESSION_KEY = :session_key)) then begin
      update SYSTEM_SESSION SS
      set SS.SESSION_VALUE = :session_value
      where SS.SESSION_KEY = :session_key;
    end else begin
      insert into SYSTEM_SESSION(SESSION_KEY, SESSION_VALUE)
      values (:session_key, :session_value);
    end
  end
end ^

ALTER PROCEDURE SYSTEM_UPDATE_REGISTER (PATCH_VERSION VARCHAR(20) CHARACTER SET NONE,
NEW_VERSION VARCHAR(20) CHARACTER SET NONE,
CHANGE_INFO VARCHAR(4096) CHARACTER SET NONE,
EXE_REQUIREMENT VARCHAR(20) CHARACTER SET NONE)
AS 
declare variable id_system_update integer;
begin
  id_system_update = gen_id(GEN_SYSTEM_UPDATES_ID, 1);
  insert into SYSTEM_UPDATES(
    ID_SYSTEM_UPDATE,
    PATCH_VERSION, DATETIME_EXECUTION,
    CHANGE_INFO)
  values (
    :id_system_update,
    :patch_version, current_timestamp,
    :change_info);

  insert into SYSTEM_REQUIREMENTS(
    "MODULE_NAME", REQUIRED_VERSION,
    ID_SYSTEM_UPDATE)
  values (
    'SalseReportsToolsDatabase', :exe_requirement,
    :id_system_update);

  update SYSTEM_INFO
  set INFO_VALUE = :new_version
  where INFO_KEY = 'CURRENT_VERSION';

  if (row_count = 0) then begin
    insert into SYSTEM_INFO (INFO_KEY, INFO_VALUE)
    values ('CURRENT_VERSION', :new_version);
  end

  execute procedure rights_regrant;
end ^

ALTER PROCEDURE TMP_BETS_BY_EVENT_INSERT (ID_EVENT INTEGER)
RETURNS (EXEC_TIME TIMESTAMP)
AS 
declare variable ID_FINAL_RACE integer;
begin
  select r.ID_RACE
    from RACE r
    where r.ID_EVENT = :ID_EVENT and r.ID_RACE_TYPE = 5
    into :ID_FINAL_RACE;

  EXEC_TIME = 'now';
  EXEC_TIME = EXEC_TIME - 1; -- do NOT change it
  insert into TMP_BETS
    (ID_RACE_ITEM, ID_EVENT_INVENTORY_ITEM, BIRD_DROP, BELGIAN_SHOW_1, BELGIAN_SHOW_2, BELGIAN_SHOW_3,
    BELGIAN_SHOW_4, BELGIAN_SHOW_5, BELGIAN_SHOW_6, BELGIAN_SHOW_7, STANDARD_SHOW_1,
    STANDARD_SHOW_2, STANDARD_SHOW_3, STANDARD_SHOW_4, STANDARD_SHOW_5, STANDARD_SHOW_6,
    WTA_1, WTA_2, WTA_3, WTA_4, WTA_5, TOTAL, EXEC_TIME)
  select rbc.ID_RACE_ITEM, rbc.ID_EVENT_INVENTORY_ITEM, null, rbc.BELGIAN_SHOW_1, rbc.BELGIAN_SHOW_2, rbc.BELGIAN_SHOW_3,
    rbc.BELGIAN_SHOW_4, rbc.BELGIAN_SHOW_5, rbc.BELGIAN_SHOW_6, rbc.BELGIAN_SHOW_7, rbc.STANDARD_SHOW_1,
    rbc.STANDARD_SHOW_2, rbc.STANDARD_SHOW_3, rbc.STANDARD_SHOW_4, rbc.STANDARD_SHOW_5, rbc.STANDARD_SHOW_6,
    rbc.WTA_1, rbc.WTA_2, rbc.WTA_3, rbc.WTA_4, rbc.WTA_5, rbc.TOTAL, :EXEC_TIME
  from RACE_BETS_CALC(:ID_FINAL_RACE) rbc;

  suspend;
end ^

ALTER PROCEDURE TMP_ID_ADD (ID INTEGER,
TAG VARCHAR(100) CHARACTER SET NONE)
AS 
begin
  if (not exists(select ti.ID  from TMP_ID ti where ti.ID = :ID and ti.TAG = :TAG)) then begin
    insert into TMP_ID (ID, TAG)
    values(:ID, :TAG);
  end
end ^

ALTER PROCEDURE TMP_ID_CLEAR (TAG VARCHAR(100) CHARACTER SET NONE)
AS 
begin
  if (TAG is null) then begin
    delete from TMP_ID;
  end else begin
    delete from TMP_ID t
      where t.TAG = :TAG;
  end
end ^

ALTER PROCEDURE USER_MODIFY (ID_USER INTEGER,
LOGIN_NAME VARCHAR(30) CHARACTER SET NONE,
FULL_NAME VARCHAR(50) CHARACTER SET NONE,
"PASSWORD" VARCHAR(30) CHARACTER SET NONE,
EMAIL_ADDRESS VARCHAR(100) CHARACTER SET NONE,
IS_ACTIVE SMALLINT,
OPERATION VARCHAR(10) CHARACTER SET NONE)
RETURNS (ERR_CODE INTEGER,
ERR_TEXT VARCHAR(255) CHARACTER SET NONE,
NEW_ID_USER INTEGER)
AS 
begin
  err_code = 0;
  err_text = '';

  if (:operation not in ('add','mod','del')) then begin
    err_code = -1;
    err_text = 'procedure USER_MODIFY_FULL, value ' || :operation;
    exit;
  end

  if ((:id_user is null) or (:id_user <= 0)) then
    new_id_user = gen_id(GEN_USERS_ID, 1);
  else new_id_user = :id_user;

  if (:operation = 'add') then begin
    insert into USERS(
      ID_USER,
      LOGIN_NAME, FULL_NAME, "PASSWORD",
      EMAIL_ADDRESS, IS_ACTIVE)
    values (
      :new_id_user,
      :login_name, :full_name, :"PASSWORD",
      :email_address, :is_active);
  end else if (:operation = 'mod') then begin
    update USERS
     set LOGIN_NAME = :login_name,
         FULL_NAME = :full_name,
         "PASSWORD" = :"PASSWORD",
         EMAIL_ADDRESS = :email_address,
         IS_ACTIVE = :is_active
     where id_user = :id_user;
  end else if (:operation = 'del') then begin
    update USERS
     set IS_ACTIVE = 0
     where id_user = :id_user;
  end
  execute procedure RIGHTS_PROTECT(null) returning_values (:err_code);
end ^

ALTER PROCEDURE USER_RIGHT_GROUPS_MODIFY (ID_RIGHT_GROUP INTEGER,
ID_USER INTEGER,
OPERATION VARCHAR(20) CHARACTER SET NONE)
RETURNS (ERR_CODE INTEGER,
ERR_TEXT VARCHAR(255) CHARACTER SET NONE)
AS 
begin
  err_code = 0;
  err_text = '';
  if (:operation is null) then operation = 'null';
  if (:operation not in ('grant', 'revoke')) then begin
    err_code = -3;
    err_text = 'Unknown value for operation in USER_RIGHT_GROUPS_MODIFY, value='||:operation;
    exit;
  end

  if (:operation = 'grant') then begin
    if (not exists (select first 1 1
                    from   USER_RIGHT_GROUPS RUG
                    where  RUG.ID_RIGHT_GROUP = :id_right_group
                      and  RUG.ID_USER = :id_user)) then
      insert into USER_RIGHT_GROUPS
        (ID_RIGHT_GROUP, ID_USER)
      values
        (:id_right_group, :id_user);
  end else if (:operation = 'revoke') then begin
    delete
    from   USER_RIGHT_GROUPS RUG
    where  RUG.ID_RIGHT_GROUP = :id_right_group
      and  RUG.ID_USER = :id_user;
  end
  execute procedure RIGHTS_PROTECT(null) returning_values (:err_code);
end ^

ALTER PROCEDURE WINNER_PAYOUT_BIRD_GET (ID_EVENT_INVENTORY_ITEM INTEGER)
RETURNS (CAPITAL_VALUE NUMERIC(15, 4),
HOT_SPOT_1_VALUE NUMERIC(15, 4),
HOT_SPOT_2_VALUE NUMERIC(15, 4),
HOT_SPOT_3_VALUE NUMERIC(15, 4),
AVG_SPEED_WINNER_VALUE NUMERIC(15, 4),
BELGIAN_SHOW_1 NUMERIC(15, 4),
BELGIAN_SHOW_2 NUMERIC(15, 4),
BELGIAN_SHOW_3 NUMERIC(15, 4),
BELGIAN_SHOW_4 NUMERIC(15, 4),
BELGIAN_SHOW_5 NUMERIC(15, 4),
BELGIAN_SHOW_6 NUMERIC(15, 4),
BELGIAN_SHOW_7 NUMERIC(15, 4),
STANDARD_SHOW_1 NUMERIC(15, 4),
STANDARD_SHOW_2 NUMERIC(15, 4),
STANDARD_SHOW_3 NUMERIC(15, 4),
STANDARD_SHOW_4 NUMERIC(15, 4),
STANDARD_SHOW_5 NUMERIC(15, 4),
STANDARD_SHOW_6 NUMERIC(15, 4),
WTA_1 NUMERIC(15, 4),
WTA_2 NUMERIC(15, 4),
WTA_3 NUMERIC(15, 4),
WTA_4 NUMERIC(15, 4),
WTA_5 NUMERIC(15, 4),
BETS_VALUE NUMERIC(15, 4),
TOTAL_VALUE NUMERIC(15, 4))
AS 
declare variable ID_FINAL_RACE integer;
declare variable PRIZE_TOTAL numeric(15, 4);
begin
  select wp.CAPITAL_VALUE, wp.HOT_SPOT_1_VALUE, wp.HOT_SPOT_2_VALUE, wp.HOT_SPOT_3_VALUE,
         wp.AVG_SPEED_WINNER_VALUE, wp.PRIZE_TOTAL, ri.ID_RACE
    from WINNER_PRIZE_PAYOUT_BIRD_GET(:ID_EVENT_INVENTORY_ITEM) wp
    left join RACE_ITEM ri on ri.ID_RACE_ITEM = wp.ID_FINAL_RACE_ITEM
    into :CAPITAL_VALUE, :HOT_SPOT_1_VALUE, :HOT_SPOT_2_VALUE, :HOT_SPOT_3_VALUE,
         :AVG_SPEED_WINNER_VALUE, :PRIZE_TOTAL, :ID_FINAL_RACE;

  select bc.BELGIAN_SHOW_1, bc.BELGIAN_SHOW_2, bc.BELGIAN_SHOW_3, bc.BELGIAN_SHOW_4,
         bc.BELGIAN_SHOW_5, bc.BELGIAN_SHOW_6, bc.BELGIAN_SHOW_7, bc.STANDARD_SHOW_1,
         bc.STANDARD_SHOW_2, bc.STANDARD_SHOW_3, bc.STANDARD_SHOW_4, bc.STANDARD_SHOW_5,
         bc.STANDARD_SHOW_6, bc.WTA_1, bc.WTA_2, bc.WTA_3, bc.WTA_4, bc.WTA_5, bc.TOTAL
    from RACE_BETS_CALC(:ID_FINAL_RACE) bc
    where bc.ID_EVENT_INVENTORY_ITEM = :ID_EVENT_INVENTORY_ITEM
    into :BELGIAN_SHOW_1, :BELGIAN_SHOW_2, :BELGIAN_SHOW_3, :BELGIAN_SHOW_4,
         :BELGIAN_SHOW_5, :BELGIAN_SHOW_6, :BELGIAN_SHOW_7, :STANDARD_SHOW_1,
         :STANDARD_SHOW_2, :STANDARD_SHOW_3, :STANDARD_SHOW_4, :STANDARD_SHOW_5,
         :STANDARD_SHOW_6, :WTA_1, :WTA_2, :WTA_3, :WTA_4, :WTA_5, :BETS_VALUE;

  TOTAL_VALUE = coalesce(PRIZE_TOTAL, 0) + coalesce(BETS_VALUE, 0);
  
  suspend;
end ^

ALTER PROCEDURE WINNER_PAYOUT_GET (ID_EVENT INTEGER)
RETURNS (ID_EVENT_INVENTORY INTEGER,
ID_EVENT_INVENTORY_ITEM INTEGER,
CAPITAL_VALUE NUMERIC(15, 4),
HOT_SPOT_1_VALUE NUMERIC(15, 4),
HOT_SPOT_2_VALUE NUMERIC(15, 4),
HOT_SPOT_3_VALUE NUMERIC(15, 4),
AVG_SPEED_WINNER_VALUE NUMERIC(15, 4),
BELGIAN_SHOW_1 NUMERIC(15, 4),
BELGIAN_SHOW_2 NUMERIC(15, 4),
BELGIAN_SHOW_3 NUMERIC(15, 4),
BELGIAN_SHOW_4 NUMERIC(15, 4),
BELGIAN_SHOW_5 NUMERIC(15, 4),
BELGIAN_SHOW_6 NUMERIC(15, 4),
BELGIAN_SHOW_7 NUMERIC(15, 4),
STANDARD_SHOW_1 NUMERIC(15, 4),
STANDARD_SHOW_2 NUMERIC(15, 4),
STANDARD_SHOW_3 NUMERIC(15, 4),
STANDARD_SHOW_4 NUMERIC(15, 4),
STANDARD_SHOW_5 NUMERIC(15, 4),
STANDARD_SHOW_6 NUMERIC(15, 4),
WTA_1 NUMERIC(15, 4),
WTA_2 NUMERIC(15, 4),
WTA_3 NUMERIC(15, 4),
WTA_4 NUMERIC(15, 4),
WTA_5 NUMERIC(15, 4),
BETS_VALUE NUMERIC(15, 4),
TOTAL_VALUE NUMERIC(15, 4))
AS 
declare variable EXEC_TIME timestamp;
begin
  execute procedure TMP_BETS_BY_EVENT_INSERT(:ID_EVENT)
  returning_values :EXEC_TIME;

  for select ppg.ID_EVENT_INVENTORY, ppg.ID_EVENT_INVENTORY_ITEM, 
    ppg.CAPITAL_VALUE, ppg.HOT_SPOT_1_VALUE, ppg.HOT_SPOT_2_VALUE, ppg.HOT_SPOT_3_VALUE, ppg.AVG_SPEED_WINNER_VALUE,
    rbc.BELGIAN_SHOW_1, rbc.BELGIAN_SHOW_2, rbc.BELGIAN_SHOW_3, rbc.BELGIAN_SHOW_4,
    rbc.BELGIAN_SHOW_5, rbc.BELGIAN_SHOW_6, rbc.BELGIAN_SHOW_7, rbc.STANDARD_SHOW_1,
    rbc.STANDARD_SHOW_2, rbc.STANDARD_SHOW_3, rbc.STANDARD_SHOW_4, rbc.STANDARD_SHOW_5,
    rbc.STANDARD_SHOW_6, rbc.WTA_1, rbc.WTA_2, rbc.WTA_3, rbc.WTA_4, rbc.WTA_5, rbc.TOTAL,
    ppg.PRIZE_TOTAL + coalesce(rbc.TOTAL, 0)
    from WINNER_PRIZE_PAYOUT_GET(:ID_EVENT) ppg
    left join TMP_BETS rbc on rbc.ID_RACE_ITEM = ppg.ID_FINAL_RACE_ITEM and rbc.EXEC_TIME = :EXEC_TIME
    into :ID_EVENT_INVENTORY, :ID_EVENT_INVENTORY_ITEM, 
      :CAPITAL_VALUE, :HOT_SPOT_1_VALUE, :HOT_SPOT_2_VALUE, :HOT_SPOT_3_VALUE, :AVG_SPEED_WINNER_VALUE,
      :BELGIAN_SHOW_1, :BELGIAN_SHOW_2, :BELGIAN_SHOW_3, :BELGIAN_SHOW_4,
      :BELGIAN_SHOW_5, :BELGIAN_SHOW_6, :BELGIAN_SHOW_7, :STANDARD_SHOW_1,
      :STANDARD_SHOW_2, :STANDARD_SHOW_3, :STANDARD_SHOW_4, :STANDARD_SHOW_5,
      :STANDARD_SHOW_6, :WTA_1, :WTA_2, :WTA_3, :WTA_4, :WTA_5, :BETS_VALUE, :TOTAL_VALUE
  do begin
    suspend;
  end
  
  delete from TMP_BETS tb where tb.EXEC_TIME = :EXEC_TIME;
end ^

ALTER PROCEDURE WINNER_PRIZE_PAYOUT_BIRD_GET (ID_EVENT_INVENTORY_ITEM INTEGER)
RETURNS (ID_FINAL_RACE_ITEM INTEGER,
CAPITAL_VALUE NUMERIC(15, 4),
HOT_SPOT_1_VALUE NUMERIC(15, 4),
HOT_SPOT_2_VALUE NUMERIC(15, 4),
HOT_SPOT_3_VALUE NUMERIC(15, 4),
AVG_SPEED_WINNER_VALUE NUMERIC(15, 4),
PRIZE_TOTAL NUMERIC(15, 4))
AS 
begin
  -- initalize
  CAPITAL_VALUE = null;
  HOT_SPOT_1_VALUE = null;
  HOT_SPOT_2_VALUE = null;
  AVG_SPEED_WINNER_VALUE = null;
  ID_FINAL_RACE_ITEM = null;

  -- capital
  select ri.ID_RACE_ITEM, rir.PRIZE_VALUE
    from RACE r
    join RACE_ITEM ri on ri.ID_RACE = r.ID_RACE
    join RACE_ITEM_RESULT rir on rir.ID_RACE_ITEM = ri.ID_RACE_ITEM
    where r.ID_RACE_TYPE = 5 /* finl race */ and ri.ID_INVENTORY_ITEM = :ID_EVENT_INVENTORY_ITEM
    into :ID_FINAL_RACE_ITEM, :CAPITAL_VALUE;

  -- hot spot 1
  select rir.PRIZE_VALUE
    from RACE r
    join RACE_ITEM ri on ri.ID_RACE = r.ID_RACE
    join RACE_ITEM_RESULT rir on rir.ID_RACE_ITEM = ri.ID_RACE_ITEM
    where r.ID_RACE_TYPE = 6 /* hot spot 1 */ and ri.ID_INVENTORY_ITEM = :ID_EVENT_INVENTORY_ITEM
    into :HOT_SPOT_1_VALUE;
    
  -- hot spot 2
  select rir.PRIZE_VALUE
    from RACE r
    join RACE_ITEM ri on ri.ID_RACE = r.ID_RACE
    join RACE_ITEM_RESULT rir on rir.ID_RACE_ITEM = ri.ID_RACE_ITEM
    where r.ID_RACE_TYPE = 7 /* hot spot 2 */ and ri.ID_INVENTORY_ITEM = :ID_EVENT_INVENTORY_ITEM
    into :HOT_SPOT_2_VALUE;

  -- hot spot 3
  select rir.PRIZE_VALUE
    from RACE r
    join RACE_ITEM ri on ri.ID_RACE = r.ID_RACE
    join RACE_ITEM_RESULT rir on rir.ID_RACE_ITEM = ri.ID_RACE_ITEM
    where r.ID_RACE_TYPE = 8 /* hot spot 3 */ and ri.ID_INVENTORY_ITEM = :ID_EVENT_INVENTORY_ITEM
    into :HOT_SPOT_3_VALUE;

  -- avg speed winer
  select awp.PRIZE_VALUE
    from AVG_WINNER_PRIZES awp
    where awp.ID_EVENT_INVENTORY_ITEM = :ID_EVENT_INVENTORY_ITEM
  into :AVG_SPEED_WINNER_VALUE;

  PRIZE_TOTAL = coalesce(CAPITAL_VALUE, 0)
    + coalesce(HOT_SPOT_1_VALUE, 0)
    + coalesce(HOT_SPOT_2_VALUE, 0)
    + coalesce(AVG_SPEED_WINNER_VALUE, 0);

  suspend;
end ^

ALTER PROCEDURE WINNER_PRIZE_PAYOUT_GET (ID_EVENT INTEGER,
IN_ID_EVENT_INVENTORY INTEGER = null)
RETURNS (ID_EVENT_INVENTORY INTEGER,
ID_EVENT_INVENTORY_ITEM INTEGER,
ID_FINAL_RACE_ITEM INTEGER,
CAPITAL_VALUE NUMERIC(15, 4),
HOT_SPOT_1_VALUE NUMERIC(15, 4),
HOT_SPOT_2_VALUE NUMERIC(15, 4),
HOT_SPOT_3_VALUE NUMERIC(15, 4),
AVG_SPEED_WINNER_VALUE NUMERIC(15, 4),
PRIZE_TOTAL NUMERIC(15, 4))
AS 
begin
  for select ei.ID_EVENT_INVENTORY, eii.ID_EVENT_INVENTORY_ITEM
    from EVENT_INVENTORY ei
    join EVENT_INVENTORY_ITEM eii on eii.ID_EVENT_INVENTORY = ei.ID_EVENT_INVENTORY
    join BIRDS b on b.ID_BIRD = eii.ID_BIRD
    where (ei.ID_EVENT = :ID_EVENT)
      and ((:IN_ID_EVENT_INVENTORY is null) or (ei.ID_EVENT_INVENTORY = :IN_ID_EVENT_INVENTORY))
    into :ID_EVENT_INVENTORY, :ID_EVENT_INVENTORY_ITEM
  do begin
    execute procedure WINNER_PRIZE_PAYOUT_BIRD_GET(:ID_EVENT_INVENTORY_ITEM)
    returning_values :ID_FINAL_RACE_ITEM, :CAPITAL_VALUE, :HOT_SPOT_1_VALUE, :HOT_SPOT_2_VALUE, :HOT_SPOT_3_VALUE,
      :AVG_SPEED_WINNER_VALUE, :PRIZE_TOTAL;
    suspend;
  end
end ^
