COMMIT WORK ;
SET AUTODDL ON;
SET TERM ^ ;

/* Triggers only will work for SQL triggers */
CREATE TRIGGER BIRDS_AD FOR BIRDS 
ACTIVE AFTER DELETE POSITION 0 
AS
begin
  delete from PICTURE p
    where p.ID_PICTURE = old.ID_PICTURE;
end ^

CREATE TRIGGER DATASYNC_WEB_ID FOR DATASYNC_WEB 
ACTIVE BEFORE INSERT POSITION 0 
AS
begin
  if ( (new.ID is null) or (new.ID = 0) )
  then new.ID = gen_id(DATASYNC_WEB_GEN, 1);
end ^

CREATE TRIGGER EVENT_INVENTORY_UDI FOR EVENT_INVENTORY 
ACTIVE AFTER INSERT OR UPDATE OR DELETE POSITION 0 
AS
DECLARE VARIABLE cQUOTECHAR VARCHAR(1);
DECLARE VARIABLE cCOMMACHAR VARCHAR(1);
DECLARE VARIABLE ROWVALS BLOB SUB_TYPE 1;

begin
  /* code */                               

  cQUOTECHAR = '"';   
  cCOMMACHAR = ',' ;
  
  IF (INSERTING ) THEN
       BEGIN                          
               ROWVALS = cQUOTECHAR ||  NEW. ID_EVENT_INVENTORY || cQUOTECHAR || cCOMMACHAR ||
                                     cQUOTECHAR ||   NEW.ID_EVENT || cQUOTECHAR || cCOMMACHAR ||
                                    cQUOTECHAR ||   NEW.ID_BREEDER || cQUOTECHAR || cCOMMACHAR ||
                                   cQUOTECHAR ||    CASE WHEN NEW.SIGN_IN_DATE  IS NULL THEN 'NULL' ELSE NEW.SIGN_IN_DATE  END || cQUOTECHAR || cCOMMACHAR ||
                                    cQUOTECHAR ||   CASE WHEN NEW.WAITING_DATE IS NULL THEN 'NULL' ELSE NEW.WAITING_DATE  END || cQUOTECHAR || cCOMMACHAR ||
                                    cQUOTECHAR ||   NEW.IS_WAITING || cQUOTECHAR || cCOMMACHAR ||
                                    cQUOTECHAR ||   NEW.RESERVED_BIRDS || cQUOTECHAR || cCOMMACHAR ||
                                   cQUOTECHAR ||   NEW.LOFT || cQUOTECHAR || cCOMMACHAR ||
                                    cQUOTECHAR ||   NEW.NOTE || cQUOTECHAR ;  
       
                 INSERT INTO DATASYNC_WEB
                  (
                      PROCESSED,
                    DBTABLE,
                    DBOPERATION,
                    DBTABLEIDCOLNAME,
                    DBTABLEROWID,
                    DBTABLEROW
                  )
                  VALUES
                  (
                     0, 'EVENT_INVENTORY', 'I', 'ID_EVENT_INVENTORY', NEW.ID_EVENT_INVENTORY, :ROWVALS 
                  ) ;
       END
  ELSE IF (UPDATING ) THEN 
       BEGIN
                ROWVALS = cQUOTECHAR ||  NEW. ID_EVENT_INVENTORY || cQUOTECHAR || cCOMMACHAR ||
                                     cQUOTECHAR ||   NEW.ID_EVENT || cQUOTECHAR || cCOMMACHAR ||
                                    cQUOTECHAR ||   NEW.ID_BREEDER || cQUOTECHAR || cCOMMACHAR ||
                                    cQUOTECHAR ||    CASE WHEN NEW.SIGN_IN_DATE  IS NULL THEN 'NULL' ELSE NEW.SIGN_IN_DATE  END || cQUOTECHAR || cCOMMACHAR ||
                                    cQUOTECHAR ||   CASE WHEN NEW.WAITING_DATE IS NULL THEN 'NULL' ELSE NEW.WAITING_DATE  END || cQUOTECHAR || cCOMMACHAR ||
                                    cQUOTECHAR ||   NEW.IS_WAITING || cQUOTECHAR || cCOMMACHAR ||
                                    cQUOTECHAR ||   NEW.RESERVED_BIRDS || cQUOTECHAR || cCOMMACHAR ||
                                   cQUOTECHAR ||   NEW.LOFT || cQUOTECHAR || cCOMMACHAR ||
                                    cQUOTECHAR ||   NEW.NOTE || cQUOTECHAR ;  
    
                     INSERT INTO DATASYNC_WEB
                   (
                      PROCESSED,
                    DBTABLE,
                    DBOPERATION,
                    DBTABLEIDCOLNAME,
                    DBTABLEROWID,
                    DBTABLEROW
                  )
                  VALUES
                  (
                     0, 'EVENT_INVENTORY', 'U', 'ID_EVENT_INVENTORY', OLD.ID_EVENT_INVENTORY, :ROWVALS 
                  ) ;
       END
  ELSE IF (DELETING ) THEN
       BEGIN
                 INSERT INTO DATASYNC_WEB
                  (
                      PROCESSED,
                    DBTABLE,
                    DBOPERATION,
                    DBTABLEIDCOLNAME,
                    DBTABLEROWID
                  )
                  VALUES
                  (
                     0, 'EVENT_INVENTORY', 'D', 'ID_EVENT_INVENTORY', OLD.ID_EVENT_INVENTORY
                  ) ;
       END
  
end ^

