/* Comments for database objects. */
COMMENT ON    COLUMN    BIRDS.SEX IS '0 male
1 female
2 not available';
COMMENT ON    COLUMN    BIRDS.LOST_ID_RACE IS 'The ID of the lost race
or lost code
9999 - died
8888 - injured
7777 - pmv';
COMMENT ON    COLUMN    BREEDERS.STATUS IS '0 active
1 inactive';
COMMENT ON    COLUMN    EVENTS.EVENT_TYPE IS '0 = AGN
1 = AS';
COMMENT ON    COLUMN    PAYMENTS.PAYMENT_TYPE IS '0 - perch fee payment
1 - entry fee payment
2 - bets payment
3 - hot spot payment
4 - entry fee refund
5 - bets refund
6 - hot spot refund
7 - transfer due
8 - winner payout';
COMMENT ON    COLUMN    PAYMENTS.PAYMENT_METHOD IS '0 = CASH
1 = CHECK
2 = MONEY ORDER
3 = CREDIT CARD
4 = OTHER';
COMMENT ON    COLUMN    SYSTEM_REQUIREMENTS."MODULE_NAME" IS 'the module identifier on which the database depends';
COMMENT ON    COLUMN    SYSTEM_REQUIREMENTS.REQUIRED_VERSION IS 'the version of the module on which the database depends';
COMMENT ON TABLE        SYSTEM_SESSION IS 'this table contains connection variables';
COMMENT ON TABLE        SYSTEM_UPDATES IS 'this table contains update history
it''s last record (max(ID_SYSTEM_UPDATE)) is the current version of the product modules';
COMMENT ON EXTERNAL FUNCTION ASCII_CHAR IS '';
COMMENT ON EXTERNAL FUNCTION F_REPLSTR IS '';
COMMENT ON EXTERNAL FUNCTION TRUNCATE IS '';
